'use client';

import { ArrowLeft, ArrowRight, Globe, Lock, RotateCw } from 'lucide-react';
import * as React from 'react';

import { Button } from '@/components/ui/button';
import { InputGroup, InputGroupAddon, InputGroupInput } from '@/components/ui/input-group';
import { EmptyState } from '@/components/ui/workspace-kit/surface';
import { TooltipIconButton } from '@/components/ui/workspace-kit/primitives';
import { DEMO_QUICK_LINKS, renderDemoPage } from '@/components/ui/coding-agent/demo-browser';
import type { BrowserPageRenderer } from '@/components/ui/coding-agent/types';

/** One browser tab: where it is, where it's been, and the page's title when the agent or host knows it. */
export type BrowserTabState = { url: string | null; title?: string; history: string[]; index: number; reloads: number };

export function browserTab(url: string | null, title?: string): BrowserTabState {
	return { url, title, history: url ? [url] : [], index: url ? 0 : -1, reloads: 0 };
}

export function navigate(tab: BrowserTabState, url: string, title?: string): BrowserTabState {
	const history = [...tab.history.slice(0, tab.index + 1), url];
	return { ...tab, url, title, history, index: history.length - 1 };
}

export function step(tab: BrowserTabState, by: -1 | 1): BrowserTabState {
	const index = Math.min(Math.max(tab.index + by, 0), tab.history.length - 1);
	return { ...tab, index, url: tab.history[index] ?? null, title: undefined };
}

/** "localhost:3000/login" → "http://localhost:3000/login"; bare words become a search. */
function toUrl(input: string) {
	const value = input.trim();
	if (!value) return null;
	if (/^[a-z]+:\/\//i.test(value)) return value;
	const local = /^(localhost|127\.0\.0\.1|\[::1\])(:\d+)?(\/|$)/i.test(value);
	if (local || /^[\w-]+(\.[\w-]+)+(:\d+)?(\/|$)/.test(value)) {
		return `${local ? 'http' : 'https'}://${local ? value.replace(/^localhost/i, 'localhost') : value}`;
	}
	return `https://search.example/?q=${encodeURIComponent(value)}`;
}

function hostOf(url: string) {
	try {
		return new URL(url).host;
	} catch {
		return url;
	}
}

export function displayUrl(url: string) {
	return url.replace(/^https?:\/\//, '');
}

/**
 * A tab title for a page that hasn't given one: its last path segment as words ("/settings/team" reads "Team"), or
 * its host for a site's front page.
 */
export function pageTitle(url: string) {
	try {
		const { host, pathname } = new URL(url);
		const page = pathname.split('/').filter(Boolean).pop();
		return page ? `${page.charAt(0).toUpperCase()}${page.slice(1).replace(/[-_]/g, ' ')}` : host;
	} catch {
		return url;
	}
}

/**
 * A browser tab inside the side panel: history, reload, an address bar, and a page area. The page comes from the
 * host's renderer, or without one from the bundled demo app's preview; a page the renderer returns null for shows a
 * note that it can't be shown here.
 */
export function BrowserPanel({
	tab,
	onChange,
	renderPage
}: {
	tab: BrowserTabState;
	onChange: (tab: BrowserTabState) => void;
	renderPage?: BrowserPageRenderer;
}) {
	const [draft, setDraft] = React.useState(tab.url ? displayUrl(tab.url) : '');
	// A new, empty tab is for typing an address, so the address bar takes focus.
	React.useEffect(() => {
		if (!tab.url) inputRef.current?.focus();
		// eslint-disable-next-line react-hooks/exhaustive-deps
	}, []);
	const [loading, setLoading] = React.useState(false);
	const inputRef = React.useRef<HTMLInputElement>(null);

	React.useEffect(() => {
		setDraft(tab.url ? displayUrl(tab.url) : '');
		if (!tab.url) return;
		setLoading(true);
		const timer = window.setTimeout(() => setLoading(false), 450);
		return () => window.clearTimeout(timer);
	}, [tab.url, tab.reloads]);

	const go = (input: string) => {
		const url = toUrl(input);
		if (url) onChange(navigate(tab, url));
		inputRef.current?.blur();
	};

	// The host's renderer runs once per address or reload, not on every render of the session around it.
	const page = React.useMemo(() => (tab.url ? (renderPage ?? renderDemoPage)(tab.url) : null), [renderPage, tab.url]);
	// The shortcuts point at the demo app's pages, so a host with its own renderer doesn't get them.
	const quickLinks = renderPage ? [] : DEMO_QUICK_LINKS;
	const secure = tab.url?.startsWith('https://');

	return (
		<div className="flex h-full min-h-0 flex-col">
			{/* The page below is someone else's surface, so the browser's own controls end at a rule. */}
			<div className="flex h-10 shrink-0 items-center gap-1 border-b border-border px-2">
				<TooltipIconButton label="Back" size="sm" disabled={tab.index <= 0} onClick={() => onChange(step(tab, -1))}>
					<ArrowLeft aria-hidden="true" className="size-3.5 rtl:-scale-x-100" />
				</TooltipIconButton>
				<TooltipIconButton label="Forward" size="sm" disabled={tab.index >= tab.history.length - 1} onClick={() => onChange(step(tab, 1))}>
					<ArrowRight aria-hidden="true" className="size-3.5 rtl:-scale-x-100" />
				</TooltipIconButton>
				<TooltipIconButton label="Reload" size="sm" disabled={!tab.url} onClick={() => onChange({ ...tab, reloads: tab.reloads + 1 })}>
					<RotateCw aria-hidden="true" className="size-3.5" />
				</TooltipIconButton>
				<form
					className="ms-1 min-w-0 flex-1"
					onSubmit={(event) => {
						event.preventDefault();
						go(draft);
					}}
				>
					<InputGroup className="h-7 rounded-md border-transparent bg-muted shadow-none dark:bg-muted">
						<InputGroupAddon className="text-muted-foreground">
							{secure ? <Lock aria-hidden="true" className="size-3.5" /> : <Globe aria-hidden="true" className="size-3.5" />}
						</InputGroupAddon>
						<InputGroupInput
							ref={inputRef}
							dir="ltr"
							size="sm"
							aria-label="Address"
							placeholder="Search or enter a URL"
							value={draft}
							onChange={(event) => setDraft(event.target.value)}
							onFocus={(event) => event.target.select()}
							className="text-xs"
						/>
					</InputGroup>
				</form>
			</div>
			<div className="relative min-h-0 flex-1 overflow-auto">
				{loading ? <div aria-hidden="true" className="absolute inset-x-0 top-0 z-10 h-0.5 animate-pulse bg-primary" /> : null}
				{!tab.url ? (
					<div className="grid h-full place-items-center">
						<EmptyState
							icon={Globe}
							title="Open a page"
							description="Preview your app, read docs, or browse the web."
							action={
								quickLinks.length > 0 ? (
									<div className="flex flex-wrap justify-center gap-1.5">
										{quickLinks.map((link) => (
											<Button key={link} size="xs" variant="outline" className="font-mono" onClick={() => go(link)}>
												{link}
											</Button>
										))}
									</div>
								) : undefined
							}
						/>
					</div>
				) : page ? (
					<div key={`${tab.url}-${tab.reloads}`} className="h-full">
						{page}
					</div>
				) : (
					<div className="grid h-full place-items-center">
						<EmptyState
							icon={Globe}
							title="This page can’t be previewed here"
							description={<span className="[overflow-wrap:anywhere]">{hostOf(tab.url)} opens outside the preview, in a real browser.</span>}
						/>
					</div>
				)}
			</div>
		</div>
	);
}

'use client';

import * as React from 'react';

export type ColorScheme = 'light' | 'dark';

/**
 * The diff and tree renderers draw inside shadow roots, so Tailwind classes never reach them. They do inherit CSS
 * custom properties from their host, so these maps hand our tokens to the renderers' override variables. Colors
 * stay `var()` references, which keeps both themes (and any host re-theme) working without re-rendering.
 */
export const DIFF_SURFACE_STYLE = {
	'--diffs-font-family': 'var(--font-mono)',
	'--diffs-header-font-family': 'var(--font-sans)',
	'--diffs-font-size': '12px',
	'--diffs-line-height': '20px',
	'--diffs-light-bg': 'var(--background)',
	'--diffs-dark-bg': 'var(--background)',
	'--diffs-bg-context-override': 'var(--background)',
	'--diffs-bg-buffer-override': 'var(--background)',
	// Folded context reads as a faint band, a step off the page rather than a block.
	'--diffs-bg-separator-override': 'color-mix(in oklab, var(--foreground) 3.5%, var(--background))',
	'--diffs-fg-number-override': 'color-mix(in oklab, var(--muted-foreground) 70%, transparent)',
	// Added and removed lines tint from these bases at the renderer's own strengths.
	'--diffs-addition-color-override': 'var(--success)',
	'--diffs-deletion-color-override': 'var(--destructive)',
	'--diffs-modified-color-override': 'var(--warning)',
	// Selection is primary, so it can't be mistaken for a modified line.
	'--diffs-bg-selection-override': 'color-mix(in oklab, var(--primary) 14%, var(--background))',
	'--diffs-bg-selection-number-override': 'color-mix(in oklab, var(--primary) 22%, var(--background))',
	'--diffs-selection-color-override': 'var(--primary)',
	// Tints run the full width of a line; the reserved scrollbar gutter left them short.
	'--diffs-scrollbar-gutter-override': '0px'
} as React.CSSProperties;

/**
 * Styles the renderer can't take as variables. The gutter's "add a comment" button is primary like the template's
 * other actions, and folded context is a slim 24px band in 11px type, flush with the code, that unfolds on click.
 */
export const DIFF_UNSAFE_CSS = [
	'[data-utility-button]{background:var(--primary);color:var(--primary-foreground)}',
	'[data-separator=line-info-basic]{height:24px}',
	'[data-separator=line-info-basic] [data-separator-content]{font-size:11px;letter-spacing:0;padding-inline:1.5ch}',
	'[data-separator=line-info-basic] [data-separator-content]:hover{color:var(--diffs-fg);text-decoration:none}'
].join('');

export const TREE_SURFACE_STYLE = {
	'--trees-font-family-override': 'var(--font-sans)',
	'--trees-font-size-override': '13px',
	// Opaque, not transparent: the tree's ellipsis marker covers overflowing text by painting this colour over it.
	'--trees-bg-override': 'color-mix(in oklab, var(--foreground) 2.5%, var(--background))',
	'--trees-fg-override': 'var(--foreground)',
	'--trees-fg-muted-override': 'var(--muted-foreground)',
	'--trees-bg-muted-override': 'color-mix(in oklab, var(--foreground) 5%, transparent)',
	'--trees-border-color-override': 'var(--border)',
	'--trees-accent-override': 'var(--primary)',
	'--trees-focus-ring-color-override': 'var(--ring)',
	'--trees-selected-bg-override': 'color-mix(in oklab, var(--foreground) 8%, transparent)',
	'--trees-selected-fg-override': 'var(--foreground)',
	'--trees-selected-focused-border-color-override': 'transparent',
	'--trees-search-bg-override': 'var(--muted)',
	'--trees-search-fg-override': 'var(--foreground)',
	'--trees-input-bg-override': 'var(--muted)',
	'--trees-indent-guide-bg-override': 'var(--border)',
	'--trees-border-radius-override': 'calc(var(--radius) - 4px)',
	'--trees-git-added-color-override': 'var(--success)',
	'--trees-git-untracked-color-override': 'var(--success)',
	'--trees-git-modified-color-override': 'var(--warning)',
	'--trees-git-renamed-color-override': 'var(--info)',
	'--trees-git-deleted-color-override': 'var(--destructive)',
	'--trees-git-ignored-color-override': 'var(--muted-foreground)'
} as React.CSSProperties;

/** The file tree column's tone: a step off the page, so it reads as its own column without a dividing rule. */
export const TREE_COLUMN_BG = 'color-mix(in oklab, var(--foreground) 2.5%, var(--background))';

/** Syntax themes for the diff and file renderers; the pair is picked by `colorScheme`. */
export const CODE_THEMES = { light: 'pierre-light', dark: 'pierre-dark' } as const;

function schemeOf(node: Element | null): ColorScheme {
	return node?.closest('.dark') ? 'dark' : 'light';
}

/**
 * Follows the nearest `.dark` ancestor of `ref`, so code surfaces match a class-based theme (the renderers would
 * otherwise follow the OS). Watches the root element's class for theme toggles.
 */
export function useColorScheme(ref: React.RefObject<Element | null>): ColorScheme {
	const [scheme, setScheme] = React.useState<ColorScheme>('light');
	React.useLayoutEffect(() => {
		const sync = () => setScheme(schemeOf(ref.current));
		sync();
		const observer = new MutationObserver(sync);
		observer.observe(document.documentElement, { attributes: true, attributeFilter: ['class'] });
		return () => observer.disconnect();
	}, [ref]);
	return scheme;
}

'use client';

import * as React from 'react';

import type {
	BrowserPageRenderer,
	CodingAgentAction,
	CodingAgentData,
	CodingAgentLayout,
	CodingProject,
	CodingSession,
	SessionPatch,
	WorkspaceLocation
} from '@/components/ui/coding-agent/types';

/** A session as the shell sees it: the script plus whatever its live run has reported. */
export type LiveSession = CodingSession & SessionPatch & { draft?: boolean };

/** Commands the active session exposes to shortcuts and the command menu. */
export type SessionHandle = {
	togglePanel: () => void;
	toggleTerminal: () => void;
	toggleTree: () => void;
	openBrowser: () => void;
	openReview: () => void;
	openFilePicker: () => void;
};

export type CodingAgentContextValue = {
	data: CodingAgentData;
	layout: CodingAgentLayout;
	setLayout: (layout: CodingAgentLayout) => void;
	sessions: LiveSession[];
	session: (id: string) => LiveSession | undefined;
	project: (id: string) => CodingProject;
	openIds: string[];
	/** The session in front, or null while the home list shows. */
	activeId: string | null;
	recentlyClosed: string[];
	activate: (id: string) => void;
	goHome: () => void;
	newSession: () => void;
	closeSession: (id: string) => void;
	/** Removes a session for good, after the person confirmed it. */
	deleteSession: (id: string) => void;
	reopenClosed: (id?: string) => void;
	patchSession: (id: string, patch: SessionPatch) => void;
	startSession: (id: string, start: { text: string; projectId: string; location: WorkspaceLocation }) => void;
	emit: (action: CodingAgentAction) => void;
	renderBrowserPage?: BrowserPageRenderer;
	/** The active session registers its handle here so shell-level shortcuts reach it. */
	activeHandle: React.RefObject<SessionHandle | null>;
	openCommandMenu: () => void;
	/** A session whose title should switch to its rename field, from F2 or the command menu. */
	renaming: string | null;
	setRenaming: (id: string | null) => void;
	/** Which agent a session shows: its own (undefined) or one of the agents it started. */
	viewRun: (sessionId: string) => string | undefined;
	openRun: (sessionId: string, runId: string | undefined) => void;
};

/**
 * The part of the shell a session needs, none of which changes while sessions run. Kept apart from the live list, so
 * one session reporting its progress doesn't re-render every other session.
 */
export type SessionShellValue = Pick<
	CodingAgentContextValue,
	'data' | 'layout' | 'project' | 'patchSession' | 'emit' | 'activeHandle' | 'renderBrowserPage' | 'deleteSession' | 'openRun'
>;

const CodingAgentContext = React.createContext<CodingAgentContextValue | null>(null);
const SessionShellContext = React.createContext<SessionShellValue | null>(null);

export function useCodingAgent() {
	const context = React.useContext(CodingAgentContext);
	if (!context) throw new Error('useCodingAgent must be used inside <CodingAgent>.');
	return context;
}

export function useSessionShell() {
	const context = React.useContext(SessionShellContext);
	if (!context) throw new Error('useSessionShell must be used inside <CodingAgent>.');
	return context;
}

export { CodingAgentContext, SessionShellContext };

'use client';

import * as React from 'react';

import { useControllableState } from '@/hooks/use-controllable-state';
import { NavMenuButton } from '@/components/ui/workspace-kit/primitives';
import { WorkspaceShell } from '@/components/ui/workspace-kit/shell';
import { useLatest } from '@/components/ui/workspace-kit/use-latest';
import { CodingAgentContext, type CodingAgentContextValue, type LiveSession, type SessionHandle, SessionShellContext, type SessionShellValue } from '@/components/ui/coding-agent/coding-agent-context';
import { CommandMenu } from '@/components/ui/coding-agent/command-menu';
import { HomeView } from '@/components/ui/coding-agent/home-view';
import { NewSession } from '@/components/ui/coding-agent/new-session';
import { SessionSidebar } from '@/components/ui/coding-agent/session-sidebar';
import { SessionTabs } from '@/components/ui/coding-agent/session-tabs';
import { SessionView } from '@/components/ui/coding-agent/session-view';
import { matches, SHORTCUTS } from '@/components/ui/coding-agent/shortcuts';
import { withoutAndNeighbor } from '@/components/ui/coding-agent/tab-strip';
import type {
	BrowserPageRenderer,
	CodingAgentAction,
	CodingAgentData,
	CodingAgentLayout,
	CodingSession,
	SessionPatch
} from '@/components/ui/coding-agent/types';

export type CodingAgentProps = {
	data: CodingAgentData;
	/** Sessions as a tab strip across the top (default) or a sidebar grouped by project. */
	layout?: CodingAgentLayout;
	defaultLayout?: CodingAgentLayout;
	onLayoutChange?: (layout: CodingAgentLayout) => void;
	/** The session in front on first render; defaults to the first open one. */
	defaultActiveSessionId?: string;
	/** Whether sessions open with the side panel showing. Defaults to true. */
	defaultPanelOpen?: boolean;
	/** Whether sessions open with the terminal dock showing. */
	defaultTerminalOpen?: boolean;
	/** Draws the page in a browser panel tab. Defaults to a preview of the demo app. */
	renderBrowserPage?: BrowserPageRenderer;
	onAction?: (action: CodingAgentAction) => void;
	/** Sits the workspace in a rounded frame, for hosts that show it as an app window. */
	framed?: boolean;
	className?: string;
};

/** A first sentence, trimmed to fit a tab, becomes a new session's title. */
function titleFrom(text: string) {
	const first = text.split(/(?<=[.?!])\s|\n/)[0].trim();
	return first.length > 48 ? `${first.slice(0, 47).trimEnd()}…` : first;
}

function sameRuns(a: SessionPatch['runs'], b: SessionPatch['runs']) {
	if (a === b) return true;
	if (!a || !b || a.length !== b.length) return false;
	return a.every((run, index) => {
		const other = b[index];
		return run.id === other.id && run.name === other.name && run.status === other.status && run.depth === other.depth && run.parentRunId === other.parentRunId;
	});
}

/** Whether a patch would change nothing, so a session reporting the same state twice doesn't re-render the shell. */
function samePatch(current: SessionPatch | undefined, patch: SessionPatch) {
	return Object.entries(patch).every(([key, value]) =>
		key === 'runs' ? sameRuns(current?.runs, value as SessionPatch['runs']) : current?.[key as keyof SessionPatch] === value
	);
}

let draftCounter = 0;

/**
 * A coding agent workspace. Sessions sit in a tab strip (or a sidebar), each with a chat column, a resizable side
 * panel for reviewing diffs, reading files and previewing the app in a browser tab, and a terminal dock. Every open
 * session keeps running in the background and marks its tab when it needs you or has something new.
 */
export function CodingAgent({
	data,
	layout: layoutProp,
	defaultLayout = 'tabs',
	onLayoutChange,
	defaultActiveSessionId,
	defaultPanelOpen = true,
	defaultTerminalOpen = false,
	renderBrowserPage,
	onAction,
	framed = false,
	className
}: CodingAgentProps) {
	const [layout, setLayoutState] = useControllableState<CodingAgentLayout>({ prop: layoutProp, defaultProp: defaultLayout, onChange: onLayoutChange });
	// With nothing open, the workspace starts on a fresh session, ready to type into.
	const [created, setCreated] = React.useState<(CodingSession & { draft?: boolean })[]>(() =>
		data.openSessionIds.length === 0 ? [{ id: 'draft-0', title: 'New session', projectId: data.projects[0].id, script: [], draft: true }] : []
	);
	const [patches, setPatches] = React.useState<Record<string, SessionPatch>>({});
	const [openIds, setOpenIds] = React.useState(() => (data.openSessionIds.length === 0 ? ['draft-0'] : data.openSessionIds));
	const [activeId, setActiveId] = React.useState<string | null>(() => defaultActiveSessionId ?? (data.openSessionIds[0] ?? 'draft-0'));
	const [recentlyClosed, setRecentlyClosed] = React.useState<string[]>([]);
	const [commandOpen, setCommandOpen] = React.useState(false);
	const [renaming, setRenaming] = React.useState<string | null>(null);
	const [deleted, setDeleted] = React.useState<string[]>([]);
	const [viewRuns, setViewRuns] = React.useState<Record<string, string | undefined>>({});
	const openRun = React.useCallback((sessionId: string, runId: string | undefined) => {
		setViewRuns((current) => (current[sessionId] === runId ? current : { ...current, [sessionId]: runId }));
	}, []);
	const activeHandle = React.useRef<SessionHandle | null>(null);
	const root = React.useRef<HTMLDivElement>(null);
	const onActionRef = useLatest(onAction);
	const emit = React.useCallback((action: CodingAgentAction) => onActionRef.current?.(action), [onActionRef]);

	// Each live session keeps its identity until its own data or patch changes, so a memoized session view only
	// re-renders for its own updates.
	const merged = React.useRef(new Map<string, { base: CodingSession; patch: SessionPatch | undefined; live: LiveSession }>());
	const sessions = React.useMemo<LiveSession[]>(() => {
		const replaced = new Set(created.map((session) => session.id));
		const removed = new Set(deleted);
		const next = new Map<string, { base: CodingSession; patch: SessionPatch | undefined; live: LiveSession }>();
		const list = [...data.sessions.filter((session) => !replaced.has(session.id)), ...created]
			.filter((session) => !removed.has(session.id))
			.map((session) => {
				const patch = patches[session.id];
				const cached = merged.current.get(session.id);
				const live = cached && cached.base === session && cached.patch === patch ? cached.live : { ...session, ...patch };
				next.set(session.id, { base: session, patch, live });
				return live;
			});
		merged.current = next;
		return list;
	}, [created, data.sessions, deleted, patches]);
	const sessionById = React.useMemo(() => new Map(sessions.map((session) => [session.id, session])), [sessions]);
	const projectById = React.useMemo(() => new Map(data.projects.map((project) => [project.id, project])), [data.projects]);
	const project = React.useCallback((id: string) => projectById.get(id) ?? data.projects[0], [data.projects, projectById]);
	// Read by the callbacks below, which stay stable across the shell's frequent re-renders.
	const sessionRef = useLatest(sessions);
	const openIdsRef = useLatest(openIds);

	const patchSession = React.useCallback((id: string, patch: SessionPatch) => {
		setPatches((current) => (samePatch(current[id], patch) ? current : { ...current, [id]: { ...current[id], ...patch } }));
	}, []);

	const activate = React.useCallback((id: string) => {
		setOpenIds((current) => (current.includes(id) ? current : [...current, id]));
		setRecentlyClosed((current) => current.filter((entry) => entry !== id));
		setActiveId(id);
	}, []);

	const newSession = React.useCallback(() => {
		draftCounter += 1;
		const id = `draft-${draftCounter}`;
		const anchor = sessionRef.current.find((session) => session.id === activeId);
		setCreated((current) => [...current, { id, title: 'New session', projectId: anchor?.projectId ?? data.projects[0].id, script: [], draft: true }]);
		setOpenIds((current) => {
			const index = activeId ? current.indexOf(activeId) : -1;
			return index >= 0 ? [...current.slice(0, index + 1), id, ...current.slice(index + 1)] : [...current, id];
		});
		setActiveId(id);
	}, [activeId, data.projects, sessionRef]);

	const closeSession = React.useCallback(
		(id: string) => {
			const draft = sessionRef.current.find((session) => session.id === id)?.draft;
			const { list, neighbor } = withoutAndNeighbor(openIdsRef.current, id);
			setOpenIds(list);
			setActiveId((active) => (active === id ? neighbor : active));
			if (draft) setCreated((current) => current.filter((session) => session.id !== id));
			else setRecentlyClosed((current) => [id, ...current.filter((entry) => entry !== id)].slice(0, 8));
			emit({ type: 'close-session', sessionId: id });
		},
		[emit, openIdsRef, sessionRef]
	);

	const deleteSession = React.useCallback(
		(id: string) => {
			closeSession(id);
			setRecentlyClosed((current) => current.filter((entry) => entry !== id));
			setDeleted((current) => [...current, id]);
			emit({ type: 'delete-session', sessionId: id });
		},
		[closeSession, emit]
	);

	const startSession = React.useCallback<CodingAgentContextValue['startSession']>(
		(id, { text, projectId, location }) => {
			setCreated((current) =>
				current.map((session) =>
					session.id === id
						? {
								id,
								title: titleFrom(text),
								projectId,
								location,
								branch: location === 'worktree' ? `agent/${id.replace('draft-', 'session-')}` : undefined,
								updatedLabel: 'now',
								script: [{ kind: 'user', text, delay: 0 }, ...data.newSessionScript(text)]
							}
						: session
				)
			);
			emit({ type: 'new-session', sessionId: id, projectId, location });
			emit({ type: 'send', sessionId: id, text, attachments: [] });
		},
		[data, emit]
	);

	const setLayout = React.useCallback(
		(next: CodingAgentLayout) => {
			setLayoutState(next);
			emit({ type: 'layout', layout: next });
		},
		[emit, setLayoutState]
	);

	const context = React.useMemo<CodingAgentContextValue>(
		() => ({
			data,
			layout,
			setLayout,
			sessions,
			session: (id) => sessionById.get(id),
			project,
			openIds,
			activeId,
			recentlyClosed,
			activate,
			goHome: () => setActiveId(null),
			newSession,
			closeSession,
			deleteSession,
			reopenClosed: (id) => {
				const target = id ?? recentlyClosed[0];
				if (target) activate(target);
			},
			patchSession,
			startSession,
			emit,
			renderBrowserPage,
			activeHandle,
			openCommandMenu: () => setCommandOpen(true),
			renaming,
			setRenaming,
			viewRun: (sessionId) => viewRuns[sessionId],
			openRun
		}),
		[activate, activeId, closeSession, data, deleteSession, emit, layout, newSession, openIds, openRun, patchSession, project, recentlyClosed, renaming, renderBrowserPage, sessionById, sessions, setLayout, startSession, viewRuns]
	);
	const shell = React.useMemo<SessionShellValue>(
		() => ({ data, layout, project, patchSession, emit, activeHandle, renderBrowserPage, deleteSession, openRun }),
		[data, deleteSession, emit, layout, openRun, patchSession, project, renderBrowserPage]
	);

	// Shortcuts work anywhere in the workspace, and from the page body when nothing else has focus.
	React.useEffect(() => {
		const onKeyDown = (event: KeyboardEvent) => {
			const target = event.target as Node | null;
			if (target !== document.body && !root.current?.contains(target)) return;
			const handle = activeId ? activeHandle.current : null;
			const actions: [keyof typeof SHORTCUTS, (() => void) | undefined][] = [
				['commandMenu', () => setCommandOpen((open) => !open)],
				['newSession', newSession],
				['closeSession', activeId ? () => closeSession(activeId) : undefined],
				['openFile', handle?.openFilePicker],
				['browser', handle?.openBrowser],
				['toggleTree', handle?.toggleTree],
				['togglePanel', handle?.togglePanel],
				['toggleTerminal', handle?.toggleTerminal]
			];
			for (const [id, run] of actions) {
				if (run && matches(event, SHORTCUTS[id])) {
					event.preventDefault();
					run();
					return;
				}
			}
			// ⌃1–⌃9 jump to a tab by position.
			if (event.ctrlKey && !event.metaKey && !event.altKey && /^Digit[1-9]$/.test(event.code)) {
				const id = openIds[Number(event.code.slice(5)) - 1];
				if (id) {
					event.preventDefault();
					setActiveId(id);
				}
			}
		};
		window.addEventListener('keydown', onKeyDown);
		return () => window.removeEventListener('keydown', onKeyDown);
	}, [activeId, closeSession, newSession, openIds]);

	const surfaces = (
		<>
			{openIds.map((id) => {
				const session = sessionById.get(id);
				if (!session) return null;
				return session.draft ? (
					<NewSession key={id} session={session} active={id === activeId} />
				) : (
					<SessionView
						key={id}
						session={session}
						active={id === activeId}
						viewRunId={viewRuns[id]}
						defaultPanelOpen={defaultPanelOpen}
						defaultTerminalOpen={defaultTerminalOpen}
					/>
				);
			})}
			{activeId === null ? <HomeView /> : null}
			<CommandMenu open={commandOpen} onOpenChange={setCommandOpen} />
		</>
	);

	// One tree for both layouts, so switching keeps every session mounted and its run where it was.
	return (
		<CodingAgentContext.Provider value={context}>
			<SessionShellContext.Provider value={shell}>
				<WorkspaceShell
					slot="coding-agent"
					framed={framed}
					className={className}
					sidebar={(props) => (layout === 'sidebar' ? <SessionSidebar {...props} /> : null)}
				>
					<div ref={root} className="flex h-full min-h-0 w-full min-w-0 flex-col bg-sidebar">
						{layout === 'tabs' ? (
							<SessionTabs />
						) : (
							// Below the rail breakpoint the sidebar becomes a drawer, opened from here.
							<div className="flex h-10 shrink-0 items-center gap-1 px-2 @3xl/ws:hidden">
								<NavMenuButton />
								<span dir="auto" title={data.brand} className="min-w-0 truncate text-sm font-medium text-foreground [text-align:match-parent]">
									{data.brand}
								</span>
							</div>
						)}
						<div className="min-h-0 flex-1">{surfaces}</div>
					</div>
				</WorkspaceShell>
			</SessionShellContext.Provider>
		</CodingAgentContext.Provider>
	);
}

