import { useLatest } from '@/components/ui/workspace-kit/use-latest';
import { CODE_THEMES, type ColorScheme, DIFF_SURFACE_STYLE, DIFF_UNSAFE_CSS } from '@/components/ui/coding-agent/code-surface-theme';
import { toolbarButtonClass } from '@/components/ui/coding-agent/session-surface';
import { type FileChange, lineTotals, type WorktreeSummary } from '@/components/ui/coding-agent/harness';
import { type ChangeScope, scopeChanges, type WorktreeAction, WorktreePicker } from '@/components/ui/coding-agent/worktree-picker';

export type LineComment = { id: string; path: string; line: number; side: 'additions' | 'deletions'; text: string; sent?: boolean };

type Annotation = { kind: 'comment'; comment: LineComment } | { kind: 'draft' };

type DiffStyle = 'unified' | 'split';

const STYLE_OPTIONS = [
	{ value: 'unified' as const, label: 'Unified', icon: Rows2 },
	{ value: 'split' as const, label: 'Split', icon: Columns2 }
];

/** Below this width two columns of code show too little of either side, so the review stays unified. */
const SPLIT_MIN_WIDTH = 640;

function DraftComment({ onSubmit, onCancel }: { onSubmit: (text: string) => void; onCancel: () => void }) {
	const [text, setText] = React.useState('');
	const field = React.useRef<HTMLTextAreaElement>(null);
	// The diff takes focus back on pointer-up after the gutter click, so focus lands a frame later.
	React.useEffect(() => {
		const frame = requestAnimationFrame(() => field.current?.focus({ preventScroll: true }));
		return () => cancelAnimationFrame(frame);
	}, []);
	return (
		<form
			dir="auto"
			className="m-2 flex max-w-lg flex-col gap-2 rounded-lg border border-border bg-card p-2 font-sans shadow-xs"
			onSubmit={(event) => {
				event.preventDefault();
				if (text.trim()) onSubmit(text.trim());
			}}
		>
			<Textarea
				ref={field}
				aria-label="Comment for the agent"
				placeholder="Add context for this change…"
				value={text}
				onChange={(event) => setText(event.target.value)}
				onKeyDown={(event) => {
					if (event.key === 'Escape') onCancel();
					if (event.key === 'Enter' && (event.metaKey || event.ctrlKey)) event.currentTarget.form?.requestSubmit();
				}}
				className="min-h-16 text-[0.8125rem]"
			/>
			<div className="flex justify-end gap-1.5">
				<Button type="button" size="sm" variant="ghost" onClick={onCancel}>
					Cancel
				</Button>
				<Button type="submit" size="sm" disabled={!text.trim()}>
					Add comment
				</Button>
			</div>
		</form>
	);
}

function SavedComment({ comment }: { comment: LineComment }) {
	return (
		<div dir="auto" className="m-2 flex max-w-lg items-start gap-2 rounded-lg border border-border bg-card px-2.5 py-2 font-sans text-[0.8125rem] shadow-xs">
			<MessageSquare aria-hidden="true" className="mt-0.5 size-3.5 shrink-0 text-muted-foreground" />
			<div className="min-w-0">
				<p className="text-foreground [overflow-wrap:anywhere]">{comment.text}</p>
				<p className="mt-0.5 text-xs text-muted-foreground">{comment.sent ? 'Sent with your message' : 'Attached to your next message'}</p>
			</div>
		</div>
	);
}

/** The file's own header row, in the panel's type and icon sizes, with the path cut in the middle so the name shows. */
function DiffHeader({ change, branch }: { change: FileChange; branch?: string }) {
	const Icon = change.before === null ? FilePlus2 : FilePen;
	return (
		<div className="flex h-10 min-w-0 items-center gap-2 bg-muted px-3 font-sans text-[0.8125rem]">
			<Icon aria-hidden="true" className={cn('size-3.5 shrink-0', change.before === null ? 'text-success' : 'text-warning')} />
			<MiddleTruncate text={change.path} tail={Math.min((change.path.split('/').pop() ?? '').length, 28)} className="min-w-0 flex-1 text-foreground" />
			{/* With several worktrees the same path can show twice, so each diff says which branch it's on. */}
			{branch ? (
				<span title={branch} className="max-w-[40%] shrink truncate font-mono text-xs text-muted-foreground">
					{branch}
				</span>
			) : null}
			<span className="shrink-0 font-mono text-xs tabular-nums">
				{change.additions ? <span className="text-success">+{change.additions}</span> : null}
				{change.additions && change.deletions ? ' ' : null}
				{change.deletions ? <span className="text-destructive">−{change.deletions}</span> : null}
			</span>
		</div>
	);
}

type Draft = { path: string; line: number; side: 'additions' | 'deletions' };

/** Files drawn straight away; the rest draw as you scroll toward them. */
const EAGER_FILES = 3;

/** About how tall a file's diff will be before it's drawn: its header and its changed lines, at 20px a line. */
function estimateHeight(change: FileChange, allLines: boolean) {
	const lines = allLines ? change.after.split('\n').length : Math.min(change.additions + change.deletions + 6, 400);
	return 40 + lines * 20;
}

/**
 * One file's diff. Memoized with stable inputs, because the renderer re-diffs whenever its file objects change and
 * repaints whenever its options do, and the session re-renders on every harness event.
 */
const ReviewFile = React.memo(function ReviewFile({
	change,
	index,
	branch,
	diffStyle,
	scheme,
	allLines,
	wrap,
	comments,
	draft,
	onDraft,
	onComment,
	onRegister,
	onCurrent
}: {
	change: FileChange;
	index: number;
	branch?: string;
	diffStyle: DiffStyle;
	scheme: ColorScheme;
	allLines: boolean;
	wrap: boolean;
	comments: LineComment[];
	/** The open draft when it's on this file. */
	draft: Draft | null;
	onDraft: (draft: Draft | null) => void;
	onComment: (comment: Omit<LineComment, 'id'>) => void;
	onRegister: (key: string, node: HTMLElement | null) => void;
	onCurrent: (index: number) => void;
}) {
	const { key, path } = change;
	const oldFile = React.useMemo(() => ({ name: path, contents: change.before ?? '' }), [path, change.before]);
	const newFile = React.useMemo(() => ({ name: path, contents: change.after }), [path, change.after]);
	const options = React.useMemo(
		() => ({
			diffStyle,
			theme: CODE_THEMES,
			themeType: scheme,
			expandUnchanged: allLines,
			stickyHeader: true,
			overflow: wrap ? ('wrap' as const) : ('scroll' as const),
			lineDiffType: 'word' as const,
			hunkSeparators: 'line-info-basic' as const,
			enableGutterUtility: true,
			unsafeCSS: DIFF_UNSAFE_CSS,
			onGutterUtilityClick: (range: { end: number; endSide?: 'additions' | 'deletions'; side?: 'additions' | 'deletions' }) =>
				onDraft({ path, line: range.end, side: range.endSide ?? range.side ?? 'additions' })
		}),
		[diffStyle, scheme, allLines, wrap, path, onDraft]
	);
	const annotations = React.useMemo(() => {
		const out: DiffLineAnnotation<Annotation>[] = comments
			.filter((comment) => comment.path === path)
			.map((comment) => ({ side: comment.side, lineNumber: comment.line, metadata: { kind: 'comment', comment } }));
		if (draft) out.push({ side: draft.side, lineNumber: draft.line, metadata: { kind: 'draft' } });
		return out;
	}, [comments, draft, path]);
	const style = React.useMemo(() => ({ ...DIFF_SURFACE_STYLE, colorScheme: scheme }), [scheme]);
	// Diffing and highlighting a file is the expensive part, so a file far below the fold waits until you scroll near
	// it, holding about its own height meanwhile; once drawn it stays drawn.
	const [near, setNear] = React.useState(index < EAGER_FILES);
	const node = React.useRef<HTMLElement | null>(null);
	const register = React.useCallback(
		(element: HTMLElement | null) => {
			node.current = element;
			onRegister(key, element);
		},
		[onRegister, key]
	);
	React.useEffect(() => {
		const element = node.current;
		if (near || !element) return;
		// Without an observer to say when it's close, draw it now rather than never.
		if (typeof IntersectionObserver === 'undefined') {
			setNear(true);
			return;
		}
		const observer = new IntersectionObserver(([entry]) => entry?.isIntersecting && setNear(true), {
			root: element.closest('[data-review-scroller]'),
			rootMargin: '800px 0px'
		});
		observer.observe(element);
		return () => observer.disconnect();
	}, [near]);

	return (
		<section
			aria-label={branch ? `${path} on ${branch}` : path}
			data-key={key}
			ref={register}
			onFocusCapture={() => onCurrent(index)}
			// Each file starts at its tinted header, so files need no rule between them.
			className="pb-3 last:pb-0"
		>
			{near ? (
				<MultiFileDiff<Annotation>
					oldFile={oldFile}
					newFile={newFile}
					options={options}
					renderCustomHeader={() => <DiffHeader change={change} branch={branch} />}
					lineAnnotations={annotations}
					renderAnnotation={(annotation) =>
						annotation.metadata?.kind === 'comment' ? (
							<SavedComment comment={annotation.metadata.comment} />
						) : (
							<DraftComment onCancel={() => onDraft(null)} onSubmit={(text) => onComment({ path, line: annotation.lineNumber, side: annotation.side, text })} />
						)
					}
					style={style}
				/>
			) : (
				<div style={{ height: estimateHeight(change, allLines) }}>
					<DiffHeader change={change} branch={branch} />
				</div>
			)}
		</section>
	);
});

/**
 * Every file the session changed, one diff each, with a split or unified view, collapsed or full context, wrapped
 * or scrolling lines, previous/next file stepping that follows your scrolling, and line comments that ride along
 * with the next message.
 */
export function ReviewPanel({
	changes,
	focusPath,
	scheme,
	comments,
	onComment,
	scopes,
	worktrees,
	names,
	onWorktreeAction
}: {
	changes: FileChange[];
	/** Agents that changed files. With more than one, the review can narrow to a single agent's changes. */
	scopes: { id: string; name: string }[];
	/** Where the changes landed, with each worktree's pull request and CI. With more than one, the review can narrow to one. */
	worktrees: WorktreeSummary[];
	/** Agent names by run id, for the worktree rows. */
	names: Record<string, string>;
	onWorktreeAction: (action: WorktreeAction) => void;
	focusPath: { path: string; nonce: number } | null;
	scheme: ColorScheme;
	comments: LineComment[];
	onComment: (comment: Omit<LineComment, 'id'>) => void;
}) {
	// Bound in the empty state too, so a session that opens with no changes is measured before its first diff lands.
	const [root, { width }] = useElementSize<HTMLDivElement>({ ignoreHidden: true });
	const scroller = React.useRef<HTMLDivElement>(null);
	const [chosenStyle, setDiffStyle] = React.useState<DiffStyle>('unified');
	const [scope, setScopeState] = React.useState<ChangeScope>({ kind: 'all' });
	// Kept stable between harness events, so the scroll observer and file stepping aren't rebuilt each time.
	const shown = React.useMemo(() => scopeChanges(changes, scope), [changes, scope]);
	const several = worktrees.length > 1;
	const branchOf = (id: string) => worktrees.find((entry) => entry.worktree.id === id)?.worktree.branch ?? id;
	const [allLines, setAllLines] = React.useState(false);
	const [wrap, setWrap] = React.useState(false);
	const [current, setCurrent] = React.useState(0);
	const setScope = (next: ChangeScope) => {
		setScopeState(next);
		setCurrent(0);
		scroller.current?.scrollTo({ top: 0 });
	};
	const [draft, setDraft] = React.useState<Draft | null>(null);
	const sections = React.useRef(new Map<string, HTMLElement>());
	const registerSection = React.useCallback((key: string, node: HTMLElement | null) => {
		if (node) sections.current.set(key, node);
		else sections.current.delete(key);
	}, []);
	// The host's callback can change every render; the files get one that never does, so they can skip re-rendering.
	const onCommentRef = useLatest(onComment);
	const submitComment = React.useCallback(
		(comment: Omit<LineComment, 'id'>) => {
			onCommentRef.current(comment);
			setDraft(null);
		},
		[onCommentRef]
	);
	const canSplit = width >= SPLIT_MIN_WIDTH;
	const diffStyle = canSplit ? chosenStyle : 'unified';

	const reveal = React.useCallback(
		(index: number) => {
			const change = shown[index];
			if (!change) return;
			setCurrent(index);
			sections.current.get(change.key)?.scrollIntoView({ block: 'start' });
		},
		[shown]
	);

	React.useEffect(() => {
		if (!focusPath) return;
		const index = shown.findIndex((change) => change.path === focusPath.path);
		if (index >= 0) reveal(index);
		// Only a new focus request moves the view, not every change to the list.
		// eslint-disable-next-line react-hooks/exhaustive-deps
	}, [focusPath]);

	// The counter follows your scrolling: the current file is the first one whose diff reaches the top quarter.
	React.useEffect(() => {
		const node = scroller.current;
		if (!node || shown.length < 2) return;
		const visible = new Map<string, boolean>();
		const observer = new IntersectionObserver(
			(entries) => {
				for (const entry of entries) visible.set((entry.target as HTMLElement).dataset.key ?? '', entry.isIntersecting);
				const index = shown.findIndex((change) => visible.get(change.key));
				if (index >= 0) setCurrent(index);
			},
			{ root: node, rootMargin: '0px 0px -75% 0px' }
		);
		for (const element of sections.current.values()) observer.observe(element);
		return () => observer.disconnect();
	}, [shown]);

	// The scope chip: what's in view, its worktree's pull request and CI, and the menu to change it.
	const picker = worktrees.length ? (
		<WorktreePicker
			worktrees={worktrees}
			agents={scopes}
			changes={changes}
			names={names}
			scope={scope}
			onScope={setScope}
			onAction={onWorktreeAction}
		/>
	) : null;

	if (changes.length === 0) {
		return (
			<div ref={root} className="@container/review flex h-full min-h-0 flex-col">
				{picker ? <div className="flex h-10 shrink-0 items-center px-3">{picker}</div> : null}
				<div className="grid min-h-0 flex-1 place-items-center">
					<EmptyState icon={GitCompareArrows} title="No changes yet" description="Files the agent edits in this session show up here as diffs." />
				</div>
			</div>
		);
	}

	const { additions, deletions } = lineTotals(shown);

	return (
		<div ref={root} className="@container/review flex h-full min-h-0 flex-col">
			<div className="flex h-10 shrink-0 items-center gap-2 px-3">
				{picker ?? null}
				{/* The file count keeps its room; the line totals give way first on a narrow panel. */}
				{/* Beside the scope chip on a narrow panel the counts step aside; the chip's menu repeats them. */}
				<p className={cn('flex min-w-0 flex-1 items-center gap-2 overflow-hidden text-xs whitespace-nowrap text-muted-foreground', picker && '@max-lg/review:invisible')}>
					<bdi className="shrink-0">
						<span className="tabular-nums">{shown.length}</span> {plural(shown.length, { one: 'file', other: 'files' })}
					</bdi>
					<bdi className="min-w-0 truncate font-mono tabular-nums">
						{additions ? <span className="text-success">+{additions}</span> : null} {deletions ? <span className="text-destructive">−{deletions}</span> : null}
					</bdi>
				</p>
				{canSplit ? <Segmented label="Diff layout" value={chosenStyle} options={STYLE_OPTIONS} onChange={setDiffStyle} /> : null}
				<Button
					size="xs"
					variant="ghost"
					aria-pressed={wrap}
					onClick={() => setWrap((value) => !value)}
					className={cn('text-muted-foreground', wrap && 'bg-overlay-hover text-foreground')}
				>
					Wrap
				</Button>
				<Button
					size="xs"
					variant="ghost"
					aria-pressed={allLines}
					onClick={() => setAllLines((value) => !value)}
					className={cn('text-muted-foreground', allLines && 'bg-overlay-hover text-foreground')}
				>
					All lines
				</Button>
				{shown.length > 1 ? (
					<div className="flex items-center">
						<TooltipIconButton label="Previous file" disabled={current === 0} onClick={() => reveal(current - 1)} className={toolbarButtonClass}>
							<ChevronUp aria-hidden="true" className="size-3.5" />
						</TooltipIconButton>
						<span className="min-w-9 text-center text-xs text-muted-foreground tabular-nums">
							{current + 1}/{shown.length}
						</span>
						<TooltipIconButton label="Next file" disabled={current === shown.length - 1} onClick={() => reveal(current + 1)} className={toolbarButtonClass}>
							<ChevronDown aria-hidden="true" className="size-3.5" />
						</TooltipIconButton>
					</div>
				) : null}
			</div>
			{/* Code reads left to right whatever the page direction. */}
			<div ref={scroller} data-review-scroller="" dir="ltr" className="min-h-0 flex-1 overflow-y-auto">
				{shown.length === 0 ? (
					<div className="grid h-full place-items-center">
						<EmptyState icon={GitCompareArrows} title="Nothing changed here yet" description="Changes land here as the agents in this worktree edit files." />
					</div>
				) : null}
				{shown.map((change, index) => (
					<ReviewFile
						key={change.key}
						change={change}
						index={index}
						branch={several ? branchOf(change.worktreeId) : undefined}
						diffStyle={diffStyle}
						scheme={scheme}
						allLines={allLines}
						wrap={wrap}
						comments={comments}
						draft={draft?.path === change.path ? draft : null}
						onDraft={setDraft}
						onComment={submitComment}
						onRegister={registerSection}
						onCurrent={setCurrent}
					/>
				))}
			</div>
		</div>
	);
}

'use client';

import { ArrowUp, AtSign, CornerDownRight, FileCode2, MessageSquare, Paperclip, Plus, Slash, Square, SquareTerminal, X } from 'lucide-react';
import * as React from 'react';

import { cn } from '@/lib/utils';
import { type AiModel, type ModelSelection, ModelSelector } from '@/components/ui/ai/model-selector';
import { PromptInput, PromptInputAction, PromptInputActions, PromptInputTextarea } from '@/components/ui/ai/prompt-input';
import { PromptInputAttachment, PromptInputAttachments } from '@/components/ui/ai/prompt-input-attachment';
import { PromptInputTray, PromptInputTrayRow } from '@/components/ui/ai/prompt-input-tray';
import { UsageNotice, usageTone } from '@/components/ui/ai/usage-notice';
import { Button } from '@/components/ui/button';
import { Command, CommandGroup, CommandGroupLabel, CommandItem, CommandList } from '@/components/ui/command';
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger } from '@/components/ui/dropdown-menu';
import { iconButtonClass } from '@/components/ui/workspace-kit/primitives';
import type { SlashCommand } from '@/components/ui/coding-agent/types';

export type ComposerAttachment = { id: string; kind: 'file' | 'comment'; label: string; detail?: string };

type Suggestion = { id: string; kind: 'command' | 'file'; label: string; detail?: string };

/** The `/command` or `@file` being typed at the caret, if any. */
function activeTrigger(value: string, caret: number) {
	const before = value.slice(0, caret);
	const command = /^\/(\S*)$/.exec(before);
	if (command) return { kind: 'command' as const, query: command[1], start: 0 };
	const mention = /(?:^|\s)@([^\s@]*)$/.exec(before);
	if (mention) return { kind: 'file' as const, query: mention[1], start: caret - mention[1].length - 1 };
	return null;
}

const MAX_SUGGESTIONS = 8;

/**
 * The session composer, assembled from the AI kit's prompt input: a `/` command and `@` file menu at the caret, `!`
 * shell mode, and the model picker. A running session adds attachment and comment chips, a queue of follow-ups typed
 * while the agent works, an "Attach files" item, and a send button that turns into stop mid-run; each shows only
 * when its props are passed, so a new-session draft leaves them out.
 */
export function SessionComposer({
	placeholder: placeholderProp,
	running = false,
	onSubmit,
	onStop,
	attachments = [],
	onRemoveAttachment,
	queued = [],
	onUnqueue,
	commands,
	files,
	models,
	model,
	onModelChange,
	usagePercent,
	onAttachFiles,
	inputRef,
	className
}: {
	placeholder?: string;
	running?: boolean;
	onSubmit: (text: string) => void;
	/** Shows the stop button while `running` and nothing is typed. */
	onStop?: () => void;
	attachments?: ComposerAttachment[];
	/** Gives each attachment chip a remove button. */
	onRemoveAttachment?: (id: string) => void;
	queued?: { id: string; text: string }[];
	/** Gives each queued follow-up a remove button. */
	onUnqueue?: (id: string) => void;
	commands: SlashCommand[];
	files: string[];
	models: AiModel[];
	model: ModelSelection;
	onModelChange: (model: ModelSelection) => void;
	usagePercent?: number;
	/** Adds "Attach files" to the add menu. */
	onAttachFiles?: () => void;
	inputRef?: React.RefObject<HTMLDivElement | null>;
	className?: string;
}) {
	const [value, setValue] = React.useState('');
	const [caret, setCaret] = React.useState(0);
	const [highlight, setHighlight] = React.useState(0);
	const [dismissed, setDismissed] = React.useState<string | null>(null);
	const [usageDismissed, setUsageDismissed] = React.useState(false);
	const wrapper = React.useRef<HTMLDivElement>(null);
	const listId = React.useId();
	// Only promise the shortcuts this workspace actually has.
	const placeholder =
		placeholderProp ??
		['Ask anything', commands.length ? '/ for commands' : null, files.length ? '@ for context' : null].filter(Boolean).join(', ') + '…';

	const trigger = activeTrigger(value, caret);
	const triggerKey = trigger ? `${trigger.kind}:${trigger.start}` : null;
	const suggestions = React.useMemo<Suggestion[]>(() => {
		if (!trigger) return [];
		const query = trigger.query.toLowerCase();
		if (trigger.kind === 'command') {
			return commands
				.filter((command) => command.name.startsWith(query))
				.map((command) => ({ id: command.name, kind: 'command' as const, label: `/${command.name}`, detail: command.description }));
		}
		return files
			.filter((path) => path.toLowerCase().includes(query))
			.slice(0, MAX_SUGGESTIONS)
			.map((path) => ({ id: path, kind: 'file' as const, label: path.split('/').pop() ?? path, detail: path }));
	}, [commands, files, trigger?.kind, trigger?.query]);
	const menuOpen = suggestions.length > 0 && triggerKey !== dismissed;
	const active = suggestions[Math.min(highlight, suggestions.length - 1)];

	React.useEffect(() => setHighlight(0), [triggerKey, trigger?.query]);

	const textarea = () => wrapper.current?.querySelector('textarea');

	const pick = (suggestion: Suggestion) => {
		if (!trigger) return;
		const insert = suggestion.kind === 'command' ? `/${suggestion.id} ` : `@${suggestion.id} `;
		const next = value.slice(0, trigger.start) + insert + value.slice(caret);
		const position = trigger.start + insert.length;
		setValue(next);
		setCaret(position);
		requestAnimationFrame(() => {
			const node = textarea();
			node?.focus();
			node?.setSelectionRange(position, position);
		});
	};

	const insertAtCaret = (text: string) => {
		const next = value.slice(0, caret) + text + value.slice(caret);
		setValue(next);
		setCaret(caret + text.length);
		requestAnimationFrame(() => {
			const node = textarea();
			node?.focus();
			node?.setSelectionRange(caret + text.length, caret + text.length);
		});
	};

	const submit = () => {
		if (menuOpen && active) {
			pick(active);
			return;
		}
		const text = value.trim();
		if (!text) return;
		onSubmit(text);
		setValue('');
		setCaret(0);
	};

	const shell = value.startsWith('!');
	const canSend = value.trim().length > 0;
	const showUsage = usagePercent !== undefined && usagePercent >= 75 && !usageDismissed;
	const header =
		showUsage || queued.length > 0 ? (
			<>
				{showUsage ? <UsageNotice percent={usagePercent} onDismiss={() => setUsageDismissed(true)} /> : null}
				{queued.map((entry) => (
					<PromptInputTrayRow
						key={entry.id}
						icon={<CornerDownRight aria-hidden="true" className="size-3.5 text-muted-foreground" />}
						actions={
							onUnqueue ? (
								<Button size="icon-xs" variant="ghost" aria-label="Remove from queue" className="size-6" onClick={() => onUnqueue(entry.id)}>
									<X className="size-3.5" />
								</Button>
							) : undefined
						}
					>
						<span dir="auto" title={entry.text} className="block min-w-0 truncate">
							<span className="text-muted-foreground">Queued · </span>
							{entry.text}
						</span>
					</PromptInputTrayRow>
				))}
			</>
		) : null;

	return (
		<div ref={inputRef} className={cn('@container/composer relative', className)}>
			{menuOpen ? (
				// The textarea's aria-controls points here; the menu's own list id belongs to the menu library.
				<div id={listId} className="absolute inset-x-0 bottom-full z-20 mb-2 overflow-hidden rounded-lg border border-border bg-popover shadow-lg">
					<Command shouldFilter={false} value={active?.id} loop label={trigger?.kind === 'command' ? 'Commands' : 'Files'}>
						<CommandList className="max-h-64">
							<CommandGroup>
								<CommandGroupLabel>{trigger?.kind === 'command' ? 'Commands' : 'Files'}</CommandGroupLabel>
								{suggestions.map((suggestion, index) => (
									<CommandItem
										key={suggestion.id}
										value={suggestion.id}
										title={suggestion.detail ? `${suggestion.label} · ${suggestion.detail}` : suggestion.label}
										onMouseEnter={() => setHighlight(index)}
										onSelect={() => pick(suggestion)}
										className="gap-2"
									>
										{suggestion.kind === 'command' ? (
											<Slash aria-hidden="true" className="size-3.5 text-muted-foreground" />
										) : (
											<FileCode2 aria-hidden="true" className="size-3.5 text-muted-foreground" />
										)}
										{/* The name keeps priority but never more than 60%, so the detail always gets some room. */}
										<span className={cn('max-w-[60%] shrink-0 truncate text-foreground', suggestion.kind === 'command' && 'font-mono text-[0.8125rem]')}>
											{suggestion.label}
										</span>
										<span dir="auto" className="min-w-0 flex-1 truncate text-xs text-muted-foreground">
											{suggestion.detail}
										</span>
									</CommandItem>
								))}
							</CommandGroup>
						</CommandList>
					</Command>
				</div>
			) : null}
			<PromptInputTray tone={showUsage ? usageTone(usagePercent) : 'neutral'} header={header}>
				<div ref={wrapper}>
					<PromptInput
						value={value}
						onValueChange={setValue}
						onSubmit={submit}
						// A long paste scrolls inside the box instead of pushing the send button out of view.
						maxHeight="min(240px, 30dvh)"
						// A ring and a soft drop instead of an outline, so the composer sits on the page rather than in a box.
						className="rounded-xl border-transparent bg-card p-1.5 shadow-[0_0_0_1px_color-mix(in_oklab,var(--foreground)_8%,transparent),0_2px_8px_-2px_rgb(0_0_0/0.08)]"
					>
						{attachments.length > 0 ? (
							<PromptInputAttachments>
								{attachments.map((attachment) => (
									<PromptInputAttachment
										key={attachment.id}
										name={attachment.label}
										meta={attachment.detail}
										icon={
											attachment.kind === 'comment' ? (
												<MessageSquare aria-hidden="true" className="size-3.5" />
											) : (
												<FileCode2 aria-hidden="true" className="size-3.5" />
											)
										}
										onRemove={onRemoveAttachment ? () => onRemoveAttachment(attachment.id) : undefined}
									/>
								))}
							</PromptInputAttachments>
						) : null}
						<PromptInputTextarea
							aria-label="Message the agent"
							aria-autocomplete="list"
							aria-controls={menuOpen ? listId : undefined}
							aria-expanded={menuOpen}
							placeholder={placeholder}
							// A dismissed menu stays closed until the caret moves into a different trigger.
							onSelect={(event) => setCaret(event.currentTarget.selectionStart)}
							onInput={(event) => setCaret(event.currentTarget.selectionStart)}
							onKeyDown={(event) => {
								if (!menuOpen) return;
								if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
									event.preventDefault();
									const by = event.key === 'ArrowDown' ? 1 : -1;
									setHighlight((index) => (index + by + suggestions.length) % suggestions.length);
								} else if (event.key === 'Tab' && active) {
									event.preventDefault();
									pick(active);
								} else if (event.key === 'Escape') {
									event.preventDefault();
									setDismissed(triggerKey);
								}
							}}
							className={cn('min-h-10 px-1.5 py-1', shell && 'font-mono')}
						/>
						<PromptInputActions className="justify-between px-0">
							<div className="flex min-w-0 flex-1 items-center gap-0.5">
								<DropdownMenu>
									<DropdownMenuTrigger
										aria-label="Add to message"
										title="Add to message"
										// Its neighbours sit 2px away, so the hit area stays inside the box; on touch screens the button grows to 44px instead.
										className={cn(iconButtonClass({ menu: true, extendHitArea: false }), 'pointer-coarse:size-11')}
									>
										<Plus aria-hidden="true" className="size-3.5" />
									</DropdownMenuTrigger>
									<DropdownMenuContent align="start" side="top" className="w-52">
										{onAttachFiles ? (
											<DropdownMenuItem onClick={onAttachFiles}>
												<Paperclip aria-hidden="true" />
												Attach files
											</DropdownMenuItem>
										) : null}
										<DropdownMenuItem onClick={() => insertAtCaret('@')}>
											<AtSign aria-hidden="true" />
											Mention a file
										</DropdownMenuItem>
										<DropdownMenuItem onClick={() => insertAtCaret(value ? '' : '/')}>
											<Slash aria-hidden="true" />
											Run a command
										</DropdownMenuItem>
										<DropdownMenuItem onClick={() => (shell ? null : setValue(`!${value}`))}>
											<SquareTerminal aria-hidden="true" />
											Shell command
										</DropdownMenuItem>
									</DropdownMenuContent>
								</DropdownMenu>
								{shell ? (
									<span className="flex h-6 shrink-0 items-center gap-1 rounded-md bg-muted px-1.5 font-mono text-xs text-muted-foreground">
										<SquareTerminal aria-hidden="true" className="size-3.5 shrink-0" />
										shell
									</span>
								) : null}
								<ModelSelector
									models={models}
									value={model}
									onValueChange={onModelChange}
									side="top"
									triggerClassName="h-7 min-w-0 px-1.5"
									// On a narrow composer the model name gets the room; the level is one click away.
									levelClassName="@max-sm/composer:hidden"
								/>
							</div>
							{running && !canSend && onStop ? (
								<PromptInputAction tooltip="Stop">
									<Button size="icon-xs" variant="secondary" aria-label="Stop" className="size-7 shrink-0" onClick={onStop}>
										<Square className="size-3.5 fill-current" />
									</Button>
								</PromptInputAction>
							) : (
								<PromptInputAction tooltip={running ? 'Queue for when the agent is done' : 'Send'}>
									<Button
										size="icon-xs"
										variant={canSend ? 'default' : 'secondary'}
										aria-label={running ? 'Queue message' : 'Send'}
										disabled={!canSend}
										className="size-7 shrink-0"
										onClick={submit}
									>
										<ArrowUp className="size-3.5" />
									</Button>
								</PromptInputAction>
							)}
						</PromptInputActions>
					</PromptInput>
				</div>
			</PromptInputTray>
		</div>
	);
}

'use client';

import { PenLine } from 'lucide-react';

import { initials } from '@/lib/initials';
import { cn } from '@/lib/utils';
import { AgentRing, type StatusSignal, statusSignal } from '@/components/ui/agents-builder/agent-status';
import { MarkTile } from '@/components/ui/ai/mark-tile';
import { TextShimmer } from '@/components/ui/ai/text-shimmer';
import type { LiveSession } from '@/components/ui/coding-agent/coding-agent-context';

const STATUS_LABEL: Record<StatusSignal, string> = {
	running: 'Working',
	approval: 'Needs your approval',
	input: 'Waiting for your answer',
	failed: 'Failed',
	queued: 'Queued',
	done: 'New result',
	idle: ''
};

export function sessionStatusLabel(session: LiveSession) {
	return STATUS_LABEL[statusSignal(session)];
}

/** A project's one-letter tile, taken by grapheme so an emoji-first name keeps its emoji whole. */
export function ProjectMark({ name, className }: { name: string; className?: string }) {
	return <MarkTile className={cn('font-medium', className)}>{initials(name, { max: 1 })}</MarkTile>;
}

/**
 * The mark before a session's title, always in the same 16px box so titles line up whatever the state: a ring
 * while the agent works or waits on you, the project's initial at rest, and a pencil for an unsent draft.
 */
export function SessionGlyph({ session, projectName, className }: { session: LiveSession; projectName: string; className?: string }) {
	const signal = statusSignal(session);
	return (
		<span className={cn('grid size-4 shrink-0 place-items-center', className)}>
			{session.draft ? (
				<PenLine aria-hidden="true" className="size-3.5 text-muted-foreground" />
			) : signal === 'idle' ? (
				<ProjectMark name={projectName} />
			) : (
				<AgentRing signal={signal} progress={session.progress} />
			)}
		</span>
	);
}

/**
 * A session title that shimmers while the agent works. It truncates in its own text direction (`dir="auto"`), so
 * an Arabic title in an English workspace loses its end rather than its first word, while still aligning with
 * the surrounding column.
 */
export function SessionTitle({ session, className }: { session: LiveSession; className?: string }) {
	const shared = cn('block min-w-0 max-w-full truncate [text-align:match-parent]', className);
	return session.status === 'running' ? (
		<TextShimmer dir="auto" className={shared}>
			{session.title}
		</TextShimmer>
	) : (
		<span dir="auto" className={shared}>
			{session.title}
		</span>
	);
}

'use client';

import { ChevronDown, LayoutGrid, type LucideIcon, PanelTop, Plus, Search } from 'lucide-react';
import * as React from 'react';

import { initials } from '@/lib/initials';
import { formatCount } from '@/lib/intl';
import { NavIcon, NavRow, NavSection, SidebarFrame } from '@/components/ui/workspace-kit/nav';
import type { WorkspaceSidebarRenderProps } from '@/components/ui/workspace-kit/shell';
import { AgentRing, isWaitingOnYou, statusSignal } from '@/components/ui/agents-builder/agent-status';
import { useCodingAgent } from '@/components/ui/coding-agent/coding-agent-context';
import { SessionGlyph, sessionStatusLabel, SessionTitle } from '@/components/ui/coding-agent/session-glyph';
import { withShortcut } from '@/components/ui/coding-agent/shortcuts';

/** Sessions shown per project before "Show all"; the active one and any that need you always show. */
const ROWS_PER_PROJECT = 8;

/** Nav icons sit in the same 16px box as the session glyphs, so every label in the sidebar starts on one line. */
function RowIcon({ icon, active }: { icon: LucideIcon; active?: boolean }) {
	return (
		<span className="grid size-4 shrink-0 place-items-center">
			<NavIcon icon={icon} active={active} />
		</span>
	);
}

/**
 * The sidebar layout's navigation: new session, home and search, then every session grouped by project with its live
 * status, and a way back to tabs. Collapses to an icon rail like the other workspace templates.
 */
export function SessionSidebar({ mode, collapsed, onCollapsedChange, onNavigate }: WorkspaceSidebarRenderProps) {
	const { data, sessions, activeId, activate, goHome, newSession, setLayout, openCommandMenu, project, viewRun, openRun } = useCodingAgent();
	const [expanded, setExpanded] = React.useState<string[]>([]);
	const go = (action: () => void) => () => {
		action();
		onNavigate();
	};
	const brandTile = (
		<span aria-hidden="true" className="grid size-5 shrink-0 place-items-center rounded-md bg-foreground text-[0.6875rem] font-semibold text-background">
			{initials(data.brand, { max: 1 })}
		</span>
	);

	return (
		<SidebarFrame
			label="Sessions"
			collapsed={collapsed}
			onCollapsedChange={onCollapsedChange}
			drawer={mode === 'drawer'}
			onClose={onNavigate}
			menu={
				collapsed ? (
					<span title={data.brand}>{brandTile}</span>
				) : (
					<span className="flex min-w-0 flex-1 items-center gap-2 px-1.5">
						{brandTile}
						<span dir="auto" title={data.brand} className="min-w-0 truncate text-sm font-medium text-foreground [text-align:match-parent]">
							{data.brand}
						</span>
					</span>
				)
			}
			footer={
				<ul className="flex flex-col gap-0.5 px-2.5 pb-3">
					<NavRow label="Show sessions as tabs" collapsed={collapsed} muted leading={<RowIcon icon={PanelTop} />} onClick={go(() => setLayout('tabs'))} />
				</ul>
			}
		>
			<NavSection collapsed={collapsed}>
				<NavRow label={withShortcut('New session', 'newSession')} labelNode="New session" collapsed={collapsed} leading={<RowIcon icon={Plus} />} onClick={go(newSession)} />
				<NavRow label="All sessions" collapsed={collapsed} active={activeId === null} leading={<RowIcon icon={LayoutGrid} active={activeId === null} />} onClick={go(goHome)} />
				<NavRow label={withShortcut('Search commands', 'commandMenu')} labelNode="Search" collapsed={collapsed} leading={<RowIcon icon={Search} />} onClick={go(openCommandMenu)} />
			</NavSection>
			{data.projects.map((entry) => {
				const rows = sessions.filter((session) => session.projectId === entry.id);
				if (rows.length === 0) return null;
				const all = expanded.includes(entry.id);
				const shown = all
					? rows
					: rows.filter((session, index) => index < ROWS_PER_PROJECT || session.id === activeId || isWaitingOnYou(statusSignal(session)));
				return (
					<NavSection key={entry.id} title={entry.name} collapsed={collapsed}>
						{shown.flatMap((session) => {
							const status = sessionStatusLabel(session);
							const viewing = session.id === activeId ? viewRun(session.id) : undefined;
							// The agents a session started hang under it, a step in per level, while the rail is open.
							const runs = collapsed
								? []
								: (session.runs ?? []).map((run) => (
										<NavRow
											key={`${session.id}:${run.id}`}
											label={run.name}
											collapsed={collapsed}
											active={viewing === run.id}
											muted={!isWaitingOnYou(run.status)}
											leading={
												<span className="grid size-4 shrink-0 place-items-center" style={{ marginInlineStart: `${run.depth * 14}px` }}>
													<AgentRing signal={run.status} />
												</span>
											}
											onClick={go(() => {
												activate(session.id);
												openRun(session.id, run.id);
											})}
										/>
									));
							return [
								<NavRow
									key={session.id}
									label={session.title}
									labelNode={<SessionTitle session={session} />}
									collapsed={collapsed}
									active={session.id === activeId && !viewing}
									muted={!session.unread && !isWaitingOnYou(statusSignal(session))}
									leading={<SessionGlyph session={session} projectName={project(session.projectId).name} />}
									trailing={<span className="min-w-8 shrink-0 text-end text-xs text-subtle-foreground tabular-nums">{session.updatedLabel}</span>}
									// The tooltip carries the whole title as well as the state, since the row may truncate it.
									tip={
										status ? (
											<>
												{session.title}
												<span className="block text-muted-foreground">{status}</span>
											</>
										) : undefined
									}
									onClick={go(() => {
										activate(session.id);
										openRun(session.id, undefined);
									})}
								/>,
								...runs
							];
						})}
						{shown.length < rows.length ? (
							<NavRow
								label={`Show all ${formatCount(rows.length)} sessions in ${entry.name}`}
								labelNode={`Show all ${formatCount(rows.length)}`}
								collapsed={collapsed}
								muted
								leading={<RowIcon icon={ChevronDown} />}
								onClick={() => setExpanded((current) => [...current, entry.id])}
							/>
						) : null}
					</NavSection>
				);
			})}
		</SidebarFrame>
	);
}

'use client';

import { History, LayoutGrid, PanelLeft, Plus, Search, X } from 'lucide-react';
import * as React from 'react';

import { formatCount, plural } from '@/lib/intl';
import { cn } from '@/lib/utils';
import { isWaitingOnYou, statusSignal } from '@/components/ui/agents-builder/agent-status';
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuLabel, DropdownMenuTrigger } from '@/components/ui/dropdown-menu';
import { Tabs, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { MiddleTruncate } from '@/components/ui/workspace-kit/middle-truncate';
import { iconButtonClass, TooltipIconButton } from '@/components/ui/workspace-kit/primitives';
import { type LiveSession, useCodingAgent } from '@/components/ui/coding-agent/coding-agent-context';
import { SessionGlyph, sessionStatusLabel, SessionTitle } from '@/components/ui/coding-agent/session-glyph';
import { withShortcut } from '@/components/ui/coding-agent/shortcuts';
import { tabCloseClass, toolbarButtonClass } from '@/components/ui/coding-agent/session-surface';


function RenameField({ session, onDone }: { session: LiveSession; onDone: () => void }) {
	const { patchSession, emit } = useCodingAgent();
	const [value, setValue] = React.useState(session.title);
	const commit = () => {
		const title = value.trim();
		if (title && title !== session.title) {
			patchSession(session.id, { title });
			emit({ type: 'rename-session', sessionId: session.id, title });
		}
		onDone();
	};
	return (
		<input
			autoFocus
			dir="auto"
			aria-label="Session title"
			value={value}
			onChange={(event) => setValue(event.target.value)}
			onFocus={(event) => event.target.select()}
			onBlur={commit}
			onKeyDown={(event) => {
				if (event.key === 'Enter') commit();
				if (event.key === 'Escape') onDone();
			}}
			className="absolute inset-y-0.5 start-7 end-1 z-10 min-w-0 rounded-[5px] bg-background px-1.5 text-[0.8125rem] text-foreground shadow-xs outline-none ring-1 ring-ring/60"
		/>
	);
}

function SessionTab({ session, active }: { session: LiveSession; active: boolean }) {
	const { project, closeSession, renaming, setRenaming } = useCodingAgent();
	const status = sessionStatusLabel(session);
	return (
		<div data-active={active || undefined} className="group/tab relative flex shrink-0">
			<TabsTrigger
				value={session.id}
				title={status ? `${session.title} · ${status}` : session.title}
				aria-label={status ? `${session.title}, ${status}` : session.title}
				onDoubleClick={() => setRenaming(session.id)}
				onKeyDown={(event) => {
					if (event.key === 'F2') {
						event.preventDefault();
						setRenaming(session.id);
					} else if (event.key === 'Delete' || event.key === 'Backspace') {
						// The close button stays out of the tab order, so the keyboard closes a tab from the tab itself.
						event.preventDefault();
						closeSession(session.id);
					}
				}}
				// Middle-click closes, as in any tabbed app; holding the button down must not start autoscroll first.
				onMouseDown={(event) => {
					if (event.button === 1) event.preventDefault();
				}}
				onAuxClick={(event) => {
					if (event.button === 1) closeSession(session.id);
				}}
				className={cn(
					'h-7 min-h-7 w-48 justify-start gap-2 ps-2 pe-7 text-[0.8125rem] font-normal text-muted-foreground @max-md/ws:w-36',
					'hover:text-foreground data-[active]:text-foreground pointer-coarse:min-h-9'
				)}
			>
				<SessionGlyph session={session} projectName={project(session.projectId).name} />
				<SessionTitle session={session} />
			</TabsTrigger>
			{renaming === session.id ? <RenameField session={session} onDone={() => setRenaming(null)} /> : null}
			<button type="button" tabIndex={-1} aria-label={`Close ${session.title}`} onClick={() => closeSession(session.id)} className={tabCloseClass}>
				<X aria-hidden="true" className="size-3.5" />
			</button>
		</div>
	);
}

/**
 * The window strip: a home toggle, one tab per open session with its live status, a new-session button, the
 * recently closed menu, and the layout switch. Tabs scroll sideways with faded edges once they overflow, and a
 * vertical wheel scrolls them too.
 */
export function SessionTabs() {
	const { openIds, activeId, activate, goHome, newSession, recentlyClosed, reopenClosed, session, setLayout, openCommandMenu, project } =
		useCodingAgent();
	const open = openIds.map(session).filter((entry): entry is LiveSession => Boolean(entry));
	const closed = recentlyClosed.map(session).filter((entry): entry is LiveSession => Boolean(entry));
	const waiting = open.filter((entry) => isWaitingOnYou(statusSignal(entry))).length;

	return (
		<div role="toolbar" aria-label="Sessions" className="flex h-10 shrink-0 items-center gap-1 px-2">
			<TooltipIconButton
				label={waiting ? `All sessions (${formatCount(waiting)} ${plural(waiting, { one: 'needs', other: 'need' })} you)` : 'All sessions'}
				aria-pressed={activeId === null}
				onClick={goHome}
				className={cn(toolbarButtonClass, activeId === null && 'bg-overlay-hover text-foreground')}
			>
				<LayoutGrid aria-hidden="true" className="size-3.5" />
				{/* A session waiting on you may be scrolled out of the strip; this keeps it from going unnoticed. */}
				{waiting ? <span aria-hidden="true" className="absolute end-1 top-1 size-1.5 rounded-full bg-warning ring-2 ring-sidebar" /> : null}
			</TooltipIconButton>
			<span aria-hidden="true" className="mx-1 h-4 w-px shrink-0 bg-border" />
			<Tabs value={activeId ?? ''} onValueChange={(value) => value && activate(String(value))} className="min-w-0 shrink gap-0">
				<TabsList
					aria-label="Open sessions"
					className="h-8 gap-0.5 rounded-lg bg-transparent p-0.5"
					// A mouse wheel scrolls vertically; the strip turns that into sideways movement.
					onWheel={(event) => {
						if (Math.abs(event.deltaY) > Math.abs(event.deltaX)) event.currentTarget.scrollLeft += event.deltaY;
					}}
				>
					{open.map((entry) => (
						<SessionTab key={entry.id} session={entry} active={entry.id === activeId} />
					))}
				</TabsList>
			</Tabs>
			<TooltipIconButton label={withShortcut('New session', 'newSession')} onClick={newSession} className={toolbarButtonClass}>
				<Plus aria-hidden="true" className="size-3.5" />
			</TooltipIconButton>
			{closed.length > 0 ? (
				<DropdownMenu>
					<DropdownMenuTrigger
						aria-label="Recently closed"
						title="Recently closed"
						className={cn(iconButtonClass({ menu: true }), toolbarButtonClass)}
					>
						<History aria-hidden="true" className="size-3.5" />
					</DropdownMenuTrigger>
					<DropdownMenuContent align="start" className="w-72 max-w-[calc(100vw-2rem)]">
						<DropdownMenuLabel>Recently closed</DropdownMenuLabel>
						{closed.map((entry) => (
							<DropdownMenuItem key={entry.id} title={entry.title} onClick={() => reopenClosed(entry.id)}>
								<SessionGlyph session={entry} projectName={project(entry.projectId).name} />
								{/* Titles that share a long start differ at the end, so the end stays visible. */}
								<MiddleTruncate text={entry.title} tail={14} title={false} className="flex-1" />
							</DropdownMenuItem>
						))}
					</DropdownMenuContent>
				</DropdownMenu>
			) : null}
			<div className="min-w-2 flex-1" />
			<TooltipIconButton label={withShortcut('Search commands', 'commandMenu')} onClick={openCommandMenu} className={toolbarButtonClass}>
				<Search aria-hidden="true" className="size-3.5" />
			</TooltipIconButton>
			<TooltipIconButton label="Show sessions in a sidebar" onClick={() => setLayout('sidebar')} className={toolbarButtonClass}>
				<PanelLeft aria-hidden="true" className="size-3.5 rtl:-scale-x-100" />
			</TooltipIconButton>
		</div>
	);
}

'use client';

import { ArrowRight, GitCompareArrows, Split } from 'lucide-react';
import * as React from 'react';
import { flushSync } from 'react-dom';

import { plural } from '@/lib/intl';
import { AgentRing } from '@/components/ui/agents-builder/agent-status';
import { type AskAnswer, AskCard } from '@/components/ui/ai/ask-card';
import { formatCompact } from '@/components/ui/ai/context-ring';
import { FeedbackBar } from '@/components/ui/ai/feedback-bar';
import { InlineDiff } from '@/components/ui/ai/inline-diff';
import { Message, MessageContent } from '@/components/ui/ai/message';
import { Reasoning } from '@/components/ui/ai/reasoning';
import { SystemMessage } from '@/components/ui/ai/system-message';
import { ThinkingStatus } from '@/components/ui/ai/thinking-status';
import { Tool, ToolGroup } from '@/components/ui/ai/tool';
import type { ToolStatus } from '@/components/ui/ai/types';
import { Button } from '@/components/ui/button';
import { useLatest } from '@/components/ui/workspace-kit/use-latest';
import { displayUrl } from '@/components/ui/coding-agent/browser-panel';
import { type HarnessView, type RunView, runTokens, TASK_TURN_ID, type TimelineItem } from '@/components/ui/coding-agent/harness';
import { AgentMark, MessageRoute, nameOf, plainText, recipientNames, runStateLabel } from '@/components/ui/coding-agent/run-presentation';
import type { SessionBeatKind } from '@/components/ui/coding-agent/types';
import { revealDuration, type SessionHarness } from '@/components/ui/coding-agent/use-harness';

const TOOL_NAME: Record<string, string> = {
	read: 'Read',
	grep: 'Grep',
	glob: 'Glob',
	list: 'List',
	webfetch: 'Fetch',
	websearch: 'Search'
};

/** Lines of command output shown in the transcript: the end, where the result is. */
const SHELL_TAIL = 40;

const DECISION_LABEL = { once: 'Allowed once', always: 'Always allowed', deny: 'Denied' } as const;

/** The live line under the timeline names what the agent is about to do. */
const UPCOMING_LABEL: Partial<Record<SessionBeatKind, string>> = {
	reasoning: 'Thinking',
	tools: 'Exploring',
	edit: 'Making edits',
	shell: 'Running commands',
	browse: 'Opening the browser',
	say: 'Writing',
	plan: 'Planning',
	spawn: 'Starting agents',
	message: 'Writing to another agent',
	route: 'Choosing an agent'
};

/** How a run's state reads in a tool card's status slot. */
function toolStatus(run: RunView): ToolStatus {
	if (run.status === 'done' || run.status === 'idle') return 'success';
	if (run.status === 'failed') return 'error';
	if (run.status === 'cancelled') return 'aborted';
	if (run.status === 'queued') return 'pending';
	return 'running';
}

/** Holds `live` true for `ms` after mount, so a beat that just landed can play out its reveal. */
function useLiveFor(live: boolean, ms: number) {
	const [active, setActive] = React.useState(live);
	React.useEffect(() => {
		if (!live) return;
		const timer = window.setTimeout(() => setActive(false), ms);
		return () => window.clearTimeout(timer);
	}, [live, ms]);
	return active;
}

/** Streams a reply in over its reveal time, rendering markdown as it grows, as a live token stream would. */
function Say({ text, live }: { text: string; live: boolean }) {
	const duration = revealDuration(text);
	const [shown, setShown] = React.useState(live ? 0 : text.length);
	React.useEffect(() => {
		if (!live) return;
		const start = performance.now();
		let frame = 0;
		const tick = (now: number) => {
			const share = Math.min((now - start) / duration, 1);
			setShown(Math.round(text.length * share));
			if (share < 1) frame = requestAnimationFrame(tick);
		};
		frame = requestAnimationFrame(tick);
		return () => cancelAnimationFrame(frame);
	}, [duration, live, text]);
	return (
		<Message from="assistant">
			<MessageContent markdown streaming={shown < text.length}>
				{text.slice(0, shown)}
			</MessageContent>
		</Message>
	);
}

function Thought({ text, durationMs, live }: { text: string; durationMs: number; live: boolean }) {
	const streaming = useLiveFor(live, durationMs);
	return <Reasoning content={text} isStreaming={streaming} durationMs={streaming ? null : durationMs} markdown />;
}

type Handlers = {
	harness: SessionHarness;
	runId: string;
	onReview: (path?: string) => void;
	onBrowse: (url: string) => void;
	onOpenRun: (runId: string) => void;
};

/** Callbacks a row needs, kept stable for the life of the transcript so memoized rows skip unrelated updates. */
type RowActions = {
	review: (path?: string) => void;
	browse: (url: string) => void;
	openRun: (runId: string) => void;
	stop: (runId: string) => void;
	retry: () => void;
	answer: (requestId: string, answer: AskAnswer) => void;
};

/**
 * One step of the transcript. Memoized: the harness keeps an item's identity until it changes, so a new event
 * re-renders only the rows it touched, not hundreds of earlier ones.
 */
const BeatRow = React.memo(function BeatRow({
	item,
	live,
	final,
	retryable,
	actions
}: {
	item: Extract<TimelineItem, { type: 'beat' }>;
	/** Landed since this transcript opened, so it plays its reveal. */
	live: boolean;
	/** The last reply of a finished turn, which gets the copy and feedback actions. */
	final: boolean;
	/** The run failed and can be retried from here. */
	retryable: boolean;
	actions: RowActions;
}) {
	return (
		// The id anchors the turn rail's jumps; the margin keeps a jumped-to message clear of the top edge.
		// Rows out of view skip layout and paint, sized from their last render, so a long thread scrolls smoothly.
		<div
			data-item-id={item.id}
			className="min-w-0 scroll-mt-6 animate-[ai-fade-up_var(--duration-slow)_var(--ease-out)_both] [contain-intrinsic-size:auto_3rem] [content-visibility:auto] motion-reduce:animate-none"
		>
			<BeatBody item={item} live={live} retryable={retryable} actions={actions} />
			{final && item.beat.kind === 'say' ? <FeedbackBar className="mt-1" copyText={item.beat.text} showRegenerate={false} /> : null}
		</div>
	);
});

function BeatBody({ item, live, retryable, actions }: { item: Extract<TimelineItem, { type: 'beat' }>; live: boolean; retryable: boolean; actions: RowActions }) {
	const beat = item.beat;
	switch (beat.kind) {
		case 'user':
			return (
				<Message from="user">
					<MessageContent>{beat.text}</MessageContent>
				</Message>
			);
		case 'reasoning':
			return <Thought text={beat.text} durationMs={beat.durationMs} live={live} />;
		case 'say':
			return <Say text={beat.text} live={live} />;
		case 'tools': {
			const names = [...new Set(beat.calls.map((call) => TOOL_NAME[call.tool]))].join(', ');
			return (
				<ToolGroup
					defaultOpen={false}
					className="max-w-none"
					label={
						<>
							{item.running ? 'Running' : 'Used'} {beat.calls.length} <span className="font-medium text-foreground">{names}</span>
						</>
					}
				>
					{beat.calls.map((call, index) => (
						<Tool key={index} name={TOOL_NAME[call.tool]} summary={call.target} status={item.running ? 'running' : 'success'} />
					))}
				</ToolGroup>
			);
		}
		case 'edit': {
			const created = item.before === null || item.before === undefined;
			// The inline diff names the file and counts the lines, so the row doesn't repeat them.
			return (
				<Tool name={created ? 'Create' : 'Edit'} summary={beat.path} status="success">
					<InlineDiff source={{ before: item.before ?? '', after: beat.after, fileName: beat.path }} maxLines={14} />
					<Button size="xs" variant="ghost" className="-ms-2 text-muted-foreground" onClick={() => actions.review(beat.path)}>
						<GitCompareArrows aria-hidden="true" />
						Open in Files changed
					</Button>
				</Tool>
			);
		}
		case 'shell': {
			const lines = beat.output.replace(/\n+$/, '').split('\n');
			const earlier = Math.max(lines.length - SHELL_TAIL, 0);
			// Output can run to hundreds of lines; the end is where a failure says what went wrong, so that's what shows.
			const output = beat.output
				? earlier
					? [`… ${earlier} earlier ${plural(earlier, { one: 'line', other: 'lines' })}`, ...lines.slice(earlier)].join('\n')
					: lines.join('\n')
				: undefined;
			return (
				<Tool
					variant="card"
					name="Shell"
					summary={beat.command}
					status={item.running ? 'running' : beat.exitCode ? 'error' : 'success'}
					output={item.running ? undefined : output}
					errorText={!item.running && beat.exitCode ? `Exited with code ${beat.exitCode}` : undefined}
					defaultOpen={Boolean(beat.exitCode)}
				>
					<code dir="ltr" className="block text-start font-mono text-[0.75rem] whitespace-pre-wrap text-foreground [overflow-wrap:anywhere]">
						<span aria-hidden="true" className="text-subtle-foreground select-none">
							${' '}
						</span>
						{beat.command}
					</code>
				</Tool>
			);
		}
		case 'browse':
			return (
				<Tool name="Browser" summary={displayUrl(beat.url)} status="success">
					<Button size="xs" variant="ghost" className="-ms-2 text-muted-foreground" onClick={() => actions.browse(beat.url)}>
						Show in the browser panel
					</Button>
				</Tool>
			);
		case 'notice':
			return <p className="max-w-prose text-xs text-pretty text-muted-foreground [overflow-wrap:anywhere]">{beat.text}</p>;
		case 'error': {
			return (
				<SystemMessage variant="destructive" title={beat.title}>
					<p className="[overflow-wrap:anywhere]">{beat.text}</p>
					{retryable ? (
						<Button size="xs" variant="outline" className="mt-2" onClick={actions.retry}>
							Retry
						</Button>
					) : null}
				</SystemMessage>
			);
		}
	}
}

/**
 * A sub-agent the run started, where it started it: the agent, its task, what it's doing or what it found, and a
 * way into its own transcript.
 */
const SpawnCard = React.memo(function SpawnCard({ child, stateLabel, actions }: { child: RunView; stateLabel: string; actions: RowActions }) {
	const status = toolStatus(child);
	const live = status === 'running' || status === 'pending';
	const detail = live ? child.lastTool : child.summary && plainText(child.summary);
	// A card opens if its agent was working when it appeared; after that it stays as you leave it.
	const [openAtFirst] = React.useState(live);
	return (
		<Tool variant="card" name={child.name} summary={child.task} status={status} defaultOpen={openAtFirst}>
			<div className="flex flex-col gap-2">
				<p className="flex flex-wrap items-center gap-x-1.5 gap-y-1 text-xs text-muted-foreground">
					<span>{stateLabel}</span>
					{child.kind ? <span>· {child.kind}</span> : null}
					{child.workspace?.branch ? <span className="font-mono">· {child.workspace.branch}</span> : null}
					<span className="tabular-nums">· {formatCompact(runTokens(child))} tokens</span>
					{child.background ? <span>· background</span> : null}
				</p>
				{detail ? <p className="line-clamp-3 text-[0.8125rem] text-pretty text-foreground [overflow-wrap:anywhere]">{detail}</p> : null}
				<div className="-ms-2 flex flex-wrap gap-1">
					<Button size="xs" variant="ghost" className="text-muted-foreground" onClick={() => actions.openRun(child.id)}>
						Open {child.name}
						<ArrowRight aria-hidden="true" className="rtl:-scale-x-100" />
					</Button>
					{live && child.capabilities?.stop !== false ? (
						<Button size="xs" variant="ghost" className="text-muted-foreground" onClick={() => actions.stop(child.id)}>
							Stop
						</Button>
					) : null}
				</div>
			</div>
		</Tool>
	);
});

/** Where a parent picks its workers' results back up: one line per worker with what it reported. */
function FanIn({ runIds, view, onOpenRun }: { runIds: string[]; view: HarnessView; onOpenRun: (runId: string) => void }) {
	const runs = runIds.map((id) => view.runs[id]).filter((run): run is RunView => Boolean(run));
	return (
		<ToolGroup
			className="max-w-none"
			defaultOpen
			label={
				<>
					Results from <span className="tabular-nums">{runs.length}</span> {plural(runs.length, { one: 'agent', other: 'agents' })}
				</>
			}
		>
			{runs.map((run) => (
				<button
					key={run.id}
					type="button"
					onClick={() => onOpenRun(run.id)}
					className="-mx-1 flex min-h-8 items-start gap-2 rounded-md px-1 py-1 text-start text-[0.8125rem] hover:bg-accent"
				>
					<AgentMark name={run.name} className="mt-0.5" />
					<span className="min-w-0 flex-1">
						<span className="font-medium text-foreground">{run.name}</span>{' '}
						<span className="text-muted-foreground [overflow-wrap:anywhere]">{run.summary ? plainText(run.summary) : runStateLabel(run, view)}</span>
					</span>
				</button>
			))}
		</ToolGroup>
	);
}

const PROTOCOL_LABEL = { 'plan-approval': 'Plan for approval', shutdown: 'Asks to wrap up', steer: 'Steer', result: 'Result', text: '' } as const;

/** A message between agents, or from you to one: who to whom, then what was said. */
const AgentMessage = React.memo(function AgentMessage({ item, from, to }: { item: Extract<TimelineItem, { type: 'message' }>; from: string; to: string }) {
	const label = PROTOCOL_LABEL[item.protocol];
	return (
		<div className="flex flex-col gap-1.5">
			<MessageRoute from={from} to={to} label={label} />
			<div className="ms-6 rounded-lg bg-muted/50 px-3 py-2">
				<MessageContent markdown>{item.text}</MessageContent>
			</div>
		</div>
	);
});

/** The last reply of each finished turn, which gets the copy and feedback actions. */
function settledReplies(items: TimelineItem[], running: boolean) {
	const finals = new Set<string>();
	let lastSay: string | null = null;
	for (const item of items) {
		if (item.type === 'beat' && item.beat.kind === 'user') {
			if (lastSay) finals.add(lastSay);
			lastSay = null;
		} else if (item.type === 'beat' && item.beat.kind === 'say') {
			lastSay = item.id;
		}
	}
	if (lastSay && !running) finals.add(lastSay);
	return finals;
}

/** What the live status line says: the step in progress if there is one, else the one about to start. */
function statusLabel(run: RunView, upcoming: SessionBeatKind | undefined, view: HarnessView) {
	if (run.status === 'waiting' && run.waitingOn?.kind === 'agent') return runStateLabel(run, view);
	for (let index = run.items.length - 1; index >= 0; index -= 1) {
		const item = run.items[index];
		if (item.type === 'beat' && item.running) return UPCOMING_LABEL[item.beat.kind] ?? 'Working';
	}
	return UPCOMING_LABEL[upcoming ?? 'say'] ?? 'Working';
}

/** Rows a transcript renders when it opens, and how many more it adds each time you scroll near the top. */
const HISTORY_CHUNK = 120;

export type TimelineHandle = {
	/** Renders history down to the row with this id if it isn't yet, and returns its element. */
	reveal: (id: string) => HTMLElement | null;
};

/**
 * One run's transcript, rendered entirely from AI kit parts: messages, reasoning, tool groups, edits with inline
 * diffs, commands, questions, sub-agent cards and their results, messages between agents, handoffs, phases, and a
 * summary of what each turn changed.
 */
export function SessionTimeline({
	harness,
	runId,
	onReview,
	onBrowse,
	onOpenRun,
	onAnswered,
	scroller,
	handle
}: Handlers & {
	onAnswered: () => void;
	/** The transcript's scroller, which earlier history loads against as you scroll up. */
	scroller: () => HTMLElement | null;
	handle?: React.Ref<TimelineHandle>;
}) {
	const view = harness.view;
	const run = view.runs[runId];
	// Steps already in the transcript when it opens are history: they don't replay their reveal when you come back.
	const [settledBefore] = React.useState(() => run?.items.length ?? 0);
	// A long thread opens on its latest rows; earlier ones render in chunks as you scroll up, so opening it stays quick.
	const [renderFrom, setRenderFrom] = React.useState(() => Math.max(0, (run?.items.length ?? 0) - HISTORY_CHUNK));
	const root = React.useRef<HTMLDivElement>(null);
	const sentinel = React.useRef<HTMLDivElement>(null);
	const items = run?.items;
	React.useImperativeHandle(
		handle,
		() => ({
			reveal: (id) => {
				const index = items?.findIndex((item) => item.id === id) ?? -1;
				if (index >= 0 && index < renderFrom) flushSync(() => setRenderFrom(Math.max(0, index - 8)));
				return root.current?.querySelector<HTMLElement>(`[data-item-id="${CSS.escape(id)}"]`) ?? null;
			}
		}),
		[items, renderFrom]
	);
	React.useEffect(() => {
		const node = sentinel.current;
		if (!node || renderFrom === 0) return;
		if (typeof IntersectionObserver === 'undefined') {
			setRenderFrom(0);
			return;
		}
		const observer = new IntersectionObserver(
			([entry]) => {
				// The browser keeps the rows you're reading in place as earlier ones are added above them.
				if (entry?.isIntersecting) setRenderFrom((from) => Math.max(0, from - HISTORY_CHUNK));
			},
			{ root: scroller(), rootMargin: '1200px 0px 0px 0px' }
		);
		observer.observe(node);
		return () => observer.disconnect();
	}, [renderFrom, scroller]);
	// The rows get callbacks that never change, so they can skip re-rendering; these read the newest props when called.
	const latest = useLatest({ harness, runId, onReview, onBrowse, onOpenRun, onAnswered });
	const actions = React.useMemo<RowActions>(
		() => ({
			review: (path) => latest.current.onReview(path),
			browse: (url) => latest.current.onBrowse(url),
			openRun: (id) => latest.current.onOpenRun(id),
			stop: (id) => latest.current.harness.stop(id),
			retry: () => latest.current.harness.retry(latest.current.runId),
			answer: (requestId, answer) => {
				latest.current.harness.answer(requestId, answer);
				latest.current.onAnswered();
			}
		}),
		[latest]
	);
	if (!run) return null;
	const busy = run.status === 'running' || (run.status === 'waiting' && run.waitingOn?.kind === 'agent');
	const lastIndex = run.items.length - 1;
	const last = run.items[lastIndex];
	const isLive = (item: TimelineItem, index: number) => item.type === 'beat' && item.live && index >= settledBefore;
	// A reply or thought that is still playing speaks for itself, so the live status line steps aside.
	const playing = last?.type === 'beat' && isLive(last, lastIndex) && (last.beat.kind === 'say' || last.beat.kind === 'reasoning');
	const finals = settledReplies(run.items, busy);
	const parent = run.parentRunId ? view.runs[run.parentRunId] : undefined;
	const retryable = run.status === 'failed';

	return (
		<div ref={root} className="flex flex-col gap-3">
			{renderFrom > 0 ? <div ref={sentinel} aria-hidden="true" className="h-px" /> : null}
			{parent && run.task && renderFrom === 0 ? (
				// A child's transcript opens with what it was asked to do, which is also its first turn on the rail.
				<Message from="user" data-item-id={TASK_TURN_ID} className="scroll-mt-6">
					<MessageContent>
						<span className="mb-1 block text-xs text-muted-foreground">Task from {parent.name}</span>
						{run.task}
					</MessageContent>
				</Message>
			) : null}
			{run.items.map((item, index) => {
				if (index < renderFrom) return null;
				if (item.type === 'beat') {
					return (
						<BeatRow
							key={item.id}
							item={item}
							live={isLive(item, index)}
							final={finals.has(item.id)}
							retryable={item.beat.kind === 'error' && retryable}
							actions={actions}
						/>
					);
				}
				if (item.type === 'spawn') {
					const child = view.runs[item.runId];
					return child ? <SpawnCard key={item.id} child={child} stateLabel={runStateLabel(child, view)} actions={actions} /> : null;
				}
				if (item.type === 'fan-in') return <FanIn key={item.id} runIds={item.runIds} view={view} onOpenRun={actions.openRun} />;
				if (item.type === 'message') {
					return (
						<AgentMessage
							key={item.id}
							item={item}
							from={nameOf(view, item.from)}
							to={recipientNames(view, item.to)}
						/>
					);
				}
				if (item.type === 'handoff') {
					return (
						<p key={item.id} className="flex items-center gap-1.5 text-xs text-muted-foreground">
							<Split aria-hidden="true" className="size-3.5 shrink-0" />
							<span>
								Control passed to <span className="font-medium text-foreground">{nameOf(view, item.to)}</span>
								{item.reason ? ` · ${item.reason}` : ''}
							</span>
						</p>
					);
				}
				if (item.type === 'route') return <Tool key={item.id} name={`Chose ${nameOf(view, item.to)}`} summary={item.reason} status="success" />;
				if (item.type === 'phase') {
					return (
						<div key={item.id} className="flex items-center gap-2 pt-2 text-xs font-medium text-muted-foreground">
							<AgentRing signal={item.status === 'running' ? 'running' : 'done'} />
							<span className="text-foreground">{item.name}</span>
							<span aria-hidden="true" className="h-px flex-1 bg-border" />
						</div>
					);
				}
				if (item.type === 'permission') {
					// A pending request waits in the dock above the composer; once decided it leaves a line here.
					if (!item.decision) return null;
					return <Tool key={item.id} name={DECISION_LABEL[item.decision]} summary={item.beat.command} status={item.decision === 'deny' ? 'aborted' : 'success'} />;
				}
				if (item.type === 'question') {
					return (
						<AskCard
							key={item.id}
							eyebrow={runId === view.rootRunId ? 'The agent has a question' : `${run.name} has a question`}
							questions={item.beat.questions}
							answer={item.answer}
							onSubmit={(choices) => actions.answer(item.requestId, { choices })}
							onSkip={() => actions.answer(item.requestId, { skipped: true })}
						/>
					);
				}
				return (
					<div key={item.id}>
						<Button size="xs" variant="outline" className="text-muted-foreground" onClick={() => actions.review(item.paths[0])}>
							<GitCompareArrows aria-hidden="true" />
							<span>
								<span className="tabular-nums">{item.paths.length}</span> {plural(item.paths.length, { one: 'file', other: 'files' })} changed
							</span>
							{item.additions ? <span className="font-mono text-success tabular-nums">+{item.additions}</span> : null}
							{item.deletions ? <span className="font-mono text-destructive tabular-nums">−{item.deletions}</span> : null}
						</Button>
					</div>
				);
			})}
			{busy && !playing ? (
				// One status line per run: its clock keeps counting as the label moves from step to step.
				<ThinkingStatus label={statusLabel(run, harness.upcoming(runId), view)} tokens={runTokens(run)} tokensPerTick={0} className="px-0" />
			) : null}
		</div>
	);
}

'use client';

import * as React from 'react';

import { useMergedRefs } from '@/lib/compose-refs';
import { cn } from '@/lib/utils';
import { ChatContainer, ChatContainerContent } from '@/components/ui/ai/chat-container';
import type { ModelSelection } from '@/components/ui/ai/model-selector';
import { PlanTracker } from '@/components/ui/ai/plan-tracker';
import { ScrollButton } from '@/components/ui/ai/scroll-button';
import { Button } from '@/components/ui/button';
import { useElementSize, useScrollbarInset } from '@/components/ui/workspace-kit/use-element-size';
import { AgentsPanel, TasksPanel } from '@/components/ui/coding-agent/agents-panel';
import { useColorScheme } from '@/components/ui/coding-agent/code-surface-theme';
import { type LiveSession, type SessionHandle, useSessionShell } from '@/components/ui/coding-agent/coding-agent-context';
import { demoShell } from '@/components/ui/coding-agent/demo-shell';
import { FilePickerDialog } from '@/components/ui/coding-agent/file-picker-dialog';
import { descendants, runSignal, runTokens, sessionChecks } from '@/components/ui/coding-agent/harness';
import { RequestDock } from '@/components/ui/coding-agent/request-dock';
import { ReviewPanel } from '@/components/ui/coding-agent/review-panel';
import { nameOf } from '@/components/ui/coding-agent/run-presentation';
import { SessionComposer } from '@/components/ui/coding-agent/session-composer';
import { SessionHeader } from '@/components/ui/coding-agent/session-header';
import { columnClass, SessionLayout } from '@/components/ui/coding-agent/session-layout';
import { frameClasses } from '@/components/ui/coding-agent/session-surface';
import { SessionTimeline, type TimelineHandle } from '@/components/ui/coding-agent/session-timeline';
import { SidePanel, type SidePanelHandle } from '@/components/ui/coding-agent/side-panel';
import { TerminalPanel } from '@/components/ui/coding-agent/terminal-panel';
import { TurnRail } from '@/components/ui/coding-agent/turn-rail';
import { useDraftContext } from '@/components/ui/coding-agent/use-draft-context';
import { isHosted, useHarness } from '@/components/ui/coding-agent/use-harness';
import { usePanelTabs } from '@/components/ui/coding-agent/use-panel-tabs';

/** Below this width the chat and the side panel take turns instead of sitting side by side. */
const SPLIT_MIN_WIDTH = 760;

/**
 * One session: the chat column (header, transcript, docks, composer), a resizable side panel with review, file and
 * browser tabs, and a terminal dock along the bottom. Every session in the tab strip stays mounted, so background
 * runs keep playing and report their status to the shell.
 */
export const SessionView = React.memo(function SessionView({
	session,
	active,
	viewRunId: requested,
	defaultPanelOpen,
	defaultTerminalOpen
}: {
	session: LiveSession;
	active: boolean;
	/** The agent on screen, when it isn't the session's own. */
	viewRunId?: string;
	defaultPanelOpen: boolean;
	defaultTerminalOpen: boolean;
}) {
	const { data, project: projectOf, patchSession, emit, activeHandle, renderBrowserPage, deleteSession, layout, openRun } = useSessionShell();
	const frame = frameClasses(layout);
	const project = projectOf(session.projectId);
	const branch = session.branch ?? project.branch;
	const harness = useHarness({ session, files: project.files, branch, followUp: data.followUp, emit });
	const view = harness.view;
	const rootId = view.rootRunId;
	// The agent on screen: the session's own, or one of the agents it started.
	const viewRunId = requested && view.runs[requested] ? requested : rootId;
	const viewed = view.runs[viewRunId];
	const viewingChild = viewRunId !== rootId;
	const showRun = React.useCallback((runId: string) => openRun(session.id, runId === rootId ? undefined : runId), [openRun, rootId, session.id]);
	const others = descendants(view, rootId);
	const runNames = React.useMemo(() => Object.fromEntries(view.runOrder.map((id) => [id, view.runs[id]?.name ?? id])), [view.runOrder, view.runs]);
	const paths = React.useMemo(() => Object.keys(harness.files).sort(), [harness.files]);

	// The session's own size decides between side by side and one at a time, and how tall the terminal may get. In a
	// background tab it measures 0×0; keeping its last real size stops it flipping to the narrow layout, which would
	// remount the chat and panel and lose drafts and split sizes.
	const rootRef = React.useRef<HTMLDivElement>(null);
	const [sizeRef, size] = useElementSize<HTMLDivElement>({ ignoreHidden: true });
	const root = useMergedRefs(rootRef, sizeRef);
	const scheme = useColorScheme(rootRef);
	const narrow = size.width < SPLIT_MIN_WIDTH;
	// The composer sits outside the transcript's scroller, so it takes the scrollbar's width on that side to keep
	// both columns on one axis. The ref follows the scroller when a layout switch remounts the chat.
	const scrollerRef = React.useRef<HTMLDivElement>(null);
	const [insetRef, scrollbarInset] = useScrollbarInset<HTMLDivElement>();
	const scroller = useMergedRefs(scrollerRef, insetRef);
	const chatScroller = React.useCallback(() => scrollerRef.current, []);
	const timelineRef = React.useRef<TimelineHandle>(null);
	const revealTurn = React.useCallback((id: string) => timelineRef.current?.reveal(id) ?? null, []);
	const composerRef = React.useRef<HTMLDivElement>(null);
	const focusComposer = () => composerRef.current?.querySelector('textarea')?.focus();

	const panel = usePanelTabs({
		defaultOpen: defaultPanelOpen,
		narrow,
		agents: others.length > 0,
		tasks: view.tasks.length > 0,
		onOpenFile: (path) => emit({ type: 'open-file', sessionId: session.id, path }),
		onOpenUrl: (url) => emit({ type: 'open-url', sessionId: session.id, url })
	});
	const { show: showTab, openBrowser, setOpen: setPanelOpen, toggleOpen: togglePanel, toggleTree: toggleTreeColumn } = panel;
	const sidePanel = React.useRef<SidePanelHandle>(null);
	const draft = useDraftContext();
	const [terminalOpen, setTerminalOpen] = React.useState(defaultTerminalOpen);
	const [focusPath, setFocusPath] = React.useState<{ path: string; nonce: number } | null>(null);
	const [model, setModel] = React.useState<ModelSelection>(session.model ?? data.defaultModel);
	const [filePicker, setFilePicker] = React.useState(false);

	// Report live state up, so the tab, sidebar rows and home list can show it, the session's other agents included.
	const runsKey = others.map((entry) => `${entry.id}:${entry.status}:${entry.waitingOn?.kind ?? ''}`).join('|');
	React.useEffect(() => {
		patchSession(session.id, {
			status: harness.status,
			// Two-percent steps: the tab's ring can't show finer, and each step re-renders the shell.
			progress: harness.progress === undefined ? undefined : Math.round(harness.progress * 50) / 50,
			changedFiles: harness.changes.length,
			runs: others.map((entry) => ({
				id: entry.id,
				name: entry.name,
				parentRunId: entry.parentRunId,
				depth: entry.depth,
				status: runSignal(entry, view)
			}))
		});
		// `runsKey` stands in for `others`, which is rebuilt every render.
		// eslint-disable-next-line react-hooks/exhaustive-deps
	}, [patchSession, session.id, harness.status, harness.progress, harness.changes.length, runsKey]);

	// A run that stops while you look elsewhere leaves its tab marked until you come back.
	const previousStatus = React.useRef(harness.status);
	React.useEffect(() => {
		if (previousStatus.current === 'running' && harness.status !== 'running' && !active) patchSession(session.id, { unread: true });
		previousStatus.current = harness.status;
	}, [active, patchSession, harness.status, session.id]);
	React.useEffect(() => {
		if (active && session.unread) patchSession(session.id, { unread: false });
	}, [active, patchSession, session.id, session.unread]);

	const openReview = React.useCallback(
		(path?: string) => {
			showTab('review');
			if (path) setFocusPath({ path, nonce: Date.now() });
		},
		[showTab]
	);

	// The agent opening a page puts it in the browser panel.
	React.useEffect(() => {
		if (harness.browse) openBrowser(harness.browse.url, harness.browse.title);
	}, [openBrowser, harness.browse]);

	// What shortcuts and the command menu can do here. It's built once from actions that never change, and the shell
	// holds it only while the session is in front, so a session that's hidden or gone never receives a shortcut.
	const handle = React.useMemo<SessionHandle>(
		() => ({
			togglePanel,
			toggleTerminal: () => setTerminalOpen((open) => !open),
			toggleTree: () => {
				// The panel on screen decides whether its tree is a column or an overlay; a closed one opens with its
				// column toggled.
				if (sidePanel.current) {
					sidePanel.current.toggleTree();
				} else {
					setPanelOpen(true);
					toggleTreeColumn();
				}
			},
			openBrowser: () => openBrowser(),
			openReview: () => openReview(),
			openFilePicker: () => setFilePicker(true)
		}),
		[openBrowser, openReview, setPanelOpen, togglePanel, toggleTreeColumn]
	);
	React.useEffect(() => {
		if (!active) return;
		activeHandle.current = handle;
		return () => {
			if (activeHandle.current === handle) activeHandle.current = null;
		};
	}, [active, activeHandle, handle]);

	const send = (text: string) => {
		const attachments = draft.take();
		// In another agent's view the composer steers that agent, attachments and all, rather than starting a turn of
		// the session's own.
		if (viewingChild) harness.steer(viewRunId, text, data.followUp(text), attachments);
		else harness.send(rootId, text, data.followUp(text), attachments);
	};

	// The plan stays docked while the turn that made it is live; once the agent is idle it would only be stale.
	const planLive = Boolean(viewed.plan) && (viewed.status === 'running' || viewed.status === 'waiting');
	const steerable = !viewingChild || viewed.capabilities?.steer !== false;

	const chatColumn = (
		<section aria-label={session.title} className={cn(columnClass, '@container/session')}>
			<SessionHeader
				session={session}
				view={view}
				viewRunId={viewRunId}
				branch={branch}
				others={others}
				tokens={viewingChild ? runTokens(viewed) : harness.tokens}
				contextWindow={data.contextWindow}
				terminalOpen={terminalOpen}
				panelOpen={panel.open}
				onToggleTerminal={handle.toggleTerminal}
				onTogglePanel={togglePanel}
				onShowRun={showRun}
				onShowAgents={() => showTab('agents')}
				onReview={handle.openReview}
				onExport={() => emit({ type: 'export-session', sessionId: session.id })}
				onDelete={() => deleteSession(session.id)}
			/>
			<div className="relative flex min-h-0 flex-1 flex-col">
				<ChatContainer ref={scroller} className="min-h-0 flex-1 px-6">
					<ChatContainerContent className="mx-auto w-full max-w-2xl gap-0 px-0 pt-8 pb-8">
						<SessionTimeline
							key={viewRunId}
							handle={timelineRef}
							harness={harness}
							runId={viewRunId}
							onReview={openReview}
							onBrowse={(url) => openBrowser(url)}
							onOpenRun={showRun}
							onAnswered={focusComposer}
							scroller={chatScroller}
						/>
					</ChatContainerContent>
					{/* A zero-height sticky row centres the button in either direction without taking space in the transcript. */}
					<div className="pointer-events-none sticky bottom-3 flex h-0 items-end justify-center">
						<ScrollButton className="pointer-events-auto relative bottom-auto left-auto translate-x-0" />
					</div>
				</ChatContainer>
				<TurnRail key={viewRunId} run={viewed} scroller={chatScroller} reveal={revealTurn} />
			</div>
			<div className="px-6 pb-5" style={scrollbarInset ? { paddingInlineEnd: `calc(1.5rem + ${scrollbarInset}px)` } : undefined}>
				<div className="mx-auto w-full max-w-2xl">
					<RequestDock harness={harness} viewRunId={viewRunId} />
					{planLive && viewed.plan ? (
						// Sits on the composer's top edge like a tab, so the plan reads as part of what you're steering.
						<PlanTracker plan={{ steps: viewed.plan }} streaming={viewed.status === 'running'} className="px-3" />
					) : null}
					{steerable ? (
						<SessionComposer
							key={viewRunId}
							placeholder={viewingChild ? `Steer ${viewed.name}…` : undefined}
							inputRef={composerRef}
							running={runSignal(viewed, view) === 'running'}
							onSubmit={send}
							onStop={() => harness.stop(viewRunId)}
							attachments={draft.attachments}
							onRemoveAttachment={draft.remove}
							queued={harness.queued(viewRunId)}
							onUnqueue={(id) => harness.unqueue(viewRunId, id)}
							commands={data.commands}
							files={paths}
							models={data.models}
							model={model}
							onModelChange={setModel}
							usagePercent={data.usagePercent}
							onAttachFiles={() => emit({ type: 'open-file', sessionId: session.id, path: '' })}
						/>
					) : (
						<div className="flex items-center justify-between gap-3 rounded-xl bg-muted/60 px-4 py-3 text-[0.8125rem] text-muted-foreground">
							<span>{viewed.name} can’t take messages directly.</span>
							<Button size="xs" variant="outline" onClick={() => showRun(viewed.parentRunId ?? rootId)}>
								Back to {nameOf(view, viewed.parentRunId ?? rootId)}
							</Button>
						</div>
					)}
				</div>
			</div>
		</section>
	);

	const panelColumn = (
		<section aria-label="Side panel" className={columnClass}>
			<SidePanel
				handle={sidePanel}
				panel={panel}
				files={harness.files}
				paths={paths}
				changes={harness.changes}
				checks={sessionChecks(harness.worktrees)}
				scheme={scheme}
				review={
					<ReviewPanel
						changes={harness.changes}
						focusPath={focusPath}
						scheme={scheme}
						comments={draft.comments}
						onComment={(comment) => {
							draft.comment(comment);
							emit({ type: 'comment', sessionId: session.id, ...comment });
						}}
						scopes={view.runOrder
							.filter((id) => harness.changes.some((change) => change.runIds.includes(id)))
							.map((id) => ({ id, name: view.runs[id]?.name ?? id }))}
						worktrees={harness.worktrees}
						names={runNames}
						onWorktreeAction={(action) => emit({ ...action, sessionId: session.id })}
					/>
				}
				agents={<AgentsPanel harness={harness} viewRunId={viewRunId} onOpenRun={showRun} />}
				tasks={<TasksPanel tasks={view.tasks} view={view} />}
				counts={{ agents: others.length, tasks: view.tasks.length }}
				onOpenFilePicker={handle.openFilePicker}
				onAttach={draft.attach}
				renderBrowserPage={renderBrowserPage}
			/>
		</section>
	);

	const terminalColumn = (
		<section aria-label="Terminal dock" className={columnClass}>
			<TerminalPanel
				lines={harness.terminal}
				agentName={(runId) => (runId === rootId ? undefined : view.runs[runId]?.name)}
				path={project.path}
				branch={branch}
				onClose={() => setTerminalOpen(false)}
				onClear={harness.clearTerminal}
				onCommand={(command) => {
					emit({ type: 'terminal-command', sessionId: session.id, command });
					// A host answers the command with terminal events; a scripted session answers from its own files.
					if (isHosted(session)) return;
					if (command === 'clear') return harness.clearTerminal();
					harness.appendTerminal([{ kind: 'command', text: command }, ...demoShell(command, { files: harness.files, changes: harness.changes, path: project.path, branch })]);
				}}
			/>
		</section>
	);

	return (
		<div ref={root} hidden={!active} className={cn('h-full min-h-0', frame.outer)}>
			<div className={cn('h-full min-h-0', frame.surface)}>
				<SessionLayout
					narrow={narrow}
					height={size.height}
					chat={chatColumn}
					panel={panelColumn}
					terminal={terminalColumn}
					panelOpen={panel.open}
					terminalOpen={terminalOpen}
				/>
			</div>
			<FilePickerDialog open={filePicker} onOpenChange={setFilePicker} paths={paths} onPick={(path) => panel.openFile(path, false)} />
		</div>
	);
});

/**
 * Keyboard shortcuts. Picked to avoid the ones browsers keep for themselves (⌘T, ⌘W, ⌘N, ⌃Tab), so they work the
 * same in a browser tab as in a desktop shell.
 */
export const SHORTCUTS = {
	commandMenu: { key: 'k', mod: true, label: '⌘K' },
	newSession: { key: 'n', mod: true, alt: true, label: '⌥⌘N' },
	closeSession: { key: 'w', mod: true, alt: true, label: '⌥⌘W' },
	openFile: { key: 'p', mod: true, label: '⌘P' },
	browser: { key: 'b', mod: true, shift: true, label: '⇧⌘B' },
	togglePanel: { key: '\\', mod: true, label: '⌘\\' },
	toggleTree: { key: '\\', mod: true, shift: true, label: '⇧⌘\\' },
	toggleTerminal: { key: '`', ctrl: true, label: '⌃`' }
} as const;

export type ShortcutId = keyof typeof SHORTCUTS;

type Shortcut = { key: string; mod?: boolean; alt?: boolean; shift?: boolean; ctrl?: boolean };

/** True when `event` is `shortcut`. `mod` is ⌘ on Apple platforms and Ctrl elsewhere. */
export function matches(event: KeyboardEvent, shortcut: Shortcut) {
	const apple = /Mac|iPhone|iPad/.test(navigator.platform || navigator.userAgent);
	const mod = apple ? event.metaKey : event.ctrlKey;
	// ⌥ and ⇧ change `key` on some layouts, so letters are matched on the physical key.
	const key = /^[a-z]$/.test(shortcut.key) ? event.code === `Key${shortcut.key.toUpperCase()}` : event.key === shortcut.key || (shortcut.key === '\\' && event.code === 'Backslash') || (shortcut.key === '`' && event.code === 'Backquote');
	// A ⌃ shortcut is Ctrl everywhere; off Apple that is also `mod`, so the mod check would reject it.
	const modMatches = shortcut.ctrl && !apple ? true : Boolean(shortcut.mod) === mod;
	return (
		key &&
		modMatches &&
		Boolean(shortcut.alt) === event.altKey &&
		Boolean(shortcut.shift) === event.shiftKey &&
		(shortcut.ctrl ? event.ctrlKey : true)
	);
}

/** "New session (⌥⌘N)": the tooltip text for a control with a shortcut. */
export function withShortcut(label: string, id: ShortcutId) {
	return `${label} (${SHORTCUTS[id].label})`;
}

import { cn } from '@/lib/utils';
import { focusRingClass } from '@/components/ui/workspace-kit/primitives';
import type { CodingAgentLayout } from '@/components/ui/coding-agent/types';

/**
 * Where a session's surface sits. In the tabs layout it's one rounded card under the strip, inset 6px plus a 1px
 * edge inside a frame drawn with `--radius-xl`, so its corners are that radius less 7px and stay concentric. In the
 * sidebar layout it sits flush beside the sidebar, the way the other workspace templates lay out their content.
 * Inside, chat, panel and terminal are columns of the one surface, joined by hairlines rather than gaps.
 */
export function frameClasses(layout: CodingAgentLayout) {
	return layout === 'tabs'
		? {
				outer: 'p-1.5 pt-0',
				// The edge is drawn as a ring in the border colour, with a short shadow lifting it off the canvas.
				surface: 'overflow-hidden rounded-[calc(var(--radius-xl)-7px)] bg-background shadow-[0_0_0_1px_var(--border),0_1px_3px_-1px_rgb(0_0_0/0.06)]'
			}
		: { outer: '', surface: 'overflow-hidden bg-background' };
}

/**
 * The hairline between two columns, which is also how you resize them. It stays a 1px line; on hover or drag it
 * darkens a step and shows a short grip in its middle, and the grab area is 9px wide. Hover is instant.
 */
export const splitHandleClass = cn(
	// Above both neighbours, so the whole grab area works from either side of the line.
	'z-10 w-px bg-border hover:bg-foreground/20 data-[resize-handle-state=drag]:bg-foreground/25 focus-visible:bg-ring focus-visible:ring-0',
	'data-[panel-group-direction=vertical]:h-px data-[panel-group-direction=vertical]:w-full',
	'after:w-[9px] data-[panel-group-direction=vertical]:after:h-[9px]',
	"before:pointer-events-none before:absolute before:top-1/2 before:left-1/2 before:z-10 before:h-6 before:w-[3px] before:-translate-x-1/2 before:-translate-y-1/2 before:rounded-full before:bg-muted-foreground/45 before:opacity-0 before:content-['']",
	'data-[panel-group-direction=vertical]:before:h-[3px] data-[panel-group-direction=vertical]:before:w-6',
	'hover:before:opacity-100 data-[resize-handle-state=drag]:before:opacity-100 focus-visible:before:opacity-100'
);

/** Toolbar buttons sit 4px apart, so their hit areas grow up and down but only 2px sideways and never overlap. */
export const toolbarButtonClass = 'before:-inset-x-0.5';

/**
 * A tab's close button: hidden until the tab is hovered, focused or active, and only clickable then, so a stray
 * click on a resting tab opens it instead of closing it. The hit area grows to 32px.
 */
export const tabCloseClass = cn(
	"absolute end-1 top-1/2 z-[1] grid size-5 -translate-y-1/2 place-items-center rounded-[4px] text-muted-foreground before:absolute before:-inset-1.5 before:content-['']",
	'pointer-events-none opacity-0 hover:bg-overlay-hover hover:text-foreground',
	'group-hover/tab:pointer-events-auto group-hover/tab:opacity-100 group-focus-within/tab:pointer-events-auto group-focus-within/tab:opacity-100 group-data-[active]/tab:pointer-events-auto group-data-[active]/tab:opacity-100',
	// With no hover to reveal it, a touch screen shows it on every tab.
	'pointer-coarse:pointer-events-auto pointer-coarse:opacity-100',
	focusRingClass
);

