/** What the session can ask of the panel on screen. */
export type SidePanelHandle = {
	/** Shows or hides the file tree, as a column beside a wide panel or over a narrow one. */
	toggleTree: () => void;
};

const basename = (path: string) => path.split('/').pop() ?? path;

/** Below this panel width the tree no longer fits beside the content. */
const TREE_COLUMN_MIN_WIDTH = 576;

function FileView({
	path,
	contents,
	change,
	scheme,
	onAttach
}: {
	path: string;
	contents: string;
	change?: FileChange;
	scheme: ColorScheme;
	onAttach: (file: FileReference) => void;
}) {
	const [range, setRange] = React.useState<{ start: number; end: number } | null>(null);
	const lines = range ? (range.start === range.end ? `${range.start}` : `${Math.min(range.start, range.end)}–${Math.max(range.start, range.end)}`) : null;
	// The renderer compares its options by identity and repaints the whole file when they change, so they stay stable
	// across the session's frequent re-renders.
	const file = React.useMemo(() => ({ name: path, contents }), [path, contents]);
	const options = React.useMemo(
		() => ({
			theme: CODE_THEMES,
			themeType: scheme,
			disableFileHeader: true,
			overflow: 'scroll' as const,
			enableLineSelection: true,
			onLineSelected: (selection: { start: number; end: number } | null) => setRange(selection ? { start: selection.start, end: selection.end } : null)
		}),
		[scheme]
	);
	const style = React.useMemo(() => ({ ...DIFF_SURFACE_STYLE, colorScheme: scheme }), [scheme]);

	return (
		<div className="flex h-full min-h-0 flex-col">
			<div className="flex h-10 shrink-0 items-center gap-2 ps-3 pe-2">
				{/* The folders give way first, so the file name and its status always show. */}
				<p dir="ltr" title={path} className="flex min-w-0 flex-1 items-center font-mono text-xs text-muted-foreground">
					{path.includes('/') ? <span className="min-w-0 shrink truncate">{path.slice(0, -basename(path).length).replaceAll('/', ' / ')}</span> : null}
					<MiddleTruncate text={basename(path)} title={false} className="max-w-[70%] shrink-0 text-foreground" />
					{change ? (
						<span title={change.before === null ? 'Added' : 'Modified'} className={cn('ms-2 shrink-0', change.before === null ? 'text-success' : 'text-warning')}>
							<span aria-hidden="true">{change.before === null ? 'A' : 'M'}</span>
							<span className="sr-only">{change.before === null ? 'Added' : 'Modified'}</span>
						</span>
					) : null}
				</p>
				<Button size="xs" variant="ghost" className="text-muted-foreground" onClick={() => onAttach(lines ? { path, lines } : { path })}>
					{lines ? (
						<>
							Add lines <span className="tabular-nums">{lines}</span> to message
						</>
					) : (
						'Add to message'
					)}
				</Button>
			</div>
			<div dir="ltr" className="min-h-0 flex-1 overflow-auto">
				<CodeFile file={file} options={options} style={style} />
			</div>
		</div>
	);
}

function TabLabel({ tab, changes, counts, checks }: { tab: PanelTab; changes: number; counts: { agents: number; tasks: number }; checks: ChecksOutcome }) {
	if (tab.kind === 'agents' || tab.kind === 'tasks') {
		const Icon = tab.kind === 'agents' ? Users : ListChecks;
		const count = tab.kind === 'agents' ? counts.agents : counts.tasks;
		return (
			<>
				<Icon aria-hidden="true" className="size-3.5 shrink-0 text-muted-foreground" />
				<span>{tab.kind === 'agents' ? 'Agents' : 'Tasks'}</span>
				{count > 0 ? <span className="text-muted-foreground tabular-nums">{count}</span> : null}
			</>
		);
	}
	if (tab.kind === 'review') {
		return (
			<>
				<GitCompareArrows aria-hidden="true" className="size-3.5 shrink-0 text-muted-foreground" />
				<span>Files changed</span>
				{changes > 0 ? <span className="text-muted-foreground tabular-nums">{changes}</span> : null}
				{/* A failing or running check on any of the session's pull requests shows from every tab. */}
				{checks === 'failed' || checks === 'running' ? (
					<span title={checks === 'failed' ? 'A check is failing' : 'Checks are running'} className={cn('size-1.5 shrink-0 rounded-full', checks === 'failed' ? 'bg-destructive' : 'bg-warning')}>
						<span className="sr-only">{checks === 'failed' ? ', a check is failing' : ', checks are running'}</span>
					</span>
				) : null}
			</>
		);
	}
	if (tab.kind === 'file') {
		// A preview tab is replaced by the next file you glance at; it reads quieter until you pin it.
		return (
			<>
				<FileCode2 aria-hidden="true" className="size-3.5 shrink-0 text-muted-foreground" />
				<MiddleTruncate
					text={basename(tab.path)}
					tail={10}
					title={false}
					className={cn(tab.preview && 'text-muted-foreground italic [font-synthesis-style:auto]')}
				/>
			</>
		);
	}
	return (
		<>
			<Globe aria-hidden="true" className="size-3.5 shrink-0 text-muted-foreground" />
			<span dir="auto" className="truncate">
				{tab.browser.url ? (tab.browser.title ?? pageTitle(tab.browser.url)) : 'New tab'}
			</span>
		</>
	);
}

/**
 * The right-hand side of a session: a tab strip of review, file and browser tabs with a menu to open more, the
 * active tab's content, and the checkout's file tree beside it. The tabs and whether the tree shows come from the
 * session's `usePanelTabs`; the Files changed, Agents and Tasks tabs are the session's to fill.
 */
export function SidePanel({
	panel,
	files,
	paths,
	changes,
	checks,
	scheme,
	review,
	agents,
	tasks,
	counts,
	onOpenFilePicker,
	onAttach,
	renderBrowserPage,
	handle
}: {
	panel: PanelTabs;
	files: Record<string, string>;
	/** The checkout's paths, sorted, for the tree. */
	paths: string[];
	changes: FileChange[];
	/** How the checks on the session's pull requests stand, shown from every tab. */
	checks: ChecksOutcome;
	scheme: ColorScheme;
	/** The Files changed tab's content. */
	review: React.ReactNode;
	/** The Agents tab's content; the tab shows once the session has started other agents. */
	agents: React.ReactNode;
	/** The Tasks tab's content; the tab shows once the session keeps a shared task list. */
	tasks: React.ReactNode;
	counts: { agents: number; tasks: number };
	onOpenFilePicker: () => void;
	onAttach: (file: FileReference) => void;
	renderBrowserPage?: BrowserPageRenderer;
	handle?: React.Ref<SidePanelHandle>;
}) {
	const { tabs, treeOpen, toggleTree: toggleTreeColumn } = panel;
	const activeTab = tabs.find((tab) => tab.id === panel.active) ?? tabs[0];
	const [root, { width }] = useElementSize<HTMLDivElement>({ ignoreHidden: true });
	const wide = width >= TREE_COLUMN_MIN_WIDTH;
	// Beside a wide panel the tree is a column the session remembers; on a narrow one it opens over the content,
	// closed until asked for, and the shortcut toggles whichever of the two is on screen.
	const [overlayTree, setOverlayTree] = React.useState(false);
	const showTree = wide ? treeOpen : overlayTree;
	const toggleTree = React.useCallback(() => (wide ? toggleTreeColumn() : setOverlayTree((open) => !open)), [toggleTreeColumn, wide]);
	React.useImperativeHandle(handle, () => ({ toggleTree }), [toggleTree]);
	const tree =
		paths.length === 0 ? (
			<p className="px-3 py-4 text-xs text-muted-foreground">No files in this project yet.</p>
		) : (
			<WorkspaceTree
				paths={paths}
				changes={changes}
				selected={activeTab.kind === 'file' ? activeTab.path : null}
				scheme={scheme}
				onOpen={(path) => {
					panel.openFile(path);
					if (!wide) setOverlayTree(false);
				}}
			/>
		);

	return (
		<div ref={root} className="flex h-full min-h-0 flex-col">
			<div className="flex h-12 shrink-0 items-center gap-1 border-b border-border px-2">
				<Tabs value={activeTab.id} onValueChange={(value) => panel.show(String(value))} className="min-w-0 shrink gap-0">
					<TabsList
						aria-label="Panel tabs"
						className="h-8 gap-0.5 bg-transparent p-0.5 [&_[data-slot=tabs-indicator]]:rounded-[4px]"
						onWheel={(event) => {
							if (Math.abs(event.deltaY) > Math.abs(event.deltaX)) event.currentTarget.scrollLeft += event.deltaY;
						}}
					>
						{tabs.map((tab) => {
							const closable = tab.kind === 'file' || tab.kind === 'browser';
							const title = tab.kind === 'file' ? tab.path : tab.kind === 'browser' && tab.browser.url ? displayUrl(tab.browser.url) : undefined;
							return (
								<div key={tab.id} data-active={tab.id === activeTab.id || undefined} className="group/tab relative flex shrink-0">
									<TabsTrigger
										value={tab.id}
										title={title}
										onDoubleClick={() => panel.pin(tab.id)}
										onKeyDown={(event) => {
											if (closable && (event.key === 'Delete' || event.key === 'Backspace')) {
												event.preventDefault();
												panel.close(tab.id);
											}
										}}
										onMouseDown={(event) => {
											if (event.button === 1) event.preventDefault();
										}}
										onAuxClick={(event) => {
											if (event.button === 1 && closable) panel.close(tab.id);
										}}
										className={cn(
											'h-7 min-h-7 max-w-48 justify-start gap-1.5 rounded-[4px] px-2 text-[0.8125rem] font-normal text-muted-foreground hover:text-foreground data-[active]:text-foreground pointer-coarse:min-h-9',
											closable && 'pe-7'
										)}
									>
										<TabLabel tab={tab} changes={changes.length} counts={counts} checks={checks} />
									</TabsTrigger>
									{closable ? (
										<button type="button" tabIndex={-1} aria-label="Close tab" onClick={() => panel.close(tab.id)} className={tabCloseClass}>
											<X aria-hidden="true" className="size-3.5" />
										</button>
									) : null}
								</div>
							);
						})}
					</TabsList>
				</Tabs>
				<DropdownMenu>
					<DropdownMenuTrigger
						aria-label="Open in panel"
						title="Open in panel"
						className={cn(iconButtonClass({ menu: true }), 'rounded-[4px]', toolbarButtonClass)}
					>
						<Plus aria-hidden="true" className="size-3.5" />
					</DropdownMenuTrigger>
					<DropdownMenuContent align="start" className="w-52">
						<DropdownMenuItem onClick={onOpenFilePicker}>
							<FileCode2 aria-hidden="true" />
							Open file
							<DropdownMenuShortcut>{SHORTCUTS.openFile.label}</DropdownMenuShortcut>
						</DropdownMenuItem>
						<DropdownMenuItem onClick={() => panel.openBrowser()}>
							<Globe aria-hidden="true" />
							Browser
							<DropdownMenuShortcut>{SHORTCUTS.browser.label}</DropdownMenuShortcut>
						</DropdownMenuItem>
					</DropdownMenuContent>
				</DropdownMenu>
				<div className="flex-1" />
				<TooltipIconButton
					label={withShortcut(showTree ? 'Hide files' : 'Show files', 'toggleTree')}
					aria-pressed={showTree}
					onClick={toggleTree}
					className={cn(toolbarButtonClass, showTree && 'text-foreground')}
				>
					<FolderTree aria-hidden="true" className="size-3.5" />
				</TooltipIconButton>
				<TooltipIconButton label={withShortcut('Hide side panel', 'togglePanel')} onClick={() => panel.setOpen(false)} className={toolbarButtonClass}>
					<PanelRightClose aria-hidden="true" className="size-3.5 rtl:-scale-x-100" />
				</TooltipIconButton>
			</div>
			<div className="relative flex min-h-0 flex-1">
				<div className="min-w-0 flex-1">
					{tabs.map((tab) => (
						// Tabs stay mounted while hidden, so a diff keeps its layout and a page its history.
						<div key={tab.id} hidden={tab.id !== activeTab.id} className="h-full">
							{tab.kind === 'review' ? (
								review
							) : tab.kind === 'agents' ? (
								agents
							) : tab.kind === 'tasks' ? (
								tasks
							) : tab.kind === 'file' ? (
								<FileView
									path={tab.path}
									contents={files[tab.path] ?? ''}
									change={changes.find((change) => change.path === tab.path)}
									scheme={scheme}
									onAttach={onAttach}
								/>
							) : (
								<BrowserPanel tab={tab.browser} onChange={(browser) => panel.changeBrowser(tab.id, browser)} renderPage={renderBrowserPage} />
							)}
						</div>
					))}
				</div>
				{showTree ? (
					<div
						dir="ltr"
						className={cn(
							// Its own pane: a rule at the join and a step of tone, like the sidebar in the other templates.
							'shrink-0 border-s border-border py-1',
							wide ? 'w-[clamp(14rem,32%,20rem)]' : 'absolute inset-y-0 end-0 z-10 w-[min(18rem,85%)] shadow-lg'
						)}
						style={{ background: TREE_COLUMN_BG }}
					>
						{tree}
					</div>
				) : null}
			</div>
		</div>
	);
}

'use client';

import { Eraser, GitBranch, SquareTerminal, X } from 'lucide-react';
import * as React from 'react';

import { cn } from '@/lib/utils';
import { MiddleTruncate } from '@/components/ui/workspace-kit/middle-truncate';
import { TooltipIconButton } from '@/components/ui/workspace-kit/primitives';
import { toolbarButtonClass } from '@/components/ui/coding-agent/session-surface';
import type { TerminalLine } from '@/components/ui/coding-agent/harness';

/**
 * The session's terminal dock: everything the agent ran, in order, then a prompt of your own. Where the shell is
 * (folder and branch) sits in the dock header, so the prompt line keeps its full width for what you type. What
 * a command prints is up to `onCommand`.
 */
export function TerminalPanel({
	lines,
	path,
	branch,
	onCommand,
	onClear,
	onClose,
	agentName
}: {
	lines: TerminalLine[];
	/** Another agent's name for lines it ran, so a shared terminal says who ran what. */
	agentName?: (runId: string) => string | undefined;
	path: string;
	branch: string;
	onCommand: (command: string) => void;
	onClear: () => void;
	onClose: () => void;
}) {
	const [value, setValue] = React.useState('');
	// Your own commands, kept apart from the log so `clear` doesn't forget them, and the line you were typing.
	const [history, setHistory] = React.useState<string[]>([]);
	const [recall, setRecall] = React.useState<{ index: number; draft: string } | null>(null);
	const scroller = React.useRef<HTMLDivElement>(null);
	const input = React.useRef<HTMLInputElement>(null);
	const pinned = React.useRef(true);

	const pin = React.useCallback(() => {
		const node = scroller.current;
		if (node && pinned.current) node.scrollTop = node.scrollHeight;
	}, []);
	React.useLayoutEffect(pin, [lines.length, pin]);
	// Resizing the dock keeps the prompt in view while you were at the bottom.
	React.useEffect(() => {
		const node = scroller.current;
		if (!node) return;
		const observer = new ResizeObserver(pin);
		observer.observe(node);
		return () => observer.disconnect();
	}, [pin]);

	const step = (by: -1 | 1) => {
		if (history.length === 0) return;
		if (by === -1) {
			const index = recall ? Math.max(recall.index - 1, 0) : history.length - 1;
			setRecall({ index, draft: recall?.draft ?? value });
			setValue(history[index]);
		} else if (recall) {
			const index = recall.index + 1;
			if (index >= history.length) {
				setValue(recall.draft);
				setRecall(null);
			} else {
				setRecall({ ...recall, index });
				setValue(history[index]);
			}
		}
	};

	return (
		<section aria-label="Terminal" className="flex h-full min-h-0 flex-col">
			<div className="flex h-10 shrink-0 items-center gap-2 ps-3 pe-1.5">
				<SquareTerminal aria-hidden="true" className="size-3.5 shrink-0 text-muted-foreground" />
				<span className="shrink-0 text-[0.8125rem] text-foreground">Terminal</span>
				<span dir="ltr" className="flex min-w-0 flex-1 items-center gap-2 font-mono text-xs text-muted-foreground">
					<MiddleTruncate text={path} tail={18} className="max-w-[60%]" />
					<span title={branch} className="flex min-w-0 items-center gap-1">
						<GitBranch aria-hidden="true" className="size-3.5 shrink-0" />
						<span className="min-w-0 truncate">{branch}</span>
					</span>
				</span>
				<TooltipIconButton label="Clear" onClick={onClear} className={toolbarButtonClass}>
					<Eraser aria-hidden="true" className="size-3.5" />
				</TooltipIconButton>
				<TooltipIconButton label="Close terminal" onClick={onClose} className={toolbarButtonClass}>
					<X aria-hidden="true" className="size-3.5" />
				</TooltipIconButton>
			</div>
			{/* Shell text is always left to right, whatever the page direction. Clicking the log puts the cursor back in the prompt. */}
			<div
				ref={scroller}
				dir="ltr"
				role="log"
				aria-live="polite"
				onScroll={(event) => {
					const node = event.currentTarget;
					pinned.current = node.scrollHeight - node.scrollTop - node.clientHeight < 24;
				}}
				onMouseUp={() => {
					if (!window.getSelection()?.toString()) input.current?.focus();
				}}
				className="min-h-0 flex-1 overflow-y-auto px-3 py-2 text-start font-mono text-xs leading-5"
			>
				{lines.map((line) => (
					<div
						key={line.id}
						className={cn(
							'min-h-5 whitespace-pre-wrap [overflow-wrap:anywhere]',
							line.kind === 'command' ? 'text-foreground' : line.kind === 'error' ? 'text-destructive' : 'text-muted-foreground'
						)}
					>
						{line.kind === 'command' ? (
							<span aria-hidden="true" className="text-success select-none">
								{agentName?.(line.runId) ? <span className="me-1.5 rounded-sm bg-muted px-1 text-muted-foreground">{agentName(line.runId)}</span> : null}❯{' '}
							</span>
						) : null}
						{line.text}
					</div>
				))}
				<form
					className="flex items-baseline"
					onSubmit={(event) => {
						event.preventDefault();
						const command = value.trim();
						if (!command) return;
						onCommand(command);
						setHistory((current) => [...current, command]);
						setValue('');
						setRecall(null);
						pinned.current = true;
					}}
				>
					<span aria-hidden="true" className="shrink-0 text-success select-none">
						❯{' '}
					</span>
					<input
						ref={input}
						aria-label="Terminal input"
						autoComplete="off"
						spellCheck={false}
						value={value}
						onChange={(event) => {
							setValue(event.target.value);
							setRecall(null);
						}}
						onKeyDown={(event) => {
							if (event.key !== 'ArrowUp' && event.key !== 'ArrowDown') return;
							event.preventDefault();
							step(event.key === 'ArrowUp' ? -1 : 1);
						}}
						className="min-w-0 flex-1 bg-transparent text-foreground caret-foreground outline-none"
					/>
				</form>
			</div>
		</section>
	);
}

import type * as React from 'react';

import type { AgentRun, FlowBeat, HarnessEvent, PermissionDecision, RunRole, RunSignal, SessionStatus, Worktree } from '@/components/ui/coding-agent/harness';
import type { HarnessStore } from '@/components/ui/coding-agent/harness-store';

import type { AskAnswer, AskQuestion } from '@/components/ui/ai/ask-card';
import type { AiModel, ModelSelection } from '@/components/ui/ai/model-selector';

/** `tabs` puts sessions in a strip across the top; `sidebar` lists them by project down the left. */
export type CodingAgentLayout = 'tabs' | 'sidebar';

/** Where a session's agent works: the project checkout itself, or its own git worktree. */
export type WorkspaceLocation = 'local' | 'worktree';

export type CodingProject = {
	id: string;
	name: string;
	/** Shown in the terminal prompt and the project menu, e.g. `~/code/acme-web`. */
	path: string;
	branch: string;
	/** The checkout as the agent first sees it, keyed by path. Edits are layered on top per session. */
	files: Record<string, string>;
};

export type { SessionStatus, ToolCallBeat } from '@/components/ui/coding-agent/harness';

/** Events a script plays as they are, from the run playing it: messages between agents and the state of their branches. */
type CoordinationBeat = HarnessEvent extends infer E
	? E extends { kind: 'message' | 'handoff' | 'route' | 'phase' | 'task' | 'worktree' | 'pr' | 'check' }
		? Omit<E, 'id' | 'runId'>
		: never
	: never;

/**
 * One scripted step of a session. Each waits `delay` ms (or a sensible default for its kind) before it lands, and
 * `permission` and `question` hold the run until they are answered.
 */
export type SessionBeat = { delay?: number } & (
	| FlowBeat
	| { kind: 'permission'; title: string; command: string }
	| { kind: 'question'; questions: AskQuestion[] }
	// Multi-agent beats. A spawn starts a child run with its own script, which plays alongside the parent.
	| { kind: 'spawn'; agent: SpawnedAgent; script: SessionBeat[]; played?: number }
	/** Waits for the named children (all of this run's children by default), then lands a row of their results. */
	| { kind: 'await'; agents?: string[] }
	| CoordinationBeat
);

/**
 * A child agent a script spawns: the run it starts, as a worker unless it says otherwise. `id` is how other beats
 * address it (`to`, `await`).
 */
export type SpawnedAgent = Pick<AgentRun, 'id' | 'name' | 'kind' | 'phase' | 'background' | 'workspace' | 'capabilities'> & { role?: RunRole; task: string };

export type SessionBeatKind = SessionBeat['kind'];

export type CodingSession = {
	id: string;
	title: string;
	projectId: string;
	location?: WorkspaceLocation;
	/** Branch the session works on; defaults to the project's. */
	branch?: string;
	model?: ModelSelection;
	/** Name of the session's own agent, shown when other agents are in play. Defaults to "Agent". */
	agentName?: string;
	/** A scripted run for demos and fixtures. A real harness passes `events` or `store` instead. */
	script?: SessionBeat[];
	/** How many beats already happened before the session opened; they land at once instead of playing. */
	played?: number;
	/** A host-controlled event log; the session shows exactly what it describes. */
	events?: HarnessEvent[];
	/** A store the host pushes events into as they happen. */
	store?: HarnessStore;
	/**
	 * Worktrees known when the session opens, with their pull requests. The first is the session's own checkout;
	 * without one it is the session's branch. Agents' own worktrees join as they spawn.
	 */
	worktrees?: Worktree[];
	/** Short relative time for lists, e.g. "2m". */
	updatedLabel?: string;
};

/** A run as the shell lists it under its session in the sidebar. */
export type RunSummary = { id: string; name: string; parentRunId?: string; depth: number; status: RunSignal };

export type SessionPatch = {
	title?: string;
	status?: SessionStatus;
	unread?: boolean;
	/** Share of the script played, 0 to 1. */
	progress?: number;
	changedFiles?: number;
	/** The session's other agents, for the sidebar's indented rows. */
	runs?: RunSummary[];
};

export type SlashCommand = {
	name: string;
	description: string;
};

export type CodingAgentData = {
	/** Product name for the new-session screen and the sidebar header. */
	brand: string;
	projects: CodingProject[];
	sessions: CodingSession[];
	/** Sessions open (as tabs, or kept live in the sidebar layout) on first render, in order. */
	openSessionIds: string[];
	models: AiModel[];
	defaultModel: ModelSelection;
	commands: SlashCommand[];
	/** Context window used by the header's context ring. */
	contextWindow: number;
	/** Share of the plan's usage spent, 0 to 100. Shows a notice above the composer from 80. */
	usagePercent?: number;
	/** Beats played after a message is sent once a session's script has finished. */
	followUp: (text: string) => SessionBeat[];
	/** Beats for a brand new session started from the new-session screen. */
	newSessionScript: (text: string) => SessionBeat[];
};

/** Everything the template asks its host to do. The demo plays the result itself; a host wires real effects. */
export type CodingAgentAction =
	| { type: 'new-session'; sessionId: string; projectId: string; location: WorkspaceLocation }
	| { type: 'close-session'; sessionId: string }
	| { type: 'rename-session'; sessionId: string; title: string }
	| { type: 'delete-session'; sessionId: string }
