import { acceptInvite, createInvite, InviteError, revokeInvite } from '../src/lib/invitations';
import { pendingInvites, resetDb, seedTeam } from './helpers/db';

const ADMIN = 'u_admin';
let teamId: string;

beforeEach(async () => {
  await resetDb();
  teamId = await seedTeam({ owner: ADMIN });
