'use client';

import type * as React from 'react';

import { ResizableHandle, ResizablePanel, ResizablePanelGroup } from '@/components/ui/resizable';
import { splitHandleClass } from '@/components/ui/coding-agent/session-surface';

/** Chat, panel and terminal are columns of one surface; each fills its slot and the hairlines between them do the rest. */
export const columnClass = 'flex h-full min-h-0 flex-col bg-background';

/** The chat keeps at least this much height, so dragging the terminal up never pushes the composer out of view. */
const CHAT_MIN_HEIGHT = 360;

/**
 * Where a session's chat, side panel and terminal sit. Wide, they're resizable columns with the terminal docked
 * along the bottom; narrow, the panel takes the chat's place while it's open and the terminal keeps its own slot.
 */
export function SessionLayout({
	narrow,
	height,
	chat,
	panel,
	terminal,
	panelOpen,
	terminalOpen
}: {
	narrow: boolean;
	/** The session's height, which caps how tall the terminal may get. */
	height: number;
	chat: React.ReactNode;
	panel: React.ReactNode;
	terminal: React.ReactNode;
	panelOpen: boolean;
	terminalOpen: boolean;
}) {
	if (narrow) {
		return (
			<div className="flex h-full min-h-0 flex-col">
				<div className="relative min-h-0 flex-1">
					{chat}
					{panelOpen ? <div className="absolute inset-0 z-10">{panel}</div> : null}
				</div>
				{terminalOpen ? <div className="h-[min(14rem,30%)] shrink-0 border-t border-border">{terminal}</div> : null}
			</div>
		);
	}

	const terminalMax = Number.isFinite(height) ? Math.max(15, Math.min(70, 100 - (CHAT_MIN_HEIGHT / height) * 100)) : 70;
	return (
		<ResizablePanelGroup direction="vertical" autoSaveId={undefined}>
			<ResizablePanel id="main" order={1} minSize={30} defaultSize={terminalOpen ? 70 : 100}>
				<ResizablePanelGroup direction="horizontal">
					<ResizablePanel id="chat" order={1} minSize={30} defaultSize={panelOpen ? 50 : 100}>
						{chat}
					</ResizablePanel>
					{panelOpen ? (
						<>
							<ResizableHandle className={splitHandleClass} />
							<ResizablePanel id="panel" order={2} minSize={28} defaultSize={50}>
								{panel}
							</ResizablePanel>
						</>
					) : null}
				</ResizablePanelGroup>
			</ResizablePanel>
			{terminalOpen ? (
				<>
					<ResizableHandle className={splitHandleClass} />
					<ResizablePanel id="terminal" order={2} minSize={15} maxSize={terminalMax} defaultSize={Math.min(30, terminalMax)}>
						{terminal}
					</ResizablePanel>
				</>
			) : null}
		</ResizablePanelGroup>
	);
}

/**
 * Closes one tab of a strip: the ids left, and the one that takes its place if it was in front, which is the tab
 * after it, or the one before when it was last. The neighbour is null when nothing is left or the id wasn't there.
 */
export function withoutAndNeighbor(list: readonly string[], id: string): { list: string[]; neighbor: string | null } {
	const index = list.indexOf(id);
	const rest = list.filter((entry) => entry !== id);
	return { list: rest, neighbor: index < 0 ? null : (rest[index] ?? rest[index - 1] ?? null) };
}

'use client';

import * as React from 'react';

import type { LineComment } from '@/components/ui/coding-agent/review-panel';
import type { ComposerAttachment } from '@/components/ui/coding-agent/session-composer';

/** A file, or a range of its lines ("12" or "12–18"), to send along with the next message. */
export type FileReference = { path: string; lines?: string };

/** Something waiting to go out with the next message: a file reference, or a comment on a line of the diff. */
type DraftItem = ({ kind: 'file' } & FileReference) | { kind: 'comment'; comment: LineComment };

type DraftState = {
	pending: DraftItem[];
	/** Comments that went out stay on the diff, marked as sent. */
	sent: LineComment[];
	/** Comments added so far, which numbers the next one. */
	comments: number;
};

type DraftAction =
	| { type: 'attach'; file: FileReference }
	| { type: 'comment'; comment: Omit<LineComment, 'id' | 'sent'> }
	| { type: 'remove'; id: string }
	| { type: 'sent' };

const basename = (path: string) => path.split('/').pop() ?? path;

/** An item's chip id. It is only ever compared, so a path can hold any character without breaking it apart. */
function itemId(item: DraftItem) {
	return item.kind === 'comment' ? `comment:${item.comment.id}` : `file:${JSON.stringify([item.path, item.lines ?? ''])}`;
}

/** The composer chip: a file leads with its name, which tells files apart, and keeps its folder as the second line. */
function chipOf(item: DraftItem): ComposerAttachment {
	if (item.kind === 'comment') {
		return { id: itemId(item), kind: 'comment', label: `${basename(item.comment.path)}:${item.comment.line}`, detail: item.comment.text };
	}
	const name = basename(item.path);
	const folder = item.path.slice(0, -name.length - 1);
	return { id: itemId(item), kind: 'file', label: item.lines ? `${name}:${item.lines}` : name, detail: folder || undefined };
}

/** What the host receives: a file as its full reference, a comment as the line it's on and what was said. */
function serialize(item: DraftItem) {
	if (item.kind === 'comment') return `${basename(item.comment.path)}:${item.comment.line}: ${item.comment.text}`;
	return item.lines ? `${item.path}:${item.lines}` : item.path;
}

function draftReducer(state: DraftState, action: DraftAction): DraftState {
	switch (action.type) {
		case 'attach': {
			const item: DraftItem = { kind: 'file', ...action.file };
			return state.pending.some((entry) => itemId(entry) === itemId(item)) ? state : { ...state, pending: [...state.pending, item] };
		}
		case 'comment': {
			const comments = state.comments + 1;
			return { ...state, comments, pending: [...state.pending, { kind: 'comment', comment: { ...action.comment, id: `comment-${comments}` } }] };
		}
		case 'remove':
			// Removing a comment's chip takes the comment off the diff too; one already sent has no chip to remove.
			return { ...state, pending: state.pending.filter((item) => itemId(item) !== action.id) };
		case 'sent':
			return {
				...state,
				pending: [],
				sent: [...state.sent, ...state.pending.flatMap((item) => (item.kind === 'comment' ? [{ ...item.comment, sent: true }] : []))]
			};
	}
}

const EMPTY: DraftState = { pending: [], sent: [], comments: 0 };

/**
 * What rides along with the next message: files and line ranges you attached and comments you left on the diff.
 * The diff's comments and the composer's chips are both views of it, so removing a chip takes its comment off the
 * diff, and sending marks the comments sent.
 */
export function useDraftContext() {
	const [state, dispatch] = React.useReducer(draftReducer, EMPTY);
	const comments = React.useMemo(
		() => [...state.sent, ...state.pending.flatMap((item) => (item.kind === 'comment' ? [item.comment] : []))],
		[state.sent, state.pending]
	);
	const attachments = React.useMemo(() => state.pending.map(chipOf), [state.pending]);
	return {
		comments,
		attachments,
		attach: (file: FileReference) => dispatch({ type: 'attach', file }),
		comment: (comment: Omit<LineComment, 'id' | 'sent'>) => dispatch({ type: 'comment', comment }),
		remove: (id: string) => dispatch({ type: 'remove', id }),
		/** Everything pending, as the host receives it; the comments stay on the diff, marked as sent. */
		take: () => {
			dispatch({ type: 'sent' });
			return state.pending.map(serialize);
		}
	};
}

'use client';

import * as React from 'react';

import { useLatest } from '@/components/ui/workspace-kit/use-latest';
import { browserTab, type BrowserTabState, navigate } from '@/components/ui/coding-agent/browser-panel';
import { withoutAndNeighbor } from '@/components/ui/coding-agent/tab-strip';

/** A tab of the side panel. Review, Agents and Tasks are fixed; files and pages open and close. */
export type PanelTab =
	| { id: 'review'; kind: 'review' }
	| { id: 'agents'; kind: 'agents' }
	| { id: 'tasks'; kind: 'tasks' }
	| { id: string; kind: 'file'; path: string; preview: boolean }
	| { id: string; kind: 'browser'; browser: BrowserTabState };

type ClosableTab = Extract<PanelTab, { kind: 'file' | 'browser' }>;

type PanelState = {
	/** The file and browser tabs, which follow the fixed ones. */
	tabs: ClosableTab[];
	active: string;
	open: boolean;
	/** Whether the panel was open when the session got too narrow for it, so it comes back that way. */
	openBeforeNarrow: boolean | null;
	/** Whether the file tree shows as a column beside a wide panel. */
	tree: boolean;
	/** Browser tabs opened so far, which numbers the next one. */
	browsers: number;
};

type PanelAction =
	| { type: 'open-file'; path: string; preview: boolean }
	| { type: 'open-browser'; url: string | null; title?: string }
	| { type: 'browser-change'; id: string; browser: BrowserTabState }
	| { type: 'close'; id: string; fixed: readonly string[] }
	| { type: 'pin'; id: string }
	| { type: 'show'; id: string }
	| { type: 'set-open'; open: boolean }
	| { type: 'toggle-open' }
	| { type: 'toggle-tree' }
	| { type: 'narrow'; narrow: boolean };

const REVIEW_TAB: PanelTab = { id: 'review', kind: 'review' };
const AGENTS_TAB: PanelTab = { id: 'agents', kind: 'agents' };
const TASKS_TAB: PanelTab = { id: 'tasks', kind: 'tasks' };

/** A file has one tab at most, so its path is its id. */
const fileTabId = (path: string) => `file:${path}`;

function showing(state: PanelState, tabs: ClosableTab[], active: string): PanelState {
	return { ...state, tabs, active, open: true };
}

function panelReducer(state: PanelState, action: PanelAction): PanelState {
	switch (action.type) {
		case 'open-file': {
			const id = fileTabId(action.path);
			if (state.tabs.some((tab) => tab.id === id)) {
				// Opening a file you only glanced at for keeps pins its tab.
				const tabs = action.preview ? state.tabs : state.tabs.map((tab) => (tab.id === id && tab.kind === 'file' ? { ...tab, preview: false } : tab));
				return showing(state, tabs, id);
			}
			const tab: ClosableTab = { id, kind: 'file', path: action.path, preview: action.preview };
			// A preview tab is reused by the next file you glance at; pinning it (double-click) keeps it.
			const previewIndex = action.preview ? state.tabs.findIndex((entry) => entry.kind === 'file' && entry.preview) : -1;
			return showing(state, previewIndex >= 0 ? state.tabs.map((entry, index) => (index === previewIndex ? tab : entry)) : [...state.tabs, tab], id);
		}
		case 'open-browser': {
			const { url, title } = action;
			// A page the agent opens reuses the browser tab you have; a new browser tab is always a new one.
			const existing = url ? state.tabs.find((tab) => tab.kind === 'browser') : undefined;
			if (url && existing?.kind === 'browser') {
				return showing(state, state.tabs.map((tab) => (tab.id === existing.id ? { ...existing, browser: navigate(existing.browser, url, title) } : tab)), existing.id);
			}
			const browsers = state.browsers + 1;
			const id = `browser-${browsers}`;
			return { ...showing(state, [...state.tabs, { id, kind: 'browser', browser: browserTab(url, title) }], id), browsers };
		}
		case 'browser-change':
			return { ...state, tabs: state.tabs.map((tab) => (tab.id === action.id && tab.kind === 'browser' ? { ...tab, browser: action.browser } : tab)) };
		case 'close': {
			if (!state.tabs.some((tab) => tab.id === action.id)) return state;
			const { neighbor } = withoutAndNeighbor([...action.fixed, ...state.tabs.map((tab) => tab.id)], action.id);
			return {
				...state,
				tabs: state.tabs.filter((tab) => tab.id !== action.id),
				active: state.active === action.id ? (neighbor ?? REVIEW_TAB.id) : state.active
			};
		}
		case 'pin':
			return { ...state, tabs: state.tabs.map((tab) => (tab.id === action.id && tab.kind === 'file' ? { ...tab, preview: false } : tab)) };
		case 'show':
			return { ...state, active: action.id, open: true };
		case 'set-open':
			return state.open === action.open ? state : { ...state, open: action.open };
		case 'toggle-open':
			return { ...state, open: !state.open };
		case 'toggle-tree':
			return { ...state, tree: !state.tree };
		case 'narrow':
			// On a narrow screen the panel would cover the chat, so it closes there, and comes back as it was once
			// there's room again. Repeats are ignored, so a remembered state is never overwritten.
			if (action.narrow) return state.openBeforeNarrow === null ? { ...state, openBeforeNarrow: state.open, open: false } : state;
			return state.openBeforeNarrow === null ? state : { ...state, open: state.openBeforeNarrow, openBeforeNarrow: null };
	}
}

function initialPanel(open: boolean): PanelState {
	return { tabs: [], active: REVIEW_TAB.id, open, openBeforeNarrow: null, tree: true, browsers: 0 };
}

/**
 * The side panel's tabs and whether it's open. Review always leads, then Agents once the session has started other
 * agents and Tasks once it keeps a shared list; the files and pages you open follow, each closable.
 */
export function usePanelTabs({
	defaultOpen,
	narrow,
	agents,
	tasks,
	onOpenFile,
	onOpenUrl
}: {
	defaultOpen: boolean;
	/** The session is too narrow for the panel to sit beside the chat. */
	narrow: boolean;
	agents: boolean;
	tasks: boolean;
	/** A file opened in a tab, for the host. */
	onOpenFile?: (path: string) => void;
	/** A browser tab went to a page, for the host. */
	onOpenUrl?: (url: string) => void;
}) {
	const [state, dispatch] = React.useReducer(panelReducer, defaultOpen, initialPanel);
	React.useEffect(() => dispatch({ type: 'narrow', narrow }), [narrow]);
	const fixed = React.useMemo(() => [REVIEW_TAB, ...(agents ? [AGENTS_TAB] : []), ...(tasks ? [TASKS_TAB] : [])], [agents, tasks]);
	const tabs = React.useMemo<PanelTab[]>(() => [...fixed, ...state.tabs], [fixed, state.tabs]);
	// The actions never change, so a session's handle and memoized children built on them don't either.
	const latest = useLatest({ fixed, onOpenFile, onOpenUrl });
	const actions = React.useMemo(
		() => ({
			openFile: (path: string, preview = true) => {
				dispatch({ type: 'open-file', path, preview });
				latest.current.onOpenFile?.(path);
			},
			openBrowser: (url: string | null = null, title?: string) => dispatch({ type: 'open-browser', url, title }),
			changeBrowser: (id: string, browser: BrowserTabState) => {
				dispatch({ type: 'browser-change', id, browser });
				if (browser.url) latest.current.onOpenUrl?.(browser.url);
			},
			close: (id: string) => dispatch({ type: 'close', id, fixed: latest.current.fixed.map((tab) => tab.id) }),
			pin: (id: string) => dispatch({ type: 'pin', id }),
			/** Brings a tab to the front, opening the panel if it's closed. */
			show: (id: string) => dispatch({ type: 'show', id }),
			setOpen: (open: boolean) => dispatch({ type: 'set-open', open }),
			toggleOpen: () => dispatch({ type: 'toggle-open' }),
			toggleTree: () => dispatch({ type: 'toggle-tree' })
		}),
		[latest]
	);
	return { tabs, active: state.active, open: state.open, treeOpen: state.tree, ...actions };
}

export type PanelTabs = ReturnType<typeof usePanelTabs>;

'use client';

import * as React from 'react';

import type { HarnessEvent } from '@/components/ui/coding-agent/harness';

/**
 * A store a host pushes harness events into as they happen, for harnesses that stream rather than hand over a
 * finished log. The template subscribes to it; nothing else is needed on the host's side.
 */
export type HarnessStore = {
	push: (...events: HarnessEvent[]) => void;
	/** The full log so far. The same array until something is pushed. */
	getEvents: () => readonly HarnessEvent[];
	subscribe: (listener: () => void) => () => void;
	clear: () => void;
};

export function createHarnessStore(initial: readonly HarnessEvent[] = []): HarnessStore {
	let events: readonly HarnessEvent[] = initial;
	const listeners = new Set<() => void>();
	const notify = () => {
		for (const listener of listeners) listener();
	};
	return {
		push: (...next) => {
			if (next.length === 0) return;
			events = [...events, ...next];
			notify();
		},
		getEvents: () => events,
		subscribe: (listener) => {
			listeners.add(listener);
			return () => listeners.delete(listener);
		},
		clear: () => {
			events = [];
			notify();
		}
	};
}

const EMPTY: readonly HarnessEvent[] = [];

/** The store's events, re-rendering as they arrive. */
export function useHarnessStoreEvents(store: HarnessStore | undefined) {
	return React.useSyncExternalStore(
		store ? store.subscribe : noopSubscribe,
		store ? store.getEvents : () => EMPTY,
		store ? store.getEvents : () => EMPTY
	);
}

function noopSubscribe() {
	return () => {};
}

import type { AskAnswer, AskQuestion } from '@/components/ui/ai/ask-card';
import { diffLines } from '@/components/ui/ai/line-diff';
import type { PlanStep } from '@/components/ui/ai/types';

/**
 * The template's model of an agent harness. Whatever the host runs (one agent, sub-agents, a team that messages
 * itself, an orchestrator with workers), it reports as a log of these events, and `reduceHarness` folds the log
 * into what the views draw. The scripted demo is one producer of this log; a real harness is another.
 */

export type RunStatus = 'queued' | 'running' | 'waiting' | 'idle' | 'paused' | 'done' | 'failed' | 'cancelled';

/** Why a run is waiting. One status with a reason keeps blocked states from multiplying. */
export type WaitingOn =
	| { kind: 'human'; requestId: string }
	| { kind: 'agent'; runIds: string[] }
	| { kind: 'task'; taskIds: string[] }
	| { kind: 'limit'; reason: 'concurrency' | 'usage' | 'budget' };

export type RunRole = 'root' | 'orchestrator' | 'worker' | 'teammate' | 'peer' | 'remote';

export type RunUsage = { inputTokens: number; outputTokens: number; toolUses: number; durationMs: number; costUsd?: number };

/** What a person may do to a run from the UI. The harness decides; by default a child can be steered and stopped. */
export type RunCapabilities = { steer?: boolean; message?: boolean; stop?: boolean; pause?: boolean };

export type AgentRun = {
	id: string;
	/** Stays the same when a run is resumed under a new run id. */
	agentId?: string;
	name: string;
	/** The agent's definition, e.g. "Explore" or a custom agent. Shown beside the name. */
	kind?: string;
	parentRunId?: string;
	role: RunRole;
	phase?: string;
	attempt?: number;
	background?: boolean;
	task?: string;
	workspace?: { kind: 'shared' | 'worktree' | 'remote'; branch?: string; path?: string };
	budget?: { maxCostUsd?: number };
	capabilities?: RunCapabilities;
};

export type MessageProtocol = 'text' | 'steer' | 'result' | 'plan-approval' | 'shutdown';

export type HarnessTask = {
	id: string;
	title: string;
	status: 'pending' | 'in_progress' | 'blocked' | 'done' | 'failed';
	ownerRunId?: string;
	dependsOn?: string[];
};

export type HarnessRequest = { id: string; type: 'approval'; title: string; command: string } | { id: string; type: 'question'; questions: AskQuestion[] };

export type PermissionDecision = 'once' | 'always' | 'deny';

/** How a person settled a request: a decision on a command, or an answer to a question. */
export type RequestResolution = { decision: PermissionDecision } | { answer: AskAnswer };

export type CheckStatus = 'queued' | 'running' | 'passed' | 'failed' | 'skipped' | 'cancelled';

/** One CI check on a pull request: a job, a status context, or a bot's verdict. */
export type CICheck = {
	id: string;
	name: string;
	status: CheckStatus;
	/** Merging waits on it. */
	required?: boolean;
	/** One line of what it found, e.g. "2 failed in csrf.spec.ts". Shown for failures. */
	summary?: string;
};

export type PullRequestState = 'draft' | 'open' | 'merged' | 'closed';

/** Whether the pull request can merge right now, and if not, what's in the way. */
export type MergeState = 'clean' | 'blocked' | 'behind' | 'conflicts' | 'checking';

export type ReviewState = 'approved' | 'changes-requested' | 'commented' | 'pending';

/** What the review needs at a glance: where the pull request stands and which checks failed or are still going. */
export type PullRequest = {
	number: number;
	title: string;
	url?: string;
	state: PullRequestState;
	/** The overall decision across reviewers. */
	review?: ReviewState;
	merge?: MergeState;
	/** Review threads nobody has resolved yet. */
	unresolved?: number;
	checks?: CICheck[];
};

/**
 * Where changes land: the session's own checkout, or a worktree on its own branch. Agents that work in a worktree
 * register it when they spawn; a harness reports the rest (how far it is from its base, its pull request).
 */
export type Worktree = {
	/** Stable key; the branch name unless two worktrees share one. */
	id: string;
	branch: string;
	/** The branch it was cut from and its pull request merges into. */
	base?: string;
	kind: 'checkout' | 'worktree' | 'remote';
	path?: string;
	/** Commits ahead of and behind its base. */
	ahead?: number;
	behind?: number;
	/** Files that conflict with its base. */
	conflicts?: string[];
	pr?: PullRequest;
};

export type WorktreePatch = Partial<Worktree> & { id: string };
export type PullRequestPatch = Partial<PullRequest>;
export type CheckPatch = Partial<CICheck> & { id: string };

/** One read-only call in a batch, e.g. a read of `src/auth/session.ts`. */
export type ToolCallBeat = {
	tool: 'read' | 'grep' | 'glob' | 'list' | 'webfetch' | 'websearch';
	target: string;
};

/** One step a run takes: what it said, read, changed or ran. Each is a row of its transcript, except the plan. */
export type FlowBeat =
	| { kind: 'user'; text: string }
	| { kind: 'reasoning'; text: string; durationMs: number }
	| { kind: 'say'; text: string }
	| { kind: 'tools'; calls: ToolCallBeat[] }
	/** Lands in the run's worktree, or in `worktree` when an agent edits one that isn't its own. */
	| { kind: 'edit'; path: string; after: string; worktree?: string }
	| { kind: 'shell'; command: string; output: string; exitCode?: number }
	/** Docks on the composer instead of taking a row, so it updates in place as steps finish. */
	| { kind: 'plan'; steps: PlanStep[] }
	| { kind: 'browse'; url: string; title: string }
	| { kind: 'notice'; text: string }
	| { kind: 'error'; title: string; text: string };

/** One thing that happened in a run. `runId` is who it happened to. */
export type HarnessEvent = { id: string; runId: string } & (
	| { kind: 'run.spawned'; run: AgentRun }
	| { kind: 'run.status'; status: RunStatus; waitingOn?: WaitingOn; summary?: string; error?: string }
	| { kind: 'run.progress'; usage: Partial<RunUsage>; lastTool?: string }
	| { kind: 'beat'; beat: FlowBeat; live?: boolean; running?: boolean }
	| { kind: 'beat.settled'; eventId: string }
	| { kind: 'turn.end' }
	/** From `runId` unless `from` says otherwise, e.g. `you` for a person steering a run. */
	| { kind: 'message'; from?: string; to: string[] | 'all'; text: string; protocol?: MessageProtocol }
	| { kind: 'handoff'; to: string; reason?: string }
	| { kind: 'route'; to: string; reason?: string }
	| { kind: 'phase'; name: string; status: 'running' | 'done' }
	| { kind: 'fan-in'; runIds: string[] }
	| { kind: 'task'; task: HarnessTask }
	| { kind: 'request'; request: HarnessRequest }
	/** Settles a request of `runId`'s; a run held at it carries on. */
	| ({ kind: 'request.resolved'; requestId: string } & RequestResolution)
	| { kind: 'terminal'; lines: { kind: 'command' | 'output' | 'error'; text: string }[] }
	| { kind: 'terminal.clear' }
	/** Adds a worktree or updates what's known about it. */
	| { kind: 'worktree'; worktree: WorktreePatch }
	/** Opens or updates the pull request for a worktree. Checks given here replace the list; use `check` for one. */
	| { kind: 'pr'; worktreeId: string; pr: PullRequestPatch }
	/** Adds or updates one CI check on a worktree's pull request. */
	| { kind: 'check'; worktreeId: string; check: CheckPatch }
);

export type HarnessEventKind = HarnessEvent['kind'];

/** One row of a run's transcript. Live rows arrived during playback and animate in; history rows land settled. */
export type TimelineItem =
	| { id: string; type: 'beat'; beat: Exclude<FlowBeat, { kind: 'plan' }>; live: boolean; running?: boolean; before?: string | null }
	| { id: string; type: 'permission'; requestId: string; beat: { title: string; command: string }; decision?: PermissionDecision }
	| { id: string; type: 'question'; requestId: string; beat: { questions: AskQuestion[] }; answer?: AskAnswer }
	| { id: string; type: 'turn-end'; paths: string[]; additions: number; deletions: number }
	| { id: string; type: 'spawn'; runId: string }
	| { id: string; type: 'fan-in'; runIds: string[] }
	| { id: string; type: 'message'; from: string; to: string[] | 'all'; text: string; protocol: MessageProtocol }
	| { id: string; type: 'handoff'; to: string; reason?: string }
	| { id: string; type: 'route'; to: string; reason?: string }
	| { id: string; type: 'phase'; name: string; status: 'running' | 'done' };

/** A file the session changed: its contents before the session touched it (null when it's new) and now. */
export type FileChange = {
	/** Unique across worktrees: the same path can change in two of them. */
	key: string;
	path: string;
	/** The worktree the change landed in. */
	worktreeId: string;
	before: string | null;
	after: string;
	additions: number;
	deletions: number;
	runIds: string[];
};

export type TerminalLine = { id: string; kind: 'command' | 'output' | 'error'; text: string; runId: string };

export type RunView = AgentRun & {
	status: RunStatus;
	waitingOn?: WaitingOn;
	summary?: string;
	error?: string;
	lastTool?: string;
	usage: RunUsage;
	/** True once the harness reports usage itself; until then the view estimates tokens from the transcript. */
	usageReported: boolean;
	items: TimelineItem[];
	plan: PlanStep[] | null;
	/** Keys of the changes made since the turn began. */
	turnPaths: string[];
	depth: number;
	/** The worktree it works in: its own, or the nearest ancestor's, or the session's checkout. Set when it spawns. */
	worktreeId: string;
};

export type HarnessMessage = { id: string; from: string; to: string[] | 'all'; text: string; protocol: MessageProtocol };

export type HarnessView = {
	rootRunId: string;
	runs: Record<string, RunView>;
	/** Runs in the order they were spawned, the root first. */
	runOrder: string[];
	base: Record<string, string>;
	/** The session's own checkout as it stands now. Edits in other worktrees stay in `changes`. */
	files: Record<string, string>;
	changes: Record<string, FileChange>;
	terminal: TerminalLine[];
	tasks: HarnessTask[];
	messages: HarnessMessage[];
	/** Requests still waiting on a person, oldest first. */
	pending: { runId: string; request: HarnessRequest }[];
	/** Every worktree the session's agents work in, the session's own checkout first. */
	worktrees: Record<string, Worktree>;
	worktreeOrder: string[];
	/** The run that has control after a handoff, if any. */
	activeRunId: string;
	/** The page an agent last opened. A new object for each visit, so opening the same page again still shows it. */
	browse: { url: string; title: string } | null;
};

const ZERO_USAGE: RunUsage = { inputTokens: 0, outputTokens: 0, toolUses: 0, durationMs: 0 };

export function createRunView(run: AgentRun, depth: number, worktreeId: string): RunView {
	return { status: 'queued', usage: ZERO_USAGE, usageReported: false, items: [], plan: null, turnPaths: [], depth, worktreeId, ...run };
}

/** The checkout a session works in when nothing says otherwise. */
const DEFAULT_CHECKOUT: Worktree = { id: 'checkout', branch: 'main', kind: 'checkout' };

/** The session's own checkout: the first worktree it knew about. */
function checkoutOf(view: HarnessView) {
	return view.worktreeOrder[0] ?? DEFAULT_CHECKOUT.id;
}

/**
 * The empty view a session starts from: one root run, the project's files, and the worktrees already known, the
 * session's own checkout first.
 */
export function createHarnessView(root: AgentRun, files: Record<string, string>, worktrees: readonly Worktree[] = [DEFAULT_CHECKOUT]): HarnessView {
	const known = worktrees.length ? worktrees : [DEFAULT_CHECKOUT];
	return {
		rootRunId: root.id,
		runs: { [root.id]: { ...createRunView(root, 0, known[0].id), status: 'idle', usage: { ...ZERO_USAGE, inputTokens: BASE_TOKENS.root } } },
		runOrder: [root.id],
		base: files,
		files,
		changes: {},
		terminal: [],
		tasks: [],
		messages: [],
		pending: [],
		worktrees: Object.fromEntries(known.map((worktree) => [worktree.id, worktree])),
		worktreeOrder: known.map((worktree) => worktree.id),
		activeRunId: root.id,
		browse: null
	};
}

/** A file's lines, without the empty one a trailing newline would add. */
function linesOf(text: string | null) {
	if (!text) return [];
	return (text.endsWith('\n') ? text.slice(0, -1) : text).split('\n');
}

export function countChange(before: string | null, after: string) {
	let additions = 0;
	let deletions = 0;
	for (const line of diffLines(linesOf(before), linesOf(after))) {
		if (line.type === 'add') additions += 1;
		else if (line.type === 'del') deletions += 1;
	}
	return { additions, deletions };
}

/** A rough running total for runs whose harness doesn't report usage: about four characters a token. */
function estimateBeat(beat: FlowBeat, files: Record<string, string>) {
	switch (beat.kind) {
		case 'say':
		case 'reasoning':
		case 'user':
			return beat.text.length / 4;
		case 'edit':
			return beat.after.length / 4;
		case 'shell':
			return (beat.output.length + beat.command.length) / 4;
		case 'tools':
			return beat.calls.reduce((sum, call) => sum + (call.tool === 'read' ? (files[call.target]?.length ?? 800) : 600), 0) / 4;
		default:
			return 0;
	}
}

/** What a step reports on its run's row: the tool calls it made and the last of them, or its reply as the summary. */
function stepReport(beat: FlowBeat): { toolUses?: number; lastTool?: string; summary?: string } {
	switch (beat.kind) {
		case 'tools': {
			const last = beat.calls[beat.calls.length - 1];
			return { toolUses: beat.calls.length, lastTool: last ? `${last.tool} ${last.target}` : undefined };
		}
		case 'edit':
			return { toolUses: 1, lastTool: `edit ${beat.path}` };
		case 'shell':
			return { toolUses: 1, lastTool: beat.command };
		case 'say':
			return { summary: beat.text };
		default:
			return {};
	}
}

/** Prompt and tool definitions every run starts with, so a fresh agent doesn't read as empty. */
export const BASE_TOKENS = { root: 14_200, child: 6_400 } as const;

function patchRun(view: HarnessView, runId: string, patch: (run: RunView) => RunView) {
	const run = view.runs[runId];
	if (!run) return view;
	return { ...view, runs: { ...view.runs, [runId]: patch(run) } };
}

function pushItem(run: RunView, item: TimelineItem): RunView {
	return { ...run, items: [...run.items, item] };
}

function addTokens(run: RunView, tokens: number): RunView {
	if (run.usageReported || !tokens) return run;
	return { ...run, usage: { ...run.usage, inputTokens: run.usage.inputTokens + Math.round(tokens) } };
}

/** The key a change is stored under: its worktree and its path. */
export function changeKey(worktreeId: string, path: string) {
	return `${worktreeId}:${path}`;
}

/** Adds a worktree, or merges what's new into the one already known. */
function upsertWorktree(view: HarnessView, patch: WorktreePatch): HarnessView {
	const existing = view.worktrees[patch.id];
	const worktree: Worktree = existing ? { ...existing, ...patch } : { branch: patch.id, kind: 'worktree', ...patch };
	return {
		...view,
		worktrees: { ...view.worktrees, [patch.id]: worktree },
		worktreeOrder: existing ? view.worktreeOrder : [...view.worktreeOrder, patch.id]
	};
}

/** A pull request a patch opens before the harness has said what it is. */
function placeholderPr(worktree: Worktree): PullRequest {
	return { number: 0, title: worktree.branch, state: 'open' };
}

/**
 * Lands an edit in the run's worktree, or in the one it names, so one agent can touch several. Every worktree keeps
 * its own change; only an edit to the session's checkout changes the files the tree and the viewer show.
 */
function applyEdit(view: HarnessView, runId: string, beat: Extract<FlowBeat, { kind: 'edit' }>) {
	const state = beat.worktree && !view.worktrees[beat.worktree] ? upsertWorktree(view, { id: beat.worktree }) : view;
	const worktreeId = beat.worktree ?? view.runs[runId]?.worktreeId ?? checkoutOf(view);
	const key = changeKey(worktreeId, beat.path);
	const original = beat.path in view.base ? view.base[beat.path] : null;
	const existing = view.changes[key];
	const runIds = existing?.runIds.includes(runId) ? existing.runIds : [...(existing?.runIds ?? []), runId];
	const change: FileChange = { key, path: beat.path, worktreeId, before: original, after: beat.after, runIds, ...countChange(original, beat.after) };
	return {
		key,
		// The row's inline diff is against what the file held just before this edit.
		before: existing ? existing.after : original,
		view: {
			...state,
			files: worktreeId === checkoutOf(view) ? { ...view.files, [beat.path]: beat.after } : view.files,
			changes: { ...view.changes, [key]: change }
		}
	};
}

/** A command's lines in the terminal: the command, what it printed, and how it ended if it failed. */
function applyShell(view: HarnessView, eventId: string, runId: string, beat: Extract<FlowBeat, { kind: 'shell' }>): HarnessView {
	const lines: TerminalLine[] = [{ id: `${eventId}-c`, kind: 'command', text: beat.command, runId }];
	if (beat.output) {
		beat.output
			.replace(/\n+$/, '')
			.split('\n')
			.forEach((text, index) => lines.push({ id: `${eventId}-${index}`, kind: 'output', text, runId }));
	}
	// What the command printed stays as it was; only how it ended is marked as an error.
	if (beat.exitCode) lines.push({ id: `${eventId}-x`, kind: 'error', text: `exited with code ${beat.exitCode}`, runId });
	return { ...view, terminal: [...view.terminal, ...lines] };
}

/** Folds one event into the view. Pure, so a host can replay a stored log and get the same screen. */
export function reduceHarness(view: HarnessView, event: HarnessEvent): HarnessView {
	switch (event.kind) {
		case 'run.spawned': {
			const parent = event.run.parentRunId ? view.runs[event.run.parentRunId] : undefined;
			let state = view;
			// A run works where its parent does, unless it brings a worktree of its own.
			let worktreeId = parent?.worktreeId ?? checkoutOf(view);
			const workspace = event.run.workspace;
			if (workspace && workspace.kind !== 'shared' && workspace.branch) {
				worktreeId = workspace.branch;
				// A new one joins the session, cut from the worktree its parent works in.
				if (!view.worktrees[workspace.branch]) {
					const base = parent ? view.worktrees[parent.worktreeId]?.branch : undefined;
					state = upsertWorktree(state, { id: workspace.branch, branch: workspace.branch, kind: workspace.kind, path: workspace.path, base });
				}
			}
			const existing = view.runs[event.run.id];
			const run: RunView = existing
				? { ...existing, ...event.run, worktreeId }
				: { ...createRunView(event.run, parent ? parent.depth + 1 : 0, worktreeId), usage: { ...ZERO_USAGE, inputTokens: BASE_TOKENS.child } };
			state = { ...state, runs: { ...state.runs, [run.id]: run }, runOrder: existing ? state.runOrder : [...state.runOrder, run.id] };
			// The spawn shows in the parent's transcript as the card that opens the child.
			return parent ? patchRun(state, parent.id, (owner) => pushItem(owner, { id: event.id, type: 'spawn', runId: run.id })) : state;
		}
		case 'run.status': {
			const updated = patchRun(view, event.runId, (run) => ({
				...run,
				status: event.status,
				waitingOn: event.status === 'waiting' ? event.waitingOn : undefined,
				summary: event.summary ?? run.summary,
				error: event.error ?? (event.status === 'failed' ? run.error : undefined)
			}));
			// A run that has ended can't act on an answer, so whatever it was still asking leaves the dock with it.
			const ended = event.status === 'cancelled' || event.status === 'done' || event.status === 'failed';
			return ended && view.pending.some((entry) => entry.runId === event.runId)
				? { ...updated, pending: view.pending.filter((entry) => entry.runId !== event.runId) }
				: updated;
		}
		case 'run.progress':
			return patchRun(view, event.runId, (run) => ({
				...run,
				usage: { ...run.usage, ...event.usage },
				usageReported: true,
				lastTool: event.lastTool ?? run.lastTool
			}));
		case 'beat': {
			const beat = event.beat;
			// One tracker per turn, on the run: a later plan updates it in place.
			if (beat.kind === 'plan') return patchRun(view, event.runId, (run) => ({ ...run, plan: beat.steps }));
			let state = view;
			let before: string | null | undefined;
			let editKey: string | undefined;
			if (beat.kind === 'edit') {
				const edit = applyEdit(view, event.runId, beat);
				state = edit.view;
				before = edit.before;
				editKey = edit.key;
			}
			if (beat.kind === 'shell') state = applyShell(state, event.id, event.runId, beat);
			if (beat.kind === 'browse' && event.live) state = { ...state, browse: { url: beat.url, title: beat.title } };
			const tokens = estimateBeat(beat, view.files);
			const report = stepReport(beat);
			return patchRun(state, event.runId, (run) => {
				let updated = addTokens(run, tokens);
				updated = {
					...updated,
					usage: report.toolUses && !updated.usageReported ? { ...updated.usage, toolUses: updated.usage.toolUses + report.toolUses } : updated.usage,
					lastTool: report.lastTool ?? updated.lastTool,
					summary: report.summary ?? updated.summary
				};
				if (beat.kind === 'user') updated = { ...updated, turnPaths: [], plan: null };
				if (editKey && !updated.turnPaths.includes(editKey)) updated = { ...updated, turnPaths: [...updated.turnPaths, editKey] };
				return pushItem(updated, { id: event.id, type: 'beat', beat, live: event.live ?? true, running: event.running, before });
			});
		}
		case 'beat.settled':
			return patchRun(view, event.runId, (run) => ({
				...run,
				items: run.items.map((item) => (item.id === event.eventId && item.type === 'beat' ? { ...item, running: false } : item))
			}));
		case 'turn.end':
			return patchRun(view, event.runId, (run) => {
				if (run.turnPaths.length === 0) return run;
				const changes = run.turnPaths.flatMap((key) => view.changes[key] ?? []);
				// The same path changed in two worktrees is one file to read about.
				const paths = [...new Set(changes.map((change) => change.path))];
				return { ...pushItem(run, { id: event.id, type: 'turn-end', paths, ...lineTotals(changes) }), turnPaths: [] };
			});
		case 'message': {
			const from = event.from ?? event.runId;
			const message: HarnessMessage = { id: event.id, from, to: event.to, text: event.text, protocol: event.protocol ?? 'text' };
			const item: TimelineItem = { type: 'message', ...message };
			let state: HarnessView = { ...view, messages: [...view.messages, message] };
			// A message reads in the sender's transcript and in each recipient's.
			const recipients = event.to === 'all' ? view.runOrder.filter((id) => id !== from) : event.to;
			for (const runId of new Set([from, ...recipients])) {
				if (state.runs[runId]) state = patchRun(state, runId, (run) => pushItem(run, item));
			}
			return state;
		}
		case 'handoff':
			return { ...patchRun(view, event.runId, (run) => pushItem(run, { id: event.id, type: 'handoff', to: event.to, reason: event.reason })), activeRunId: event.to };
		case 'route':
			return patchRun(view, event.runId, (run) => pushItem(run, { id: event.id, type: 'route', to: event.to, reason: event.reason }));
		case 'phase':
			return patchRun(view, event.runId, (run) => {
				const index = run.items.findIndex((item) => item.type === 'phase' && item.name === event.name);
				if (index < 0) return pushItem(run, { id: event.id, type: 'phase', name: event.name, status: event.status });
				return { ...run, items: run.items.map((item, at) => (at === index && item.type === 'phase' ? { ...item, status: event.status } : item)) };
			});
		case 'fan-in':
			return patchRun(view, event.runId, (run) => pushItem(run, { id: event.id, type: 'fan-in', runIds: event.runIds }));
		case 'task': {
			const exists = view.tasks.some((task) => task.id === event.task.id);
			return { ...view, tasks: exists ? view.tasks.map((task) => (task.id === event.task.id ? { ...task, ...event.task } : task)) : [...view.tasks, event.task] };
		}
		case 'request': {
			const request = event.request;
			const item: TimelineItem =
				request.type === 'approval'
					? { id: event.id, type: 'permission', requestId: request.id, beat: { title: request.title, command: request.command } }
					: { id: event.id, type: 'question', requestId: request.id, beat: { questions: request.questions } };
			const state = { ...view, pending: [...view.pending, { runId: event.runId, request }] };
			return patchRun(state, event.runId, (run) => ({
				...pushItem(run, item),
				status: 'waiting',
				waitingOn: { kind: 'human', requestId: request.id }
			}));
		}
		case 'request.resolved': {
			const state = { ...view, pending: view.pending.filter((entry) => entry.request.id !== event.requestId) };
			return patchRun(state, event.runId, (run) => {
				const items = run.items.map((item) => {
					if (item.type === 'permission' && item.requestId === event.requestId && 'decision' in event) return { ...item, decision: event.decision };
					if (item.type === 'question' && item.requestId === event.requestId && 'answer' in event) return { ...item, answer: event.answer };
					return item;
				});
				// A run held at this request carries on; one that moved on meanwhile keeps the status it has.
				if (awaitsPerson(run) && run.waitingOn.requestId === event.requestId) return { ...run, items, status: 'running', waitingOn: undefined };
				return { ...run, items };
			});
		}
		case 'terminal':
			return {
				...view,
				terminal: [...view.terminal, ...event.lines.map((line, index) => ({ ...line, id: `${event.id}-${index}`, runId: event.runId }))]
			};
		case 'terminal.clear':
			return { ...view, terminal: [] };
		case 'worktree':
			return upsertWorktree(view, event.worktree);
		case 'pr': {
			const state = view.worktrees[event.worktreeId] ? view : upsertWorktree(view, { id: event.worktreeId });
			const worktree = state.worktrees[event.worktreeId];
			return upsertWorktree(state, { id: worktree.id, pr: { ...(worktree.pr ?? placeholderPr(worktree)), ...event.pr } });
		}
		case 'check': {
			const state = view.worktrees[event.worktreeId] ? view : upsertWorktree(view, { id: event.worktreeId });
			const worktree = state.worktrees[event.worktreeId];
			const pr = worktree.pr ?? placeholderPr(worktree);
			const checks = pr.checks ?? [];
			const found = checks.some((check) => check.id === event.check.id);
			const nextChecks = found
				? checks.map((check) => (check.id === event.check.id ? { ...check, ...event.check } : check))
				: [...checks, { name: event.check.id, status: 'queued' as const, ...event.check }];
			return upsertWorktree(state, { id: worktree.id, pr: { ...pr, checks: nextChecks } });
		}
	}
}

/** Lines added and removed across a set of changes. */
export function lineTotals(changes: readonly FileChange[]) {
	let additions = 0;
	let deletions = 0;
	for (const change of changes) {
		additions += change.additions;
		deletions += change.deletions;
	}
	return { additions, deletions };
}

export type CheckTally = { total: number; passed: number; failed: number; running: number; queued: number; skipped: number; requiredFailing: number };

/** Counts a pull request's checks by outcome. */
export function tallyChecks(checks: readonly CICheck[] = []): CheckTally {
	const tally: CheckTally = { total: checks.length, passed: 0, failed: 0, running: 0, queued: 0, skipped: 0, requiredFailing: 0 };
	for (const check of checks) {
		if (check.status === 'passed') tally.passed += 1;
		else if (check.status === 'failed') {
			tally.failed += 1;
			if (check.required) tally.requiredFailing += 1;
		} else if (check.status === 'running') tally.running += 1;
		else if (check.status === 'queued') tally.queued += 1;
		else tally.skipped += 1;
	}
	return tally;
}

export type ChecksOutcome = 'failed' | 'running' | 'passed' | 'none';

/** One word for a set of checks: any failure wins, then anything still going, then passed. */
export function checksOutcome(tally: CheckTally): ChecksOutcome {
	if (tally.total === 0) return 'none';
	if (tally.failed) return 'failed';
	if (tally.running || tally.queued) return 'running';
	return 'passed';
}

export type WorktreeSummary = {
	worktree: Worktree;
	changes: FileChange[];
	additions: number;
	deletions: number;
	/** Agents working in it or that changed files in it, in spawn order. */
	runIds: string[];
	checks: CheckTally;
};

/** Each worktree with the changes that landed in it and the agents involved, in the order they joined the session. */
export function summarizeWorktrees(view: HarnessView): WorktreeSummary[] {
	const changes = Object.values(view.changes);
	return view.worktreeOrder.map((id) => {
		const worktree = view.worktrees[id];
		const own = changes.filter((change) => change.worktreeId === id);
		const editors = new Set(own.flatMap((change) => change.runIds));
		const runIds = view.runOrder.filter((runId) => editors.has(runId) || view.runs[runId]?.worktreeId === id);
		return {
			worktree,
			changes: own,
			...lineTotals(own),
			runIds,
			checks: tallyChecks(worktree.pr?.checks)
		};
	});
}

/** Across every pull request in the session: whether any check failed, any is still going, or all passed. */
export function sessionChecks(worktrees: readonly WorktreeSummary[]) {
	return checksOutcome(tallyChecks(worktrees.flatMap((entry) => entry.worktree.pr?.checks ?? [])));
}

/** Replays a log onto a starting view. */
export function replayHarness(view: HarnessView, events: readonly HarnessEvent[]) {
	return events.reduce(reduceHarness, view);
}

/** Tokens a run has used: what the harness reported, or the estimate. */
export function runTokens(run: RunView) {
	return run.usage.inputTokens + run.usage.outputTokens;
}

/** The run and everything it spawned, depth first. */
export function descendants(view: HarnessView, runId: string): RunView[] {
	const out: RunView[] = [];
	const visit = (id: string) => {
		for (const childId of view.runOrder) {
			const child = view.runs[childId];
			if (child?.parentRunId === id) {
				out.push(child);
				visit(childId);
			}
		}
	};
	visit(runId);
	return out;
}

/** Runs from the root down to `runId`, for the breadcrumb. */
export function ancestry(view: HarnessView, runId: string): RunView[] {
	const out: RunView[] = [];
	let current: RunView | undefined = view.runs[runId];
	while (current) {
		out.unshift(current);
		current = current.parentRunId ? view.runs[current.parentRunId] : undefined;
	}
	return out;
}

export const ACTIVE_STATUSES: RunStatus[] = ['queued', 'running', 'waiting', 'paused'];

/** The run is held until a person approves a command or answers a question. */
export function awaitsPerson(run: RunView): run is RunView & { status: 'waiting'; waitingOn: { kind: 'human'; requestId: string } } {
	return run.status === 'waiting' && run.waitingOn?.kind === 'human';
}

/** Still has work in hand: queued, running, paused, or waiting on other agents, tasks or limits. Not one held for a person. */
export function isWorking(run: RunView) {
	return ACTIVE_STATUSES.includes(run.status) && !awaitsPerson(run);
}

/** Live state a session reports back to the shell, for its tab, sidebar row and the home list. */
export type SessionStatus = 'idle' | 'running' | 'approval' | 'input' | 'failed';

/** A session's states, plus queued, and done once a run has reported back. */
export type RunSignal = SessionStatus | 'queued' | 'done';

/** What a run means for a tab, a row or a ring: running, waiting on a person, failed, or at rest. */
export function runSignal(run: RunView, view: HarnessView): RunSignal {
	if (awaitsPerson(run)) {
		const request = view.pending.find((entry) => entry.request.id === run.waitingOn.requestId)?.request;
		return request?.type === 'question' ? 'input' : 'approval';
	}
	if (run.status === 'running' || run.status === 'waiting') return 'running';
	if (run.status === 'queued') return 'queued';
	if (run.status === 'failed') return 'failed';
	if (run.status === 'done') return 'done';
	return 'idle';
}

/** The session's status for its tab: whatever needs a person most, across every run. */
export function sessionStatus(view: HarnessView): SessionStatus {
	const signals = view.runOrder.map((id) => runSignal(view.runs[id], view));
	if (signals.includes('approval')) return 'approval';
	if (signals.includes('input')) return 'input';
	if (runSignal(view.runs[view.rootRunId], view) === 'failed') return 'failed';
	if (signals.includes('running') || signals.includes('queued')) return 'running';
	if (signals.includes('failed')) return 'failed';
	return 'idle';
}

/** Where a sub-agent's transcript opens: the task its parent gave it, which is also its first turn on the rail. */
export const TASK_TURN_ID = 'task';

'use client';

import * as React from 'react';

import type { AskAnswer } from '@/components/ui/ai/ask-card';
import { REDUCED_MOTION_DELAY } from '@/components/ui/agents-builder/playback';
import { prefersReducedMotion } from '@/components/ui/workspace-kit/reduced-motion';
import {
	type AgentRun,
	awaitsPerson,
	createHarnessView,
	type HarnessEvent,
	type HarnessRequest,
	type HarnessView,
	type PermissionDecision,
	reduceHarness,
	type RequestResolution,
	type RunCapabilities,
	type RunStatus,
	runTokens,
	sessionStatus,
	summarizeWorktrees,
	type Worktree
} from '@/components/ui/coding-agent/harness';
import { useHarnessStoreEvents } from '@/components/ui/coding-agent/harness-store';
import type { CodingAgentAction, CodingSession, SessionBeat, SessionBeatKind } from '@/components/ui/coding-agent/types';

/** Default wait before each kind lands, in ms. */
const BEAT_DELAY: Record<SessionBeatKind, number> = {
	user: 250,
	reasoning: 500,
	say: 450,
	tools: 500,
	edit: 900,
	shell: 600,
	plan: 400,
	permission: 600,
	question: 600,
	browse: 600,
	notice: 300,
	error: 700,
	spawn: 500,
	await: 300,
	message: 700,
	handoff: 500,
	route: 500,
	phase: 300,
	task: 250,
	worktree: 200,
	pr: 600,
	check: 500
};

/** How long a running command or tool batch spins before it settles. */
const SETTLE_MS = { shell: 1300, tools: 1100 } as const;


/** What a scripted child may do unless its spawn says otherwise. */
const CHILD_CAPABILITIES: RunCapabilities = { steer: true, stop: true, pause: true };

/** Typewriter pace for replies: fast enough to read along, capped so long answers don't stall the run. */
export function revealDuration(text: string) {
	return Math.min(Math.max(text.length * 9, 450), 2400);
}

function holdFor(beat: SessionBeat) {
	if (beat.kind === 'say') return revealDuration(beat.text);
	if (beat.kind === 'reasoning') return beat.durationMs;
	return 0;
}

type Op = { id: string; delay: number } & ({ op: 'beat'; beat: SessionBeat } | { op: 'settle'; eventId?: string });

/**
 * Where a scripted run is in its script. Everything the view also shows (its status, a pause, the request it is held
 * at) lives in the harness view alone, so the two can't disagree.
 */
type Flow = {
	queue: Op[];
	/** Messages sent while the run was busy, waiting for its turn to end. */
	queued: { id: string; text: string }[];
	/** What a retry repeats. */
	lastStep: SessionBeat | null;
	played: number;
	/** Children this run is waiting on before it continues. */
	awaiting: string[] | null;
};

type ScriptState = { flows: Record<string, Flow>; view: HarnessView; nextId: number; followUp: (text: string) => SessionBeat[] };

type ScriptAction =
	| { type: 'due'; runId: string; opId: string }
	| { type: 'resolve'; requestId: string; decision: PermissionDecision }
	| { type: 'answer'; requestId: string; answer: AskAnswer }
	| { type: 'send'; runId: string; text: string; beats: SessionBeat[]; attachments: string[]; steer?: boolean }
	| { type: 'unqueue'; runId: string; id: string }
	| { type: 'stop'; runId: string }
	| { type: 'pause'; runId: string }
	| { type: 'resume'; runId: string }
	| { type: 'retry'; runId: string }
	| { type: 'terminal'; lines: { kind: 'command' | 'output' | 'error'; text: string }[] }
	| { type: 'clear-terminal' };

const TERMINAL: RunStatus[] = ['done', 'failed', 'cancelled', 'idle'];

/** Beats that report on the run instead of being a step it took. */
const SIDE_BEATS: SessionBeatKind[] = ['error', 'notice', 'worktree', 'pr', 'check'];

function nextId(state: ScriptState, prefix: string) {
	state.nextId += 1;
	return `${prefix}-${state.nextId}`;
}

type EventInput = HarnessEvent extends infer E ? (E extends HarnessEvent ? Omit<E, 'id'> : never) : never;

function emit(state: ScriptState, event: EventInput) {
	const id = nextId(state, 'e');
	state.view = reduceHarness(state.view, { ...event, id } as HarnessEvent);
	return id;
}

function statusOf(state: ScriptState, runId: string): RunStatus | undefined {
	return state.view.runs[runId]?.status;
}

function isSettled(state: ScriptState, runId: string) {
	return TERMINAL.includes(statusOf(state, runId) ?? 'done');
}

function setStatus(state: ScriptState, runId: string, status: RunStatus, extra: { waitingOn?: Extract<HarnessEvent, { kind: 'run.status' }>['waitingOn']; summary?: string } = {}) {
	emit(state, { kind: 'run.status', runId, status, ...extra });
}

function op(state: ScriptState, beat: SessionBeat): Op {
	return { id: nextId(state, 'op'), op: 'beat', beat, delay: beat.delay ?? BEAT_DELAY[beat.kind] };
}

function newFlow(): Flow {
	return { queue: [], queued: [], lastStep: null, played: 0, awaiting: null };
}

function childrenOf(state: ScriptState, runId: string) {
	return state.view.runOrder.filter((id) => state.view.runs[id]?.parentRunId === runId);
}

/**
 * Holds a run on a person: a command to approve or a question to answer. In history the gate was settled long ago,
 * so the command was allowed and each question took its first option.
 */
function raise(state: ScriptState, runId: string, beat: Extract<SessionBeat, { kind: 'permission' | 'question' }>, live: boolean) {
	const id = nextId(state, 'req');
	const request: HarnessRequest =
		beat.kind === 'permission' ? { id, type: 'approval', title: beat.title, command: beat.command } : { id, type: 'question', questions: beat.questions };
	emit(state, { kind: 'request', runId, request });
	if (live) return;
	const resolution: RequestResolution =
		beat.kind === 'permission'
			? { decision: 'once' }
			: { answer: { choices: Object.fromEntries(beat.questions.map((question) => [question.id, { option: question.options[0]?.id ?? '' }])) } };
	emit(state, { kind: 'request.resolved', runId, requestId: id, ...resolution });
}

/** Lands one beat for a run. `live` is false while replaying history, which lands at once and settles every gate. */
function land(state: ScriptState, runId: string, beat: SessionBeat, live: boolean) {
	const flow = state.flows[runId];
	flow.played += 1;
	// Retrying repeats the last thing the agent did, not a status report about its branch.
	if (!SIDE_BEATS.includes(beat.kind)) flow.lastStep = beat;
	switch (beat.kind) {
		case 'permission':
		case 'question':
			raise(state, runId, beat, live);
			return;
		case 'spawn': {
			const childId = beat.agent.id;
			emit(state, {
				kind: 'run.spawned',
				runId: childId,
				run: { ...beat.agent, role: beat.agent.role ?? 'worker', parentRunId: runId, capabilities: beat.agent.capabilities ?? CHILD_CAPABILITIES }
			});
			state.flows[childId] = newFlow();
			// A spawn in history brought its child's whole script with it, unless it says how far the child got.
			const played = beat.played ?? (live ? 0 : beat.script.length);
			setStatus(state, childId, 'running');
			for (const childBeat of beat.script.slice(0, played)) land(state, childId, childBeat, false);
			state.flows[childId].queue = beat.script.slice(played).map((entry) => op(state, entry));
			settle(state, childId);
			return;
		}
		case 'await': {
			const targets = beat.agents ?? childrenOf(state, runId);
			const pending = targets.filter((id) => !isSettled(state, id));
			if (!live || pending.length === 0) {
				emit(state, { kind: 'fan-in', runId, runIds: targets });
				return;
			}
			flow.awaiting = targets;
			setStatus(state, runId, 'waiting', { waitingOn: { kind: 'agent', runIds: pending } });
			return;
		}
		case 'error':
			emit(state, { kind: 'beat', runId, beat, live });
			setStatus(state, runId, 'failed');
			return;
		case 'user':
		case 'reasoning':
		case 'say':
		case 'tools':
		case 'edit':
		case 'shell':
		case 'plan':
		case 'browse':
		case 'notice': {
			// A command or a batch of reads spins for a moment before it settles.
			const spins = live && (beat.kind === 'shell' || beat.kind === 'tools') ? SETTLE_MS[beat.kind] : 0;
			const eventId = emit(state, { kind: 'beat', runId, beat, live, running: spins > 0 });
			if (spins) flow.queue.unshift({ id: nextId(state, 'op'), op: 'settle', eventId, delay: spins });
			return;
		}
		default:
			// The rest are harness events already, sent from this run.
			emit(state, { ...beat, runId });
	}
}

/** When every child a parent waits on has stopped, it gathers their results and carries on. */
function releaseParent(state: ScriptState, childId: string) {
	const parentId = state.view.runs[childId]?.parentRunId;
	const parent = parentId ? state.flows[parentId] : undefined;
	if (!parentId || !parent?.awaiting) return;
	const pending = parent.awaiting.filter((id) => !isSettled(state, id));
	if (pending.length > 0) {
		emit(state, { kind: 'run.status', runId: parentId, status: 'waiting', waitingOn: { kind: 'agent', runIds: pending } });
		return;
	}
	emit(state, { kind: 'fan-in', runId: parentId, runIds: parent.awaiting });
	parent.awaiting = null;
	setStatus(state, parentId, 'running');
	settle(state, parentId);
}

/** Closes a turn once its queue is empty: summarises the changes, sends the next queued message, or rests. */
function settle(state: ScriptState, runId: string) {
	const flow = state.flows[runId];
	if (!flow || statusOf(state, runId) !== 'running' || flow.queue.length > 0 || flow.awaiting) return;
	emit(state, { kind: 'turn.end', runId });
	const [next, ...rest] = flow.queued;
	flow.queued = rest;
	if (next) {
		const beats: SessionBeat[] = [{ kind: 'user', text: next.text, delay: 200 }, ...state.followUp(next.text)];
		flow.queue = beats.map((beat) => op(state, beat));
		return;
	}
	const isRoot = runId === state.view.rootRunId;
	// The session's own agent rests and can be messaged again; a child reports back and is done.
	setStatus(state, runId, isRoot ? 'idle' : 'done', { summary: state.view.runs[runId]?.summary });
	if (!isRoot) releaseParent(state, runId);
}

function stopRun(state: ScriptState, runId: string, note: string) {
	const flow = state.flows[runId];
	if (!flow) return;
	// Dropped first, so the children stopping below don't hand their results back to a run that's stopping too.
	flow.queue = [];
	flow.queued = [];
	flow.awaiting = null;
	// Each child stops its own children; the status is read fresh, so nobody below is stopped twice.
	for (const childId of childrenOf(state, runId)) {
		if (!isSettled(state, childId)) stopRun(state, childId, 'Stopped with its parent.');
	}
	for (const item of state.view.runs[runId]?.items ?? []) {
		if (item.type === 'beat' && item.running) emit(state, { kind: 'beat.settled', runId, eventId: item.id });
	}
	emit(state, { kind: 'beat', runId, beat: { kind: 'notice', text: note } });
	const isRoot = runId === state.view.rootRunId;
	setStatus(state, runId, isRoot ? 'idle' : 'cancelled');
	if (!isRoot) releaseParent(state, runId);
}

function clone(state: ScriptState): ScriptState {
	const flows: Record<string, Flow> = {};
	for (const [id, flow] of Object.entries(state.flows)) flows[id] = { ...flow, queue: [...flow.queue], queued: [...flow.queued] };
	return { ...state, flows };
}

function scriptReducer(current: ScriptState, action: ScriptAction): ScriptState {
	const state = clone(current);
	switch (action.type) {
		case 'due': {
			const flow = state.flows[action.runId];
			const head = flow?.queue[0];
			if (!flow || !head || head.id !== action.opId || statusOf(state, action.runId) !== 'running') return current;
			flow.queue.shift();
			if (head.op === 'settle') {
				if (head.eventId) emit(state, { kind: 'beat.settled', runId: action.runId, eventId: head.eventId });
			} else {
				land(state, action.runId, head.beat, true);
			}
			// The beat that just landed holds the next one back while it reveals or thinks.
			const hold = head.op === 'beat' ? holdFor(head.beat) : 0;
			if (hold && flow.queue[0]) flow.queue[0] = { ...flow.queue[0], delay: flow.queue[0].delay + hold };
			// The last beat of a turn still gets its hold, so the turn closes after the reply has revealed.
			else if (hold && statusOf(state, action.runId) === 'running') flow.queue.push({ id: nextId(state, 'op'), op: 'settle', delay: hold });
			settle(state, action.runId);
			return state;
		}
		case 'resolve':
		case 'answer': {
			const runId = state.view.pending.find((entry) => entry.request.id === action.requestId)?.runId;
			const run = runId ? state.view.runs[runId] : undefined;
			const flow = runId ? state.flows[runId] : undefined;
			// Only a run still held at this request picks back up; one stopped meanwhile stays stopped.
			if (!runId || !run || !flow || !awaitsPerson(run) || run.waitingOn.requestId !== action.requestId) return current;
			const resolution: RequestResolution = action.type === 'answer' ? { answer: action.answer } : { decision: action.decision };
			emit(state, { kind: 'request.resolved', runId, requestId: action.requestId, ...resolution });
			if (action.type === 'resolve' && action.decision === 'deny') {
				// A denied command is skipped along with its output, and the agent says so.
				if (flow.queue[0]?.op === 'beat' && flow.queue[0].beat.kind === 'shell') {
					flow.queue.shift();
					flow.played += 1;
				}
				flow.queue.unshift(op(state, { kind: 'notice', text: 'Command denied. Continuing without running it.', delay: 300 }));
			}
			settle(state, runId);
			return state;
		}
		case 'send': {
			const flow = state.flows[action.runId];
			if (!flow) return current;
			if (action.steer) emit(state, { kind: 'message', runId: action.runId, from: 'you', to: [action.runId], text: action.text, protocol: 'steer' });
			const status = statusOf(state, action.runId);
			const busy = status === 'running' || status === 'waiting';
			if (busy && !action.steer) {
				flow.queued.push({ id: nextId(state, 'queued'), text: action.text });
				return state;
			}
			const beats: SessionBeat[] = action.steer ? action.beats : [{ kind: 'user', text: action.text, delay: 0 }, ...action.beats];
			// Steering a busy run slots its reply in next; a resting run starts a new turn.
			flow.queue = busy ? [...beats.map((beat) => op(state, beat)), ...flow.queue] : beats.map((beat) => op(state, beat));
			if (!busy) setStatus(state, action.runId, 'running');
			return state;
		}
		case 'unqueue': {
			const flow = state.flows[action.runId];
			if (flow) flow.queued = flow.queued.filter((entry) => entry.id !== action.id);
			return state;
		}
		case 'stop': {
			if (!state.flows[action.runId] || isSettled(state, action.runId)) return current;
			stopRun(state, action.runId, action.runId === state.view.rootRunId ? 'Stopped. Send a message to pick it back up.' : 'Stopped.');
			return state;
		}
		case 'pause': {
			if (!state.flows[action.runId] || statusOf(state, action.runId) !== 'running') return current;
			setStatus(state, action.runId, 'paused');
			return state;
		}
		case 'resume': {
			if (!state.flows[action.runId] || statusOf(state, action.runId) !== 'paused') return current;
			setStatus(state, action.runId, 'running');
			return state;
		}
		case 'retry': {
			const flow = state.flows[action.runId];
			if (!flow || statusOf(state, action.runId) !== 'failed') return current;
			emit(state, { kind: 'beat', runId: action.runId, beat: { kind: 'notice', text: 'Retrying from the failed step.' } });
			// The step that failed runs again before whatever was left of the script.
			if (flow.lastStep && flow.lastStep.kind !== 'user') flow.queue.unshift(op(state, { ...flow.lastStep, delay: 500 }));
			setStatus(state, action.runId, 'running');
			settle(state, action.runId);
			return state;
		}
		case 'terminal':
			emit(state, { kind: 'terminal', runId: state.view.rootRunId, lines: action.lines });
			return state;
		case 'clear-terminal':
			emit(state, { kind: 'terminal.clear', runId: state.view.rootRunId });
			return state;
	}
}

/** What a control asks the host to do, or null for the ones that only ever touch the local script. */
function hostAction(control: ScriptAction, view: HarnessView, sessionId: string): CodingAgentAction | null {
	switch (control.type) {
		case 'send':
			return control.steer
				? { type: 'steer-run', sessionId, runId: control.runId, text: control.text, attachments: control.attachments }
				: { type: 'send', sessionId, text: control.text, attachments: control.attachments };
		case 'stop':
			// Stopping the session's own agent stops the session; any other agent stops on its own.
			return control.runId === view.rootRunId ? { type: 'stop', sessionId } : { type: 'stop-run', sessionId, runId: control.runId };
		case 'pause':
			return { type: 'pause-run', sessionId, runId: control.runId };
		case 'resume':
			return { type: 'resume-run', sessionId, runId: control.runId };
		case 'retry':
			return { type: 'retry-run', sessionId, runId: control.runId };
		case 'resolve': {
			const entry = view.pending.find((pending) => pending.request.id === control.requestId);
			if (entry?.request.type !== 'approval') return null;
			return { type: 'permission', sessionId, runId: entry.runId, requestId: control.requestId, decision: control.decision, command: entry.request.command };
		}
		case 'answer': {
			const entry = view.pending.find((pending) => pending.request.id === control.requestId);
			if (!entry) return null;
			return { type: 'answer', sessionId, runId: entry.runId, requestId: control.requestId, answer: control.answer };
		}
		default:
			return null;
	}
}

function rootRun(session: CodingSession): AgentRun {
	return { id: 'root', name: session.agentName ?? 'Agent', role: 'root', capabilities: { steer: true, stop: true } };
}

/** The session's own checkout and any worktrees it already knows about. */
function sessionWorktrees(session: CodingSession, branch: string): Worktree[] {
	const known = session.worktrees ?? [];
	if (known.length) return known;
	return [{ id: branch, branch, kind: session.location === 'worktree' ? 'worktree' : 'checkout' }];
}

function initialScript(session: CodingSession, files: Record<string, string>, branch: string, followUp: (text: string) => SessionBeat[]): ScriptState {
	const script = session.script ?? [];
	const state: ScriptState = { flows: {}, view: createHarnessView(rootRun(session), files, sessionWorktrees(session, branch)), nextId: 0, followUp };
	const root = state.view.rootRunId;
	state.flows[root] = newFlow();
	setStatus(state, root, 'running');
	const played = session.played ?? 0;
	for (const beat of script.slice(0, played)) land(state, root, beat, false);
	state.flows[root].queue = script.slice(played).map((beat) => op(state, beat));
	settle(state, root);
	return state;
}

/**
 * Times each running run's next step. Every head keeps the moment it became due, so one run landing a step never
 * restarts another run's wait.
 */
function useScheduler(state: ScriptState, dispatch: React.Dispatch<ScriptAction>) {
	const dueAt = React.useRef(new Map<string, number>());
	const heads = Object.entries(state.flows)
		.filter(([runId, flow]) => flow.queue[0] && state.view.runs[runId]?.status === 'running')
		.map(([runId, flow]) => ({ runId, op: flow.queue[0] }));
	// A paused or held run keeps its head and the moment it was due; a head that left its queue never will be.
	const queuedHeads = new Set(Object.values(state.flows).flatMap((flow) => (flow.queue[0] ? [flow.queue[0].id] : [])));
	const key = heads.map((head) => `${head.runId}:${head.op.id}`).join('|');
	React.useEffect(() => {
		for (const id of dueAt.current.keys()) if (!queuedHeads.has(id)) dueAt.current.delete(id);
		const now = performance.now();
		const reduced = prefersReducedMotion();
		const timers = heads.map(({ runId, op: head }) => {
			if (!dueAt.current.has(head.id)) dueAt.current.set(head.id, now + (reduced ? Math.min(head.delay, REDUCED_MOTION_DELAY) : head.delay));
			const wait = Math.max(0, (dueAt.current.get(head.id) ?? now) - now);
			return window.setTimeout(() => {
				dueAt.current.delete(head.id);
				dispatch({ type: 'due', runId, opId: head.id });
			}, wait);
		});
		return () => timers.forEach((timer) => window.clearTimeout(timer));
		// `key` captures the heads; the arrays themselves are rebuilt every render.
		// eslint-disable-next-line react-hooks/exhaustive-deps
	}, [key, dispatch]);
}

/** Reduces a host's events incrementally: an append-only log only folds what's new since the last render. */
function useHostView(events: readonly HarnessEvent[], initial: () => HarnessView) {
	const cache = React.useRef<{ events: readonly HarnessEvent[]; view: HarnessView } | null>(null);
	const cached = cache.current;
	let view: HarnessView;
	if (cached && cached.events === events) {
		view = cached.view;
	} else if (cached && events.length >= cached.events.length && (cached.events.length === 0 || events[cached.events.length - 1] === cached.events[cached.events.length - 1])) {
		// An append-only log: if the last event seen is still in place, only what came after it needs folding.
		view = events.slice(cached.events.length).reduce(reduceHarness, cached.view);
	} else {
		view = events.reduce(reduceHarness, initial());
	}
	cache.current = { events, view };
	return view;
}

/** What's coming next for a run, for its live status line. */
function upcoming(flow: Flow | undefined): SessionBeatKind | undefined {
	for (const entry of flow?.queue ?? []) if (entry.op === 'beat') return entry.beat.kind;
	return undefined;
}

/** Share of a run's script played so far, counting what it has been sent since. */
function playedShare(flow: Flow | undefined) {
	if (!flow) return 1;
	const total = flow.played + flow.queue.filter((entry) => entry.op === 'beat').length;
	return total ? flow.played / total : 1;
}

/** The host drives the session through its `events` log or `store`; without either, the session plays its script. */
export function isHosted(session: Pick<CodingSession, 'events' | 'store'>) {
	return Boolean(session.events || session.store);
}

/**
 * The session's harness: a scripted run for demos, or the host's `events` log or `store`. Either way the views get
 * one `HarnessView` and one set of controls. Every control reaches the host through `emit` as a `CodingAgentAction`;
 * a scripted session also plays it out, while in host mode nothing changes until the host answers with events.
 */
export function useHarness({
	session,
	files,
	branch,
	followUp,
	emit: emitAction
}: {
	session: CodingSession;
	files: Record<string, string>;
	/** The branch the session works on, for its checkout when `session.worktrees` doesn't name one. */
	branch: string;
	followUp: (text: string) => SessionBeat[];
	emit: (action: CodingAgentAction) => void;
}) {
	const host = isHosted(session);
	const [scripted, dispatch] = React.useReducer(scriptReducer, undefined, () => initialScript(host ? { ...session, script: [] } : session, files, branch, followUp));
	useScheduler(scripted, dispatch);
	const storeEvents = useHarnessStoreEvents(session.store);
	const hostEvents = session.events ?? storeEvents;
	const hostView = useHostView(host ? hostEvents : [], () => createHarnessView(rootRun(session), files, sessionWorktrees(session, branch)));
	const view = host ? hostView : scripted.view;

	const control = (action: ScriptAction) => {
		const forHost = hostAction(action, view, session.id);
		if (forHost) emitAction(forHost);
		if (!host) dispatch(action);
	};

	const changes = React.useMemo(() => Object.values(view.changes), [view.changes]);
	// Worktree rows only change with the worktrees, the changes or the runs, not with every step an agent takes.
	const { worktrees: worktreeMap, worktreeOrder, changes: changeMap, runOrder, runs } = view;
	const worktrees = React.useMemo(
		() => summarizeWorktrees(view),
		// The runs are read only for the worktree each works in, which is set when it spawns, so `runOrder` covers it.
		// eslint-disable-next-line react-hooks/exhaustive-deps
		[worktreeMap, worktreeOrder, changeMap, runOrder]
	);
	const tokens = React.useMemo(() => runOrder.reduce((sum, id) => sum + runTokens(runs[id]), 0), [runOrder, runs]);

	return {
		view,
		status: sessionStatus(view),
		progress: host ? undefined : playedShare(scripted.flows[view.rootRunId]),
		files: view.files,
		changes,
		worktrees,
		terminal: view.terminal,
		browse: view.browse,
		tokens,
		queued: (runId: string) => (host ? [] : (scripted.flows[runId]?.queued ?? [])),
		upcoming: (runId: string) => (host ? undefined : upcoming(scripted.flows[runId])),
		send: (runId: string, text: string, beats: SessionBeat[], attachments: string[] = []) => control({ type: 'send', runId, text, beats, attachments }),
		steer: (runId: string, text: string, beats: SessionBeat[], attachments: string[] = []) => control({ type: 'send', runId, text, beats, attachments, steer: true }),
		unqueue: (runId: string, id: string) => control({ type: 'unqueue', runId, id }),
		stop: (runId: string) => control({ type: 'stop', runId }),
		pause: (runId: string) => control({ type: 'pause', runId }),
		resume: (runId: string) => control({ type: 'resume', runId }),
		retry: (runId: string) => control({ type: 'retry', runId }),
		resolvePermission: (requestId: string, decision: PermissionDecision) => control({ type: 'resolve', requestId, decision }),
		answer: (requestId: string, answer: AskAnswer) => control({ type: 'answer', requestId, answer }),
		appendTerminal: (lines: { kind: 'command' | 'output' | 'error'; text: string }[]) => control({ type: 'terminal', lines }),
		clearTerminal: () => control({ type: 'clear-terminal' })
	};
}

export type SessionHarness = ReturnType<typeof useHarness>;
